/* ÇEVİRİ ja · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ja","olay",{
"OLAYLAR_EK5:1514-09-06:0":{"b": ["ヤヴズ・スルタン・セリムのタブリーズ入城", "dad2e227"], "d": ["チャルディランの勝利の後、オスマン軍はサファヴィー朝の首都タブリーズに入り、都市でスルタンの名でフトバが読まれた。セリムはここに1週間滞在し、タブリーズの芸術家とウラマーの一部をイスタンブルへ移住させた。この移住はオスマンの宮廷美術に深い影響を与えることになる。冬の接近とイェニチェリの不満により都市は放棄されたが、東方でのサファヴィーの優位は砕かれていた。地図上でこの日にオスマンに移った地が互いに隣接していないのは正しい:タブリーズは9日間の軍事占領である。エルズィンジャン平原は遠征中に無血で降伏し、その中央のケマフ城は1515年5月19日までサファヴィー側で抵抗した。スィイルトは、タブリーズでシャー・イスマーイールの獄から解放されたハサンケイフの領主ハリル・ベイがオスマンに服従してサファヴィー朝から取り戻した - その周辺のディヤルバクルは1515年まで、ハサンケイフは1517年までサファヴィーのままであった。", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["ムシュとビンギョル(Çapakçur)がサファヴィー朝からオスマンの統治に移った", "b0a53b5a"], "d": ["チャルディラーンの後、東アナトリアがサファヴィー朝から取られたことで、ムシュはヒジュラ暦921年/1515年にオスマンの統治に入った。隣のÇapakçur(ビンギョル)も同じ過程でオスマンに編入された。", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["ケマフ城のサファヴィー朝からの征服", "73fd8671"], "d": ["チャルディランからの帰途に冬をアマスヤで過ごしたヤヴズ・スルタン・セリムは、ユーフラテスの渡河点を押さえる堅固なケマフ城の征服をビユクル・メフメト・パシャに命じた。スルタンも自ら加わった包囲の末に城はサファヴィー朝の手から奪われ、東アナトリアの門が開かれた。この征服は、チャルディランの勝利を恒久的な領土の獲得に変える最初の具体的な一歩である。", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["トゥルナダー(Turnadağ)の勝利 - ドゥルカディル侯国、オスマンに服属", "fd879145"], "d": ["オスマン軍は、チャルディラン遠征の際に態度を曖昧にしたドゥルカディル侯アラーッデヴレ・ボズクルトを、ギョクスンとアンドゥルンの間のオルデクリの地で破り、アラーッデヴレはこの戦いで殺された。侯国はこの日には併合されなかった。アラーッデヴレの後、ドゥルカディル侯国の長にはヤヴズ・スルタン・セリムによってシェフスヴァルオウル・アリ・ベイが就けられ、マラシュ-エルビスタンを中心とする国はオスマンに服属する侯国として続いた。マムルーク朝との国境の緩衝地はこうしてオスマンの管理下に入り、2年後のエジプト遠征への道が開かれた。併合はアリ・ベイの殺害の後に行われることになる。", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["アーミド(ディヤルベクル)の征服とディヤルベクル総督領の設置", "a6867d5b"], "d": ["イドリース・ビトリースィーが地域のスンナ派クルド人ベイたちをオスマンの側につけた後、サファヴィー軍は長い包囲に耐えられず、アーミドの鍵はビユクル・メフメト・パシャに引き渡された。都市は新設のディヤルベクル総督領の中心とされた。こうして上メソポタミアの行政の核がオスマンの手に渡った。", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["ハルプトの征服 - ディヤルベクルへの道の開通", "564eb269"], "d": ["チャルディランの後に奪ったディヤルベクルをサファヴィーの包囲から救うため出発したカラマン総督ヒュスレヴ・パシャは、周辺を先にチェルケス・ヒュセイン・ベイが占領していたハルプト城を3日間の包囲の末に奪った。ユーフラテスの東でディヤルベクルへ至る道はこうして確保された。", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["コチヒサル(クズルテペ)の戦い - カラ・ハンの敗北", "9ea9e843"], "d": ["ビユクル・メフメト・パシャ率いるオスマン軍は、コチヒサル近くのデデ・ガルクン平原のコルク地で、サファヴィーの総督カラ・ハンを終日続いた野戦で破った。カラ・ハンの首は、スルタンの陣営に送られた。続いてオスマン軍はマルディン市に入ったが、数日で去った。サファヴィーの守備兵が守るマルディン城は1年後にようやく接収された。この勝利は、ヤヴズが南の国境を確保してエジプト遠征に向かうことを可能にした。同日に編入されたその他の地:パル、チェミシュゲゼク、シヴェレク。", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["ヤヴズ・スルタン・セリムのエジプト遠征のためのイスタンブル出発", "ac258b4b"], "d": ["ヤヴズ・スルタン・セリムは、表向きはサファヴィー朝に対する新たな東方遠征の準備として、イスタンブルを出発し、アクシェヒルを経て南に向かった。マムルーク朝のスルタン、カンスー・ガウリーがシャー・イスマーイールと接触してオスマンの東翼を脅かしたことが、目標をまもなく変えさせることになる。遠征は2年続き、オスマンを中東の帝国に変える大作戦の始まりである。", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["ザビードの奪取:オスマンの海の者たちの紅海への最初の進出", "38740e0c"], "d": ["ポルトガルのインド洋での圧力に対し、マムルーク朝のスルタン、カンスー・ガウリーの要請で紅海に派遣されたオスマン出身の海の者フサイン・ベイとサルマン・レイスは、艦隊でザビードを占領した。なおマムルーク朝の下で行われたこの作戦は、オスマン海軍の紅海-インド線における最初の事実上の存在である。1年後にエジプトがオスマンに移ると、この艦隊は直接イスタンブルに属することになる。", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["遠征の目標がマムルーク朝とアレッポであることの正式な宣言", "689e310d"], "d": ["ヤヴズ・スルタン・セリムは、カンスー・ガウリーがサファヴィー朝と協定して軍をアレッポに進めたことを受け、遠征の目標をマムルーク朝のスルタンとアレッポであると公然と宣言した。こうして二つのスンナ派国家の間で長年続いた隠れた競争は、公然たる戦争に変わった。この宣言は、マルジュ・ダービクへの4週間のカウントダウンを始めた。", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["アデン攻囲の失敗:ポルトガルに対する最初の紅海での試み", "8ffd46f2"], "d": ["サルマン・レイスとフサイン・ベイは、紅海のインド洋への門であるアデンを奪うため8日間にわたる攻囲を行ったが、都市の強力な防備の前に撤退せざるを得なかった。アデンを奪えなかったことは、ポルトガルに対する南方戦略を長年妨げることになる。この試みは、オスマンの海洋政策における最初の試練である。", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["ラマザン侯国のオスマンへの帰属", "cfaa3754"], "d": ["マルジュ・ダービクの勝利の後に行われた任命の際、アダナを中心とするラマザン侯国はマフムト・ベイに与えられ、オスマンの宗主権下に置かれた。マムルーク朝への臣従を離れた侯国は、廃止されるのではなく「オジャクルク」の地位で一族に委ねられた。ラマザン家はチュクロヴァの統治を、オスマンのサンジャク・ベイとして続けた。この特権的な制度は、ピール・マンスールが侯位を離れた1608年まで続いた。同日に編入されたその他の地:マラティヤ、タルスス、モスル、アンテプ。", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["アレッポ、ラッカ、デイルッゾールのオスマン支配への編入", "2088eb6a"], "d": ["マルジュ・ダービクの4日後、ヤヴズ・スルタン・セリムは抵抗を受けずにアレッポに入り、都市のモスクでは彼の名でフトバが読まれた。シリアの商業と行政の首都とされるアレッポがこれほど早く陥落したことは、地域でマムルーク朝の権威が崩れていたことを示す。都市の奪取により、ダマスクスへ、そしてそこからエジプトへ至る道が一気に開かれた。同日に編入されたその他の地:アンタキヤ、ラッカ、デイルッゾール。", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["アレッポのギョクメイダンでアッバース朝カリフ、ムタワッキル3世との会見", "22979f42"], "d": ["マルジュ・ダービクでマムルーク軍とともに捕虜となったカイロのアッバース朝カリフ、ムタワッキル3世は、アレッポのギョクメイダンでスルタンの御前に引き出され、ヤヴズ・スルタン・セリムは彼に大きな敬意を示した。1261年からマムルーク朝のスルタンの影で象徴的な地位にあったカイロのカリフ位は、この会見で事実上オスマンの保護下に移った。カリフはのちにスルタンとともにイスタンブルへ連れて行かれることになる。", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["トリポリ(トラブルスシャーム)とハマー、オスマンの統治下に入る", "a1e19a79"], "d": ["アレッポとハマーに続き、シリア沿岸のトリポリも抵抗せずにオスマンの統治に移った。東地中海で最も繁華な港の一つであった同市はダマスクスの海への門であり、絹と砂糖の交易の中心であった。その奪取により、ビラード・アッシャームの沿岸帯はすべて手を替えた。", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["ダマスクスのオスマン支配への編入", "2b844d91"], "d": ["アレッポの後、ハマーとホムスが降伏して前途が開けたヤヴズ・スルタン・セリムは、9月27日にダマスクスの前に達した。都市にはすぐに入らず外のマスタバの地に幕営を張り、到着の12日目に盛大な儀礼とともに入城した。ダマスクスに長く滞在してシリアの行政秩序を整え、ムヒッディーン・イブン・アラビーの墓廟を建てさせた。こうしてビラード・アッシャームの全域がマムルーク朝の統治を離れた。同日に編入されたその他の地:ベイルート。", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["トゥーマーンバーイ、カイロでマムルーク朝のスルタンとして宣言される", "6020d90d"], "d": ["マルジュ・ダービクで死んだカンスー・ガウリーの後、マムルークのエミールたちは、国家の最後のスルタンとなるトゥーマーンバーイを王位に就けた。チェルケス出身の新スルタンは、シリアを失い、国庫が尽き、火器を欠く国家を引き継いだ。それにもかかわらず、カイロの前に防衛線を築き、オスマンの進出に対する最後の抵抗を組織することになる。", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["ガザ(ハン・ユーヌス)の戦い:ジャーンビルディー・ガザーリーの敗北", "9f1eb8cb"], "d": ["ヤヴズ・スルタン・セリムは、4千人の先遣隊とともに大宰相ハドゥム・スィナン・パシャをガザに送った。トゥーマーンバーイによってダマスクス総督に任じられたジャーンビルディー・ガザーリーは、オスマンの先遣隊をガザ-ハン・ユーヌス線で止めようとしたが、大敗してエジプトに逃れた。パレスチナにおける最後のマムルーク朝の緩衝軍が解体したことで、シナイ砂漠への道は完全に開かれた。", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["ヨルダン川の東:アンマン、オスマンの統治下に入る", "9db62667"], "d": ["ガザの戦いの後、エジプト遠征の準備をしていたオスマン軍が南下するなか、ヨルダン川東方のアンマンもオスマンの統治下に入った。パレスチナの沿岸および内陸の都市(ヤッファ、ナーブルス、サイダ、アッカ、エルサレム)は、マルジュ・ダービクの後の1516年秋にすでに手を替えていた。これらの都市は4世紀にわたり、ダマスクス州のサンジャクとして統治された。", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["ヤヴズ・スルタン・セリムのエルサレム到着", "66d7bfad"], "d": ["マルジュ・ダービクの後に抵抗せずオスマンの統治に移っていたエルサレムに、ガザの戦いの後、ヤヴズ・スルタン・セリムが国の要人と軍とともに来た。スルタンは岩のドームとアクサー・モスクを訪れ、都市の聖なる地位を確認した。エルサレムはこの日から1917年12月まで、ちょうど4世紀にわたりオスマンの統治下に留まることになる。", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["ヤヴズ・スルタン・セリムのガザ入城とシナイ砂漠への進発", "2106bfc7"], "d": ["ハン・ユーヌスでジャーンビルディー・ガザーリーが敗れた(1516年12月21日)後、ガザは先遣隊の手にあった。スルタンは1517年1月2日にガザに入り、ここで先遣隊の長スィナン・パシャと合流し、軍はエジプト渡河の最後の準備をした。ガザからサーリヒーヤに至る水のないカティヤ(シナイ)砂漠では8宿を歩き、水はラクダで運ばれることになった。この渡河は、遠征で最も危険で、兵站の面で最も困難な局面である。", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["スエズの奪取 - 紅海への門", "05f3324e"], "d": ["リダニーヤでの勝利の後、オスマン軍がカイロに入ると、紅海北端のスエズもオスマンの統治下に入った。マムルーク朝がインド洋へ艦隊を派遣した造船所兼港であるこの地は、ポルトガルに対する南方政策の拠点となった。スエズは、3世紀後に運河が開かれる線の北の口である。", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["オスマン軍のカイロへの最初の入城", "0a3f4f4d"], "d": ["リダニーヤの勝利の翌日、オスマン軍のカイロ入城が許可され、1月24日に部隊は都市に駐屯した。しかしこの入城は都市の完全な掌握を意味しなかった。トゥーマーンバーイは上エジプトに退き、マムルーク朝の抵抗はまだ折れていなかった。カイロの征服は一日ではなく、数週間にわたる血なまぐさい過程で完成することになる。", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["トゥーマーンバーイのカイロ急襲と3日間の市街戦", "b83b6ce6"], "d": ["上エジプトに退いていたトゥーマーンバーイは、7千人ほどの手勢とともに1月27-28日の夜に突然カイロに入って市内で抵抗を始め、オスマン軍を極めて苦しい状況に陥れた。3日間続いた激しい市街戦で、マムルーク軍は都市の大部分を一時的に手中に収めた。抵抗はオスマンの砲兵と増援部隊が投入されてようやく砕かれた。", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["ジャーンビルディー・ガザーリーのオスマン仕官", "a94ea459"], "d": ["リダニーヤの後にサーリヒーヤに退いた元マムルークのエミール、ジャーンビルディー・ガザーリーは、スルタンに申し出て助命を乞うた。ヤヴズ・スルタン・セリムは、エジプトとシリアの治安確立に役立つと考えて彼を召し抱えた。この選択は、オスマンがマムルークの人材を一掃する代わりに体制に取り込む政策の最初の大きな例である。", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["ヤヴズ・スルタン・セリムの盛大なカイロ入城とフトバの読誦", "6d98080c"], "d": ["市街戦の鎮圧後、スルタンは1517年2月15日に極めて華やかな式典とともにカイロに入り、モスクで彼の名でフトバが読まれた。カイロでオスマンのスルタンの名でフトバが読まれたことは、1250年から続いたマムルークの支配が法的に終わったことの宣言である。この日付は、エジプトの事実上の征服の象徴的な完成の瞬間とされる。", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["最後のマムルーク朝スルタン、トゥーマーンバーイのテッルージェでの捕縛", "7058e6ad"], "d": ["カイロを離れた後ナイル・デルタに潜んでいたトゥーマーンバーイは、彼をかくまったベドウィンに密告され、テッルージェ地方で捕らえられた。その捕縛はマムルークの抵抗の組織的な中心を消した。最後のスルタンは以後14日間、オスマンの手に留め置かれることになる。", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["トゥーマーンバーイのバーブ・ズウェイラでの処刑とマムルーク朝の終焉", "ad9820be"], "d": ["捕縛から14日後、トゥーマーンバーイはカイロの有名な門バーブ・ズウェイラで絞首され、遺体は後に叔父が建てさせたメドレセに葬られた。こうして1250年からエジプトとシリアを支配したマムルーク朝は正式に歴史から消えた。抵抗が砕かれたことで、上エジプト(サイード)のアスユートやアスワンなどの都市もオスマンの統治下に組み込まれた。", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["ポルトガル艦隊のジッダ襲撃とサルマン・レイスの防衛", "52322cf5"], "d": ["30隻ほどのガレー船とガレオン船からなるポルトガル艦隊がジッダを襲撃した。サルマン・レイスは都市の防衛を指揮して敵の上陸を阻み、ポルトガル船数隻を沈めた。この防衛は、メッカの港、ひいては巡礼路がキリスト教国の手に渡ることを防いだ。ジッダは数か月後、ヒジャーズの臣従によって正式にオスマンの統治に入ることになる。", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["アレクサンドリアの艦隊による接収 - エジプト征服の完了", "386878fe"], "d": ["リダニーヤからちょうど4か月、トゥーマーンバーイの処刑から36日後に、ジャーフェル・ベイ指揮下のオスマン艦隊が港に着くとアレクサンドリアはオスマンの統治に移り、ロゼッタやダミエッタといったデルタの港もこの過程で組み込まれた。エジプトの地中海への大きな港が、カイロの陥落から数か月後に、陸からではなく海から接収されたことは、征服が一度の戦いではなく地域ごとに完成されたことを如実に示している。アレクサンドリアはこれ以後、イスタンブルとカイロを結ぶ生命線の港となる。同日に編入されたその他の地:ロゼッタ(Reşîd)。", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["ヒジャーズの無血編入:メッカのシャリーフの子アブー・ヌマイイの忠誠の誓い", "c13b98c7"], "d": ["ヤヴズ・スルタン・セリムは当初メッカとその周辺の占領のため兵を送ることを考えていたが、メッカのエミール、シャリーフ・バラカートが服従を表明したため、これを取りやめた。バラカートの12歳の子アブー・ヌマイイは、父の贈り物とメッカの鍵を携えてカイロに来て、スルタンの御前に受け入れられた。こうしてヒジャーズは、リダニーヤの自動的な帰結としてではなく、5か月半後に、一発の銃弾も撃たれることなく、平和裡に忠誠の誓い(バイア)によってオスマンに編入された。同日に編入されたその他の地:ターイフ。", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["「二聖都の奉仕者」称号の受諾とメディナでのフトバ", "63b32b59"], "d": ["メッカの使節団の二度目の謁見の後、ヤヴズ・スルタン・セリムは二聖都の保護を正式に引き受け、「ハーディム・アル=ハラマイン・アッシャリーファイン(二聖都の奉仕者)」の称号を用い始めた。シャリーフ・バラカートは送られた礼服を着てスルタンの名でフトバを読ませ、メディナの使節団もイスタンブルへ行くと、バラカートのエミール位は勅許状で承認された。スルタンは二聖都の人々に20万金貨と大量の食糧を送り、毎年繰り返されるスッレの慣習を始めさせた。同日に編入されたその他の地:ヤンブー、タブーク。", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["サルマン・レイスのオスマン仕官と紅海政策の引き継ぎ", "771da99a"], "d": ["ジッダをポルトガル人から守ったサルマン・レイスは、カイロに来てヤヴズ・スルタン・セリムの御前に出た。しばらく留め置かれたが、1519年にイスタンブルに召され、ポルトガルの脅威に対してガレー船30隻ほどと数隻のガレオン船を準備することを請け合った。この会見は、紅海とインド洋の政策がマムルークの遺産から引き継がれ、直接イスタンブルに結びつけられることの始まりである。オスマンはもはや地中海国家であるのみならず、大洋政策をも推進する勢力であった。", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["ヤヴズ・スルタン・セリムのカイロ出発とハイル・ベイの総督就任", "8cd4fb23"], "d": ["エジプトに約8か月滞在して行政・財政・軍事の秩序を整えたヤヴズ・スルタン・セリムはカイロを発った。マルジュ・ダービクで左翼を引き上げてマムルークの敗北を早めた元アレッポ総督ハイル・ベイは、エジプトの最初のオスマン総督として、カルアト・アル=ジャバルから統治を始めた。マムルーク出身の総督が選ばれたことは、新しい統治が地元の人々に異質に映らないようにするための意図的な移行政策であった。スルタンは帰路、最後のアッバース朝カリフ、ムタワッキル3世と、エジプトの卓越した芸術家や学者たちをイスタンブルへ連れて行った。", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["カイロのアッバース朝カリフ制の終焉 - 「移譲式」伝承", "1d357640"], "d": ["ヤヴズ・スルタン・セリムはエジプトを征服すると、マルジュ・ダービクで捕虜となった最後のカリフ、ムタワッキル3世・アラッラーをイスタンブルへ連れて来た。1261年からマムルーク朝のスルタンの影で権限なく存続してきたカイロのアッバース朝カリフ制はこうして終わった。これに対し、カリフ位がアヤソフィアで正式な式典によってヤヴズに譲られたという有名な伝承は、18世紀末のドーソンの著作に初めて現れ、ヤヴズ時代の史料にはまったく見られない。TDV『イスラーム百科事典』は式典を裏づける原史料がないことからこの伝承を作り話とみなすが、同時に、カリフ位の移転にシャリーア上そのような移譲式は必要なかったことも記している。", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["エルズルム、オスマンの統治に編入 - 東アナトリアでサファヴィーの影響力が砕かれる", "78d1be02"], "d": ["チャルディランの勝利(1514年)の後、地域でのオスマンの影響力は強まったが、エルズルムの完全な掌握はイランの影響力が砕かれるまで遅れた。都市はエジプト遠征の後の1518-19年にようやくオスマンの統治に編入された。エルズルムは1502年にシャー・イスマーイールがアク・コユンル侯国を滅ぼしたことでサファヴィーの支配に入っていた。16年に及ぶこの時期はこうして閉じた。1534年のイラクェイン遠征の際にエルズルム総督領が設置されることになる。1518-1519年の間にエルズルム地方とともにアシュカレもオスマンの統治に編入された(日付未確認)。", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["ジェラーリーの反乱の始まり:ボゾクのシェイフ・ジェラールの蜂起", "99bd8a99"], "d": ["ボゾク地方でシェイフ・ジェラールという人物がマフディーを名乗ってトカト周辺で蜂起した。反乱は鎮圧されたが、その名は1世紀にわたりアナトリアのあらゆる匪賊と蜂起運動の呼び名となった。ジェラーリー運動は、16世紀末にティマール制の崩壊と人口圧力が重なって、帝国で最も長く続いた国内治安問題に変わった。蜂起は、アナトリアで「大逃散(ビュユク・カチュグンルク)」と呼ばれる大規模な人口移動を引き起こした。", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["アルジェのオスマン国家への編入", "b8eba4c1"], "d": ["北アフリカでスペインの圧力に抵抗していたハイレッディン・レイスは、持ちこたえるためにイスタンブルに申し出てアルジェをスルタンに献上し、フトバはヤヴズ・スルタン・セリムの名で読まれた。こうしてアルジェは正式にオスマン領に編入され、ハイレッディンには総督の称号とともに兵と大砲が送られた。この編入は、オスマンの西地中海における数世紀続く海上支配の礎を築いた。同日に編入されたその他の地:コンスタンティーヌ、シェルシェル(Cherchell)、メデア(Titteri)、セティフ。", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["ヤヴズ・スルタン・セリムのチョルルでの死去", "9fe83744"], "d": ["8年で国土を2倍以上に広げたセリム1世は、1520年7月18日に新たな遠征のためイスタンブルを出たが、背中にできた大きな腫瘍のためチョルルから先へ進めなかった。医師たちの処置にもかかわらず病は重くなり、2か月続いた望みのない治療の後、926年シャウワール月8-9日(1520年9月21-22日)にこの地で没した。チャルディラン、マルジュ・ダービク、リダニーヤによってイランを食い止め、マムルーク朝を滅ぼし、カリフ位と二聖都の保護者の地位をオスマンにもたらした。残した男子は一人だけ:スレイマンである。", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["イカリア(Nikarya)島のオスマン統治への編入", "6afa972b"], "d": ["サモスとキオスの間にあるイカリア(Nikarya)は、1481年から1521年までロドスの聖ヨハネ騎士団の統治下にあった。島での最初のオスマン時代は1522年に始まり、1822年まで続いた。この時代には税の徴収と納付の責任はカイマカムが負い、他のエーゲ海の島々と同様に、地元の長老会議(デモゲロンティア)も存続し、時にオスマンの統治と衝突した。", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["ドゥルカディル侯国の併合 — マラシュを中心とするドゥルカディル州", "595c3c30"], "d": ["1515年のトゥルナダー敗北の後、オスマンに従属する侯国として続いていたドゥルカディルの国は、Şehsuvaroğlu Ali Beyがアルトゥコヴァで子供たちとともに殺されたことを受けて、直接オスマンの領土に編入され、マラシュを中心とする州とされた。侯国のボゾク地方は別個のサンジャクとしてオスマンの統治に結びつけられた。こうしてマラシュ、エルビスタン、ギョクスン、ギュルン、ザマントゥ、ダレンデの約2世紀にわたるドゥルカディル侯国の時代は閉じられ、マムルーク朝との国境にあった緩衝侯国は完全に消えた。", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["クニンの征服", "a46d3117"], "d": ["ボスニアのサンジャク・ベイGazi Hüsrev Beyのヒジュラ暦927から928年(1521年から1522年)の襲撃によって、クニン、スクラディン、Ostrovicaをはじめとする一連のヴェネツィアの要塞がオスマンの統治に移り、国境は第二の山脈の向こうに押された。この征服の連鎖は、15年後のクリスの占領で完成するダルマチア・サンジャクの基礎を築いた。", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["騎士団の撤退:ボドルム、コス、ドデカネスの引き渡し", "ea01666e"], "d": ["ロドスの降伏条件により、聖ヨハネ騎士団は島の中心部だけでなく、200年間保持してきたすべての拠点を空けた。アナトリア海岸のボドルム(サン・ピエール)要塞と、コス島、Kelemez、İleryozの島々は、こうして戦闘なしにオスマンの統治に移った。ロドスの陥落から2週間後に完了したこの引き渡しによって、エーゲ海の南東の隅におけるラテン人の存在は完全に終わった。", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["エジプトでの裏切り者アフメト・パシャの反乱", "b18bb805"], "d": ["大宰相の座を待ちながらエジプト総督に送られたアフメト・パシャは、カイロで自らを「アル=マリク・アル=マンスール・スルタン・アフメト」と宣言し、独立を表明した。反乱は短期間で鎮圧されてパシャは殺されたが、この事件は帝国で最も豊かな州における中央の統制の脆さを示した。これを受けてイブラヒム・パシャはエジプトに赴き、州の統治を再編する有名なエジプト法令集(カーヌーンナーメ)を作らせた。", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["北ボスニアの併合:ヤイツェとバニャ・ルカ", "8ec86cfa"], "d": ["モハーチの後、ハンガリーの防衛線が崩れると、ボスニアのサンジャク・ベイGazi Hüsrev Beyはヴルバス川流域に進軍し、ハンガリー王国の手に残る最後のボスニアの要塞を取った。ヤイツェとバニャ・ルカの陥落によって、ボスニア州は北でサヴァ川に達し、クロアチア戦線が生まれた。バニャ・ルカはまもなく州の第二の中心となった。", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["ブダの奪取とサポヤイへの引き渡し", "fba4f89b"], "d": ["ウィーン遠征の途上、オスマン軍はフェルディナントの手に渡っていたブダを包囲して奪い返し、都市をオスマンの保護下のハンガリー王ヤーノシュ・サポヤイに引き渡した。こうしてハンガリーをめぐるハプスブルク-オスマンの競合において、緩衝となる臣従王国のモデルが築かれた。この秩序は1541年まで続き、サポヤイの死後、ブダは直接オスマンの州とされることになる。", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["カーヌーニー、ドイツ遠征に出発 - カール5世への挑戦", "7c3d7055"], "d": ["ウィーン包囲が成果なく終わったことと、フェルディナントがブダを再び包囲したことの後、スルタンは今度は直接皇帝カール5世を野戦に引き出すため、イスタンブルから出発した。軍は8月に小さなギュンス城の抵抗に足止めされ、皇帝が出戦しなかったため、遠征は襲撃にとどまることになる。遠征は翌年のハプスブルクとの最初の和平の下地を整えた。", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["ドイツ遠征とギュンス(Kőszeg)の攻囲", "8aec937a"], "d": ["カーヌーニーはカール5世を野戦に追い込むため軍とともにオーストリアに進軍した。小さなギュンス城は25日間抵抗して軍の進出を遅らせた。皇帝が出戦しなかったため、騎兵(アクンジュ)がウィーン周辺を襲い、季節の進行により引き返した。遠征は領土の獲得をもたらさなかったが、ハプスブルクを交渉の席に着かせ、翌年の和平の下地を整えた。", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["イスタンブル条約 - ハプスブルクとの最初の和平", "b085767a"], "d": ["フェルディナントの使節コルネリウスを迎えたスルタンは休戦に同意し、オスマンとオーストリアの間で最初の公式な和平文書が成立した。条約によりフェルディナントは保持するハンガリー領に対し年貢を払うことを受け入れ、オーストリア大公は儀礼上、大宰相と同格とされた。この不平等な地位は、16世紀におけるオスマン外交の優越の主張をはっきり表すものであった。", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["カルスの占領と北東国境の開通", "742e3101"], "d": ["両イラク遠征(Irakeyn Seferi)の先鋒がエルズルムから東に向かうなか、グルジアのアタベク国の手にあり、ティムール以来荒廃していたカルス要塞は、抵抗もなく受け取られた。都市は、アラス川の湾曲部とチルドゥルの間の通路を押さえるため、イランに開く北の門の鍵とされていた。この獲得は、30年後に設けられるカルス・ベイレルベイ領とコーカサス線の最初の環となった。", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["タブリーズへの最初の入城 — 両イラク遠征の開幕", "cf7ed4e3"], "d": ["大元帥(セルダール・イ・エクレム)の資格で先行したイブラヒム・パシャは、シャー・タフマースブが野戦を避けて内陸に退いたため、サファヴィー朝の首都タブリーズに抵抗なく入った。カーヌーニーも9月に都市に達したが、冬の到来と補給線が長くなりすぎたため、軍はバグダードの方向に向かい、タブリーズは長く保持できなかった。チャルディラーンの後、二度目に占領されたこの都市は、オスマンが東方で占領するのは易しく保持するのは難しいと学んだ場所となった。", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["バルバロスのチュニス征服", "d8754216"], "d": ["海軍総司令官バルバロス・ハイレッディン・パシャは、艦隊でイタリア沿岸を攻撃した後チュニスに向かい、ハフス朝の君主ムーレイ・ハサンを逃亡させて都市に入った。チュニスの奪取は、シチリア海峡を押さえる位置ゆえに、西地中海の力の均衡を一気にオスマン有利に変えた。しかしこの支配は長続きせず、カール5世が翌年、大艦隊で応じることになる。", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["チュニスのカール5世への喪失", "a691f0f8"], "d": ["カール5世は、ジェノヴァと教皇庁の艦隊に支援された大遠征でハルク・アル=ワード(ラ・グレット)を陥落させた後、チュニスを奪い、ムーレイ・ハサンをスペインの保護下に王位に復した。都市にはスペイン守備隊が置かれ、オスマンの中部地中海での進出は一時的に止められた。チュニスの最終的な征服は、40年後の1574年にようやく可能となる。", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Gazi Hüsrev Beyのサヴァ川沿いの作戦:ボスニア・ブロドとヤセノヴァツ", "3740ec83"], "d": ["1528年のヤイツェとバニャ・ルカの占領の後も、サヴァ川沿いの要塞はしばらくハプスブルク王冠に属するクロアチア・スラヴォニア国境に残った。1536年に三度目のボスニアのサンジャク・ベイとなったGazi Hüsrev Beyは、同年にポジェガとその周辺を占領するとともに、サヴァ河岸のブロドとヤセノヴァツの要塞もオスマンの統治に加えた。こうしてボスニアの北の国境はサヴァに達した。地域は2年後のドゥビツァの占領で完成した。", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["マクブル・イブラヒム・パシャの処刑", "348aa7b8"], "d": ["13年間大宰相を務め、カーヌーニーの最も親しい友であり国家の事実上のナンバー2であったイブラヒム・パシャは、断食明けの食事(イフタール)に招かれた宮殿で、何の理由も示されないまま絞殺され処刑された。イラクェイン遠征での態度、「セラスケル・スルタン」の称号の使用、宮廷内の力関係が死に影響したとされる。この処刑は、オスマンの中央政府において大宰相に絶対の安全がないことを示す転機である。", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["クリス城の征服とダルマチア・サンジャクの設置", "6ffd4ebf"], "d": ["ガーズィー・ヒュスレヴ・ベイの家令(ケトヒュダー)で、クロアチア出身の改宗者ムラト・ベイは、スプリットのすぐ北にある戦略上の要衝クリス城をヴェネツィアから奪った。征服の直後、クリスは周辺を含む新しいサンジャクとカザーの中心とされ、このサンジャクの境界はオスマン領クロアチアの枠組みをおおむね描いた。クニンから15年後に来たこの征服は、ダルマチア内陸の行政の骨格を完成させた。", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["コルフ攻囲とヴェネツィアとの戦争", "11af95bd"], "d": ["プーリア(アプリア)遠征の後、オスマン軍はコルフに上陸し、島の堅固なヴェネツィアの城を包囲した。城の険しい構造、大きな損害、季節の条件のため、9月6日に封鎖を解いて撤退した。攻囲は成果なく終わったが、ヴェネツィアとの間に始まった戦争は、エーゲ海とアドリア海の多数の島のオスマンへの編入と、翌年のプレヴェザの勝利に終わった。", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["バルバロスのエーゲ遠征:ヴェネツィアが直接統治する島々の占領", "1b32ed96"], "d": ["コルフ島の包囲から戻った艦隊は、ヴェネツィアに戦争が宣言されていたことを利用して、エーゲ海で公国にではなく直接ヴェネツィアに属する島々を一つずつ受け取った。アイギナは激しい抵抗の後に占領され、Querini家の手にあったアスティパレアとカルパトス、カソスは降伏し、修道院の統治下にあったパトモスもオスマンの保護を受け入れた。ナクソス公国は年貢を課されたうえでそのまま残された。その併合は1566年を待つことになる。", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["バルバロスの北エーゲ遠征:スキロスと北スポラデス諸島の占領", "20ab688e"], "d": ["プレヴェザへ向かう途上で、艦隊は、イスタンブル征服後にヴェネツィアに逃れていた北エーゲ海の島々を一つずつ受け取った。エヴィア島の北のスキロスと、テッサロニキ湾の口を押さえるスキアトス、スコペロス、アロニソスがこうしてオスマンの統治に入った。これらの島は、エヴィア島が1470年に占領されていたにもかかわらずさらに68年間ヴェネツィアの手に残っていた、北エーゲ海最後の空白を埋めた。", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["アデンの占領とイエメン海岸の併合", "e7d46d8f"], "d": ["インド遠征のためスエズから出た艦隊は、紅海の安全を確保せずに大洋に出ることはできないため、まずイエメン海岸に向かった。Hadım Süleyman Paşaは1538年8月3日にアデン港に入った。ポルトガル人に傾いていたターヒル朝の君主Âmir b. Dâvudは艦長の門に連れてこられて処刑され、都市には500人の守備隊が置かれた。同じ遠征の間に、モカと海峡を支配するカマラン島とFerasan島も引き渡され、イエメン・ベイレルベイ領の礎が築かれた。こうしてオスマン帝国は初めてバブ・エル・マンデブ海峡の北岸全体を掌握した。サナアと内陸部はさらに9年待たねばならなかった。", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["モルダヴィア遠征とブジャク(ベンデル)地方の併合", "90a88a56"], "d": ["オスマンへの義務を果たさなかったモルダヴィア公ペトル・ラレシュに対する遠征でスチャヴァが占領され、ヤシの町はクリム・ハンのサーヒブ・ギレイによって略奪された。スルタンはチェキルゲ・ステファンを公位に就け、ベンデルとともにブジャク(南ベッサラビア)地方を直接オスマン領に編入した。この併合は、黒海北西岸をオスマンの内海に変える環の一つとなった。モルダヴィアはすでにオスマンに服属する公国であった。この遠征は土地を外国の国家から取ったのではなく、ベンデルとブジャクの内政を公から取ってスルタンに直接結びつけただけであり、公国の残りは服属の地位を保った。同じ構造は1484年のキリアとアッケルマン、1713年のホティンでも繰り返されることになる:国境の城塞は直接、内陸は服属。", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["ナフプリオ(Anabolu)の協定による引き継ぎ", "104d0937"], "d": ["プレヴェザの後、3年続いたヴェネツィアとの戦争は、共和国がモレアに残る最後の二つの要塞を手放すことに同意して終わった。包囲では奪えなかったナフプリオ(Anabolu)とモネンヴァシア(Benefşe)は、30万ドゥカートの戦争賠償に加えて、交渉の席でオスマン帝国に譲渡された。モレア半島はこうして、ヴェネツィアの足跡が一つも残らない形でまとまった。", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["セゲドのオスマン統治への編入とセゲド・リヴァーの編成", "019aa000"], "d": ["ブダにおけるオスマンの統治が1541年に完全に確立された後、セゲドの有力者たちはフェルディナント1世の支配を受け入れ、武装防衛の準備をした。ブダのベイレルベイKüçük Bâlî Paşaは1543年の初めに都市の指導者たちを呼び寄せて反逆を理由に処刑させ、続いて都市を占領するために部隊を送った。このときセゲド・リヴァー(サンジャク)が編成され、最初のサンジャク・ベイにはBâlî Paşaの息子Derviş Beyが任命された。リヴァーは当初ドナウ川とティサ川の間に広がっていた。", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Valpo、Şikloş、Peçuy(ペーチ)の征服", "2ca030a3"], "d": ["ブダの併合の2年後に出陣したハンガリー遠征の最初の目標は、新しい州のドラヴァ川とドナウ川の間の南側面を確保することであった。Valpo要塞とŞikloş要塞が占領された後、バラニャ地方の中心Peçuyが降伏した。都市はオスマン・ハンガリーで最も人口が多く最も整備された中心地となり、歴史家İbrahim Peçuylu(ペーチ出身のイブラヒム)の名もここに由来することになる。", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["エステルゴムとイストルニ・ベオグラードの征服", "efca9e05"], "d": ["カーヌーニーが自ら出たハンガリー遠征で、2週間半の包囲の後、ハンガリー王国の宗教的中心で大司教座の都市エステルゴムがオスマンの統治に入った。続いてハンガリー王たちの戴冠の都市イストルニ・ベオグラード(Székesfehérvár)も奪われ、ブダ州の防衛帯が完成した。エステルゴムは1595年までドナウ線の要衝の城としてオスマンの手に残ることになる。", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["ブダの北と西の防衛帯:ヴァーツ、ハトヴァン、Şimontorna", "733ee5ce"], "d": ["エステルゴムとセーケシュフェヘールヴァールが取られた後、ブダのベイレルベイは、首都を取り巻く要塞の環を完成させるため、スルタンの遠征なしに行動を起こした。ドナウの湾曲部にあるヴァーツ、アルフェルドの門であるハトヴァン、シオ川線のŞimontornaが一つずつ引き渡された。この静かな年の獲得は、ブダを辺境の都市から、140年持ちこたえる州の中心へと変えた。", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["バスラの併合とペルシア湾への進出", "02f87c11"], "d": ["バグダード征服(1534年)の際にバスラの君主Râşid b. Megāmisはカーヌーニーへの服従を表明し、1538年には都市の鍵を送っていた。後を継いだシェイフ・ヤフヤーがオスマンに敵対すると、バグダードのベイレルベイAyas Paşaが陸から、モスルのサンジャク・ベイが120隻の船でユーフラテスから進軍した。Ayas Paşaは1545年12月26日にバスラに入り、都市はベイレルベイ領の中心となった。シャットゥルアラブの河口にあるこの港は、ポルトガルがホルムズから支配していたペルシア湾にオスマンが開いた門であり、1555年のアマスヤ条約でイランもこの状況を承認した。", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["サナアとイエメン内陸の征服", "d31ded85"], "d": ["ターイズに続いてサナアも取られ、国の全体がベイレルベイ領に結びつけられた。しかし険しい地形と宗派の違いのため、この支配は決して安楽なものにはならなかった。イエメンは、オスマンにとって絶えず兵を飲み込む戦線となった。", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["ターイズの征服", "d4509df9"], "d": ["9年前には海岸の帯状地帯だけで満足していたイエメンで、ザイド派のイマームたちが山がちの内陸部で次第に力を強めたため、Özdemir Paşaの軍は高地に上ってターイズを占領した。", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["イスタンブル条約 - ハプスブルクとの5年間の和平", "41f81773"], "d": ["オスマンとハプスブルクの間で5年期限の和平が結ばれ、フェルディナントは保持するハンガリー領に対し年3万ドゥカートを支払うことを受け入れた。条約は、ハンガリーが三分されている事実上の状態を法的に追認した。西部戦線がこれで安全になったことで、カーヌーニーにイランへの新たな遠征を組織する余地が生まれた。", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["第二次イラン遠征とタブリーズの再占領", "e82365df"], "d": ["シャー・タフマースブに反旗を翻してイスタンブルに逃れていた弟のElkas Mirzaの勧めで出陣した遠征で、軍は二度目にタブリーズに入った。サファヴィー朝は再び野戦に入らず、土地を焼いて退いたため、都市には数週間しかとどまれなかった。遠征は、タブリーズが保持できないことを決定づけ、オスマンの戦略を恒久的な国境線を築くこと、すなわちヴァンの要塞化へと向かわせた。", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["ヴァンの征服と東部国境の固定", "fc8f930b"], "d": ["タブリーズからの帰途に包囲されたヴァン要塞は、湖の東岸の岩の上にそびえる立地によって、地域の疑いなき鍵であり、短い包囲の後に降伏した。都市はただちにベイレルベイ領の中心とされ、Erciş、Adilcevaz、Hakkâriのサンジャクがここに結びつけられた。タブリーズと違って、ヴァンは保持され、400年にわたってオスマンの東方における最も進んだ恒久的な陣地として残った。", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["ハサーとカティーフの併合 — ペルシア湾のアラビア側の海岸", "f6701e60"], "d": ["バスラの占領の後、湾の西岸でポルトガルの前進拠点となっていたカティーフが占領され、内陸のハサーのオアシス群とともに新たなベイレルベイ領が設けられた。バーレーンとホルムズに向けた作戦の出発点はここであった。オスマン帝国はこうして、アラビア半島の紅海とペルシア湾の両方の海岸で同時に発言権を持つことになった。", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["シャフラズールの喪失 — アルダラーンの君主Sührâbがサファヴィー朝に傾いた", "5600efc9"], "d": ["両イラク遠征の際(1535年)にオスマンの統治を承認していたシャフラズール地方は、Zalm要塞に拠るアルダラーンの首長Bige Beyの統治下にあった。Bige Beyが1550年に死ぬと、Zalm要塞を奪って侯国を支配した弟のSührâbは、サファヴィー朝に向かってオスマンへの服従から離れ、シャフラズール地方はこうしてオスマンの影響を出た。地域は、ナヒチェヴァン遠征のさなかの1554年にZalm要塞が包囲・占領されることで、ようやく取り戻された。", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["アルダハンとチルドゥル盆地の占領", "14c9eb76"], "d": ["エルズルムのベイレルベイは、サファヴィー朝との戦争のさなか、グルジアのアタベクたちのクル川湾曲部の領地に向かい、アルダハンとチルドゥル周辺をオスマンの統治に結びつけた。カルス・アルダハン線はこうして一体となり、北東でグルジアに開く高原が統制下に置かれた。地域の最終的な行政体制は、27年後に設けられるチルドゥル州で完成することになる。", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokullu Mehmed Paşaのドナウ渡河 — トランシルヴァニア戦争の開始", "38fde931"], "d": ["トランシルヴァニア王の幼いヤーノシュ・ジグモンドの後見人である修道士マルティヌッツィが引き起こした混乱と、トランシルヴァニアがバナトの要塞をフェルディナントに譲ったことを受けて、新たな遠征が必要と判断され、指揮はルメリアのベイレルベイSokullu Mehmed Paşaに委ねられた。軍はマルティヌッツィの引き延ばしの努力にもかかわらずドナウを渡り、Beçe、Beçkerek、Çanad、Lippaを占領したが、ティミショアラの包囲は11月16日に寒さのため解かれた。こうしてハンガリーで新たなオスマン・ハプスブルク戦争が始まった。", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["リポヴァ(Lippa)の町がカスタルドのオーストリア軍の手に渡った — 要塞は12月5日に降伏", "a0e1ff0d"], "d": ["Sokullu Mehmed Paşaが1551年10月に取ったリポヴァを、カスタルド将軍の軍が11月4日に包囲した。2日後に町はオーストリア人の手に渡った。Ulama Paşaは5000人の守備隊とともに要塞をさらに9日間守り、1551年12月5日に合意のうえで出た。ティミショアラが1552年に陥落するまで、リポヴァはハプスブルクの手に残った。", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["ティミショアラから派遣された部隊による南バナトの小城塞の掌握 — Versec、Haram、Keve", "edca0921"], "d": ["ティミショアラがオスマン軍に降伏した後、包囲軍から分かれた部隊はバナトの小さな城塞(パランカ)に向かった。Bánlakyの叙述によれば、Versec、Facset、Mehádia、Csákóvár、Haramvár、Keveの各パランカがこれらの部隊に掌握された。こうしてドナウ河岸のHaramもオスマン帝国の手に入った。", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["ソルノクの征服とエゲル包囲の失敗", "a7156e8f"], "d": ["ティミショアラの占領後に合流した二つのオスマン軍は、ティサ川沿いのソルノクを、傭兵守備隊が要塞を放棄したためほとんど戦闘なしに占領した。続いて包囲されたエゲル要塞は、István Dobó率いる2000人の守備隊の38日間の抵抗の前に落とせず、軍は冬が迫ると退いた。同じ遠征で一つの要塞が容易に落ち、もう一つが持ちこたえたことは、ハンガリーで国境がもはやオスマンに有利に自ずと進まないことを示す最初の明白な徴候であった。", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["オスマン-フランス同盟 - フランス艦隊のオスマン指揮下への編入", "a8e01b22"], "d": ["1553年2月1日付の条約により、フランス艦隊はオスマン艦隊の指揮下に置かれ、スペインに対して西地中海での共同作戦が想定された。条約の後、トゥルグト・レイスは1553年6月15日に45隻のガレー船でフランスを支援するため出征した。これは、1536年のカピチュレーションの通商の土台を軍事協力に移した最初の公式な同盟条約であった。", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["シェフザーデ・ムスタファのコンヤ・エレーリスィでの処刑", "dec36858"], "d": ["ナフチヴァン遠征のために集まった軍に加わろうと父の幕舎に入ったシェフザーデ・ムスタファは、御前に出ようとしたところで死刑執行人と出会い、絞殺された。軍内で深く愛されていた世継ぎ候補の殺害はイェニチェリの間に深い怒りを生み、リュステム・パシャは大宰相の職を解かれた。この事件は、オスマンの王子をめぐる政治の最も議論を呼ぶ断絶の一つとして、文学と民衆の記憶に残った。", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["イブリムとヌビアの国境の南への移動", "c57d5d77"], "d": ["エジプト・ベイレルベイ領の南の国境は、ナイル川上の岩の岬の上にそびえるイブリム要塞がÖzdemir Beyの手で要塞化され、下ヌビアがオスマン・エジプトに完全に編入されたことで、第二急流の向こうへと移された。(イブリムのオスマン行政組織はエジプト征服の直後に設けられていた。地図ではイブリムは1517年からオスマン領として表示される。この年は近似であり、史料は年を示さない。)要塞はヌビアからの襲撃に対する防壁であると同時に、センナールに通じる金と奴隷の道の管制点でもあった。ここに置かれたボスニア人の守備隊は非常に長く続き、その子孫は300年後にもまだ要塞にいた。史料はイブリムがオスマンの統治に入った時期について二つの異なる叙述を与える。TDVのスーダンの項は下ヌビアのオスマン・エジプトへの編入を16世紀半ばのÖzdemir Paşaの作戦に結びつけるが、ヌビアの項はワーディー・ハルファまでの地域とイブリムの行政組織が1517年の征服の直後に設けられたと記す。イブリム・サンジャクは1573年7月26日にハベシュ州に結びつけられた。", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["ベジャイア(Bicâye、ブージー)のスペインからの奪取", "49691cda"], "d": ["43年間スペインの手にあり、アルジェとコンスタンティーヌの間の海岸を二つに分けていたベジャイアは、陸と海から包囲された後に降伏した。要塞の陥落によってアルジェ・オジャクの海岸はオランまで途切れなく続くことになった。スペインではこの喪失が非常に大きな憤激を呼び、要塞を引き渡した司令官Alonso de Peraltaは故郷で処刑された。", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["ゼイラのハベシュ州への編入", "7bbf369a"], "d": ["ハベシュ州の南端、アデン湾のアフリカ側海岸にあるゼイラ港がオスマンの統治に結びつけられた。アダル・スルタン国の海に開く門であるこの都市は、バブ・エル・マンデブの外へ出る船にとって最後の補給地点であった。ゼイラの編入によって、オスマン帝国のアフリカにおける国境は最南端に達した。", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["コンヤ王子たちの戦い", "1c8de387"], "d": ["王位争いに入ったシェフザーデ・バヤジトは約3万の兵でコンヤの前に来たが、2日続いた戦闘で弟のシェフザーデ・セリムに敗れた。敗走したバヤジトはアマスヤ経由でイランへ、シャー・タフマースブのもとへ逃れた。この戦いは、カーヌーニーの晩年における王位継承の危機を対外政策の問題に変えた。", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["ジェルバ海戦の勝利", "c7b905c1"], "d": ["ピヤーレ・パシャ指揮下のオスマン艦隊は、トリポリを奪い返すために集まったスペイン-ジェノヴァ-マルタの連合艦隊を、ジェルバ沖で二つに分ける機動で壊滅させた。連合軍は艦隊の大部分を失い、島の城もまもなく陥落した。ジェルバは、プレヴェザに次いでオスマンの地中海での優位を決定づけた二つ目の大海戦の勝利とされる。", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["シェフザーデ・バヤジトのカズヴィーンでの処刑", "a759de14"], "d": ["イランに逃れたシェフザーデ・バヤジトは、長い交渉の末にシャー・タフマースブからオスマンの使節団に引き渡され、4人の子とともに絞殺された。引き渡しの見返りにサファヴィー朝は重要な物質的譲歩と国境の保証を得た。この処刑により、セリム2世の即位を妨げる最後の障害が除かれ、アマスヤ条約の和平秩序が守られた。", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["キオスのジェノヴァ人からの奪取", "a4559b96"], "d": ["200年にわたりジェノヴァのジュスティニアーニ家に属する交易植民地として統治され、オスマンに年貢を払っていたキオスは、年貢を滞らせたことと敵の船に港を提供したことを理由に、Piyâle Paşaによって一発の弾も撃たれずに受け取られた。キオスとプサラとともに、エーゲ海東岸における最後のジェノヴァの存在も清算された。キオスの人々のマスティックの生産と特権は保たれたまま、島はCezâyir-i Bahr-i Sefîd(群島)州に結びつけられた。", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["ナクソス公国の併合 — キクラデス諸島の全域", "68f0ec0b"], "d": ["1207年から続き、1537年からオスマンに年貢を払っていたラテン系のナクソス公国は、最後の公Giacomo Crispoが民を虐げたとして寄せられた訴えを根拠に廃止された。ナクソス、パロス、Değirmenlik、アンドロス、シロス、ミコノス、イオス、アモルゴスと、その周辺のキクラデス諸島のすべてが一つの決定で直接オスマンの統治に置かれた。カーヌーニーは島々の統治をしばらくヨセフ・ナシに与えた。3世紀半に及んだラテン人の支配は、こうしてエーゲ海の中央で終わった。", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["イエメンの反乱とコジャ・スィナン・パシャのイエメン遠征", "c8218d8e"], "d": ["ザイド派イマームのムタッハルは、強制的に税が取り立てられたことを理由に蜂起し、オスマンの統治をイエメンの大部分から払い落とした。イスタンブルから送られたコジャ・スィナン・パシャは、1568-1570年に行った作戦で、長い包囲の末にカウカバーンを奪い、地域のオスマン支配を再建した。遠征は、紅海の南の門とインド洋交易路の管理を保つうえで死活的に重要であった。", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["アチェ・スルタン国との防衛同盟とインド洋への援助", "8e835f24"], "d": ["ポルトガルの攻撃に対してカーヌーニーの援助を求めたアチェの使節たちは、スルタンのシゲトヴァールでの死去を受けて忠誠をセリム2世に捧げ、彼との間に防衛条約が結ばれた。スルタンはアレクサンドリアから大砲、銃、弾薬、職人を送るよう命じ、インド洋へ派遣される17隻の軍艦が準備された。イエメンの反乱の拡大が艦隊の出発を妨げたが、アチェに届いたオスマンの砲兵と職人は地域に永続的な痕跡を残した。", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["キプロス上陸:リマソルの占領", "9074ccc9"], "d": ["島に上陸したオスマン軍は、大きな抵抗に遭わずにリマソルを占領し、翌日ラルナカに向かった。地元の住民がヴェネツィアの統治に不満を持ち、オスマン軍に協力したため、ラルナカでも本格的な抵抗には遭わなかった。Tuzla İskelesiは兵と装備の上陸基地とされた。ヴェネツィアは防衛をニコシアとファマグスタに集中させていた。パフォスの総督は、ニコシアが陥落した後にようやく総司令官への服従を表明した。", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["ニコシアの征服", "413d866b"], "d": ["1570年7月25日に始まり45日続いた包囲の後、キプロスのヴェネツィア統治下の首都ニコシアはオスマン軍に降伏した。島の中心の陥落は、ヴェネツィアの抵抗をファマグスタ城に押し込めた。征服は西欧で大きな反響を呼び、教皇の主導による神聖同盟艦隊の結成へ至る過程を加速させた。", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["キレニアの降伏 — キプロスの北岸", "39fdeea5"], "d": ["ニコシアが9月9日に虐殺を伴って陥落したことで、キプロス北部の抵抗は砕かれた。五本指山脈の向こうのキレニア要塞は、首都の運命を知ると8日後に条件付きで降伏し、守備隊は島から出ることを許されて送り出された。島でヴェネツィアの旗はファマグスタにだけ残り、それもさらに11か月持ちこたえることになる。", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["レパント後の艦隊の再建", "db51fe44"], "d": ["レパントの惨敗の後、海軍総司令官に任じられたクルチ・アリ・パシャの最初の仕事は、大きな損害を受けた艦隊の再建であり、造船所は1571-1572年の冬を通して休みなく稼働した。1572年6月、約250隻のガレー船と300隻の志願のレイスのガレー船からなる新しい艦隊が地中海に出た。この迅速な立ち直りは、レパントがオスマンの海軍力を恒久的に砕くことはなかったことを示した。", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["ヴェネツィアとのイスタンブル条約 - キプロスの承認", "4d08ef50"], "d": ["神聖同盟の解体により孤立したヴェネツィアは、オスマンと単独で和平を結び、キプロスがオスマンに属することを正式に認め、戦争賠償金を払うことを受け入れた。条約は、レパントの勝利がキリスト教世界に政治的な利益をもたらさなかったことを明白にした。ヴェネツィアはこれ以後70年間、オスマンと直接戦争することを避けることになる。", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["セリム2世の死去", "c289f5ee"], "d": ["セリム2世は転倒の後、2か月ほど御前会議に出られず、死去した。その死は、マニサにいた長子ムラトがイスタンブルに来るまで12日間、宮殿で秘匿された。死去の日については史料が分かれる:セラーニキーは12月15日とし、ゲルラハ、メフメト・ブン・メフメト、ジェナービーは12月13日とする。", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["セリム2世の死の公表とムラト3世の即位", "84334d70"], "d": ["セリム2世の死と、マニサから呼び寄せられたムラト3世の即位は、1574年12月22日に正式に公表された。新しいスルタンは21年間王位に留まり、その治世は東方での長いイラン戦争、西方での長期戦争の前夜、そして内政での貨幣の品位低下(アクチェの悪鋳)で記憶されることになる。ソコルル・メフメト・パシャの1579年の死まで、国家の運営では旧来の秩序が続いた。", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["ワーディー・アッサイル(カスル・アル=カビール)の戦い - オスマンの支援を受けたアブド・アルマリクがポルトガル軍を壊滅させる", "21280dac"], "d": ["オスマンの支援でモロッコの王位に就いたアブド・アルマリクは、ポルトガル王セバスティアンの大軍をワーディー・アッサイルで壊滅させた。戦いで三人の君主が同時に死んだため、西欧の史料では「三王の戦い」と呼ばれる。ポルトガルの軍事力は崩壊し、国はまもなくスペインの手に渡った。アブド・アルマリクも戦いで死に、後を継いだ弟アフマド・アル=マンスールは勝利を使節団でイスタンブルに伝えた。両国の関係は貢納や臣従ではなく、使節と贈り物の交換の水準にとどまり、まもなく贈り物の問題で緊張した。", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["デルベントの人々のLala Mustafa Paşaへの服従の表明 — Demirkapıのオスマン統治", "9c55aeff"], "d": ["シルヴァン遠征の間、デルベントの人々から7人の使節団が、エレシュにいた総司令官Lala Mustafa Paşaのもとに赴いて服従を表明した。コーカサスの壁とカスピ海の間の狭い通路を塞ぐデルベント(Demirkapı、鉄門)は、北からの陸路の必須の通路として、シルヴァンの保持において鍵となる役割を果たした。オスマンの支配はここで1607年まで続いた。", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["シルヴァンの征服:シェマハの占領", "9afae4c1"], "d": ["チルドゥルの勝利の後にコーカサスに開いた軍は、サファヴィー朝のカスピ海沿岸で最も豊かな州であるシルヴァンに入り、中心都市シェマハを占領した。Özdemiroğlu Osman Paşaがここのベイレルベイに任命され、シルクロードの北の支線はオスマンの統制下に入った。シルヴァンは、12年続くことになる東方戦争で最も多く手が替わり、最も高くついた戦線となる。", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["バクーの占領 — カスピ海岸への到達", "eb5adab8"], "d": ["シルヴァン作戦の最後の環として、カスピ海の西岸にあるバクー港が占領された。都市の周辺の石油の井戸は、当時すでに知られた収入源であり、港はカスピ海を経由して来るイラン絹の積み出し地点であった。オスマン帝国はこうして歴史上初めて、そして唯一、カスピ海に面する沿岸の所有者となった。", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["エレヴァン(Revan、Erivan)の征服と要塞の建設", "7f623b7b"], "d": ["カルスでエレヴァンに行ってそこに要塞を築くよう命じられたFerhad Paşaはエレヴァンに進軍し、都市はヒジュラ暦991年ラマダーン月の初め(1583年9月中旬)にオスマンの統制下に入った。アラス川流域の北の門を押さえるエレヴァンには新しく大きな要塞が築かれ、都市はベイレルベイ領の中心とされた。カルスとタブリーズの間の軍道の中央に立つエレヴァンは、東部戦線の兵站の背骨であった。要塞は非常に堅固に造られ、その後200年のあいだ、オスマン・イラン戦争の不動の目標となった。", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["カラバフとギャンジャの併合", "29abaead"], "d": ["10年に及ぶ東方戦争の最後の獲得として、Ferhad Paşaは1588年にギャンジャに進軍し、9月1日に都市に入った。クル川とアラス川の間のカラバフ地方とその中心ギャンジャがオスマンの統治に置かれた。こうしてシルヴァン、エレヴァン、カラバフが結びついて、コーカサスに途切れのないオスマンの線ができた。1590年に署名されたFerhad Paşa条約がこの国境を確認することになるが、獲得はわずか20年しか保持できなかった。", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["ビハチの征服", "651a7275"], "d": ["ボスニア総督テッリ・ハサン・パシャは、1591年11月にビハチの前衛の城リパチを奪った後、1592年に都市と城自体も占領した。10日間の包囲の後、司令官ラムベルクは降伏した。この征服はボスニア国境をウナ川沿いに押し進め、1年後にテッリ・ハサン・パシャがクルパ(Kulpa)の前で殉死して勃発する長期戦争の前夜における、オスマン最後の大きな獲得となった。", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["オスマン-オーストリア「長期戦争」の開始", "bd22c392"], "d": ["ボスニア総督テッリ・ハサン・パシャがクルパ(シサク)の前で敗れて殉死したことを受け、オスマン国家はオーストリアに宣戦し、13年続く長期戦争が始まった。火器を持つ歩兵が決定的となったこの戦争は、オスマンの軍制でセクバン(銃兵)と火縄銃兵の雇用を加速させ、ティマール制のスィパーヒーの衰退を深めた。戦争は1606年のジトヴァトロク条約で終わることになる。", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["コジャ・スィナン・パシャ、オーストリア遠征に出発 - 長期戦争の最初の遠征", "d4a2f46d"], "d": ["ボスニア総督ハサン・パシャがシサク(Sisak)の前で敗れて殉死した後、大宰相コジャ・スィナン・パシャは、巧みな言葉と約束でスルタンを戦争に同意させ、1万2千人のイェニチェリとその他の部隊とともに出発した。こうして13年続くオスマン-オーストリア戦争の最初の遠征が開かれた。", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["ジェール(Győr、ヤヌクカレ)の征服", "14b75207"], "d": ["大宰相コジャ・スィナン・パシャは、1か月を超える包囲の後、ウィーンへの道の鍵とされるヤヌクカレ(ジェール)を接収した。城の陥落はヨーロッパに大きなパニックを引き起こし、長期戦争におけるオスマンの最も輝かしい獲得となった。しかし城は4年間しか保持できないことになる。", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["ムラト3世の死去", "1b62e886"], "d": ["21年の治世の後、ムラト3世は、ワラキア軍がブライラを焼いてシリストラにまで達していた日々に死去し、アヤソフィアの墓域に葬られた。マニサから呼び寄せられた子メフメト3世は10日後にイスタンブルに着いて即位した(1595年1月27日)。", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["エステルゴムのオーストリアへの喪失", "f420d333"], "d": ["カール・フォン・マンスフェルトが率いた包囲で十分な援助を得られなかったエステルゴムの守備兵は、城をマティアス大公に引き渡した。52年のオスマン支配が終わったことで、ドナウ線の防衛の連鎖が断ち切られ、ブダが直接の脅威にさらされた。城は10年後の1605年になってようやく取り戻されることになる。", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["エゲル城の征服", "3e511629"], "d": ["3週間続いた戦いの後、オスマンがそれまでどうしても奪えなかった堅固なエゲル城が、守備兵の降伏により陥落した。スルタン自らが臨んだこの征服は、失われたエステルゴムが生んだ士気をいくらか回復させ、エゲル州が設置された。2週間後に得たハチョヴァの勝利とともに、1596年は長期戦争でオスマンが最も成功した年となった。", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["ジェール(Győr、ヤヌクカレ)の喪失", "b4ccc679"], "d": ["ミクローシュ・パールフィとアドルフ・フォン・シュヴァルツェンベルク指揮下の部隊は、奇襲で城門を爆破してヤヌクカレを取り戻した。4年前にコジャ・スィナン・パシャが多大な労力で得た城の喪失は、オスマンのハンガリーにおける前線を崩壊させた。同年ブダを包囲した敵軍は撃退されたが、戦争の均衡はしだいに消耗戦に変わっていった。", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["カラヤズィジュ・アブデュルハリムの蜂起", "30493b0d"], "d": ["長期戦争で軍から逃れたセクバンとレヴェンドを集めたカラヤズィジュ・アブデュルハリムは、中央アナトリアの広い地域を支配下に収め、ウルファ城を奪い(1599年11月)、「ハリム・シャー」の称号でスルタン位を宣言して自らのトゥグラを帯びた勅令を送った。大ジェラーリー波の最初の指導者とされるカラヤズィジュは1602年に死に、運動は弟のデリ・ハサンが続けた。蜂起は、アナトリアの農民が大挙して土地を去る「大逃散」の時代の始まりである。", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["ティリヤキ・ハサン・パシャのカニジェ防衛", "d56a5e6a"], "d": ["1年前に征服されたカニジェを取り戻そうとしたフェルディナント大公とその同盟者たちは、城を2か月以上包囲した。ティリヤキ・ハサン・パシャは9千の兵で抵抗した。外からの援助を得られないにもかかわらず総攻撃を撃退し、出撃作戦で敵に大きな損害を与えて撤退に追い込んだ。この防衛はオスマンの歴史叙述で叙事詩となり、「カニジェ攻囲記」はそれ自体が一つの文学ジャンルとなった。", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["メフメト3世の死去とアフメト1世の即位", "da735fde"], "d": ["メフメト3世の12月20日の死により、14歳の子アフメト1世が王位に就いた。幼い年齢で、サンジャク(地方総督)の経験を経ずに王位に就いた最初のスルタンであることは、王子たちを地方で育てる慣行が事実上終わったことを示す。アフメト1世の治世には、兄弟殺しが放棄され、「エクベリイェト」(最年長の男子成員が王位を継ぐ)の原則に移ることになる。", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["エステルゴムの奪還", "7330f273"], "d": ["大宰相ララ・メフメト・パシャは、10年前に失われたエステルゴムを包囲して再びオスマンの統治に加えた。同じ遠征のうちにペシュトとヴァーツも取り戻され、オスマンはハンガリーの戦線を立て直した。この成功は、翌年のジトヴァトロクで比較的強い立場で交渉の席に着くことを可能にした。エステルゴムは1683年までオスマンの手に残ることになる。", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["オルチュ平原の勝利とジャンボラトオウルの反乱の鎮圧", "30f93532"], "d": ["アレッポで独立した侯国を築いてトスカーナとの同盟を探ったジャンボラトオウル・アリ・パシャは、大宰相クユジュ・ムラト・パシャによってオルチュ平原で大敗した。シリアで中央の権威が再建されたことで、ジェラーリー波の最も危険な一派は砕かれた。クユジュ・ムラト・パシャの2年続いた容赦ない粛清は、一時的ではあれアナトリアの治安を回復させた。", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["アラチャユルの勝利とカレンデルオウルの反乱の鎮圧", "55db0485"], "d": ["マニサとブルサ周辺から貢納を取り立てていたジェラーリーの指導者カレンデルオウルは、クユジュ・ムラト・パシャによってアラチャユルで大敗し、イランへ逃れざるを得なかった。この勝利で、アナトリアの大ジェラーリー軍の最後のものが解散させられた。クユジュ・ムラト・パシャが、殺させた反乱者たちを掘らせた井戸に詰めたと伝えられる厳しい粛清は、短期的には秩序をもたらしたが、アナトリアの人口と生産の損失を埋め合わせることはできなかった。", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["オランダへの最初のアフドナーメ(通商特許状)の付与", "5d9d117e"], "d": ["ネーデルラント連邦共和国の使節コルネリス・ハーガは、アフメト1世から、フランスとイギリスに与えられたものと同じ範囲のアフドナーメを得ることに成功した。オランダはこうして、イスタンブルに大使館を、オスマンの港に領事館を開く権利と、自国の旗で交易する権利を得た。このアフドナーメは、地中海交易でヴェネツィアに取って代わった北方の海洋国家がオスマン市場に入ったことを象徴する。", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["アフメト1世の死とムスタファ1世の即位 - エクベリイェトの慣行", "9901c09e"], "d": ["51日間続いた胃の病の後、28歳のアフメト1世が死去し、王位には息子の代わりに弟のムスタファ1世が就けられた。こうして父から子へ継ぐ継承の慣行は放棄され、王家で最年長の男子成員が王位を継ぐ「エクベリイェト」制に事実上移った。96日間続いたこの最初の治世は、王子たちが「カフェス(鳥籠)」で育てられる時代の始まりでもある。", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["ムスタファ1世の廃位とゲンチ・オスマン(オスマン2世)の即位", "e0f552f2"], "d": ["精神の健康が整っていないことを理由に、ムスタファ1世は96日後に王位を降ろされ、アフメト1世の14歳の子オスマン2世がスルタンとなった。ハサンベイザーデに基づく伝承によれば、この廃位の決定には宦官長(キズラル・アー)ムスタファ・アーが影響した。ゲンチ・オスマンは、イェニチェリ軍団を廃して新しい軍を築く構想をもったことから、オスマンの改革論議における最初の急進的な人物とされる。この構想は4年後に自身の命を奪うことになる。", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["サラーヴ条約 - イランとの和平の更新", "e778aca8"], "d": ["プリ・シケステの敗北の後にイランと結ばれたサラーヴ条約は、1612年のナスーフ・パシャ条約の条件をおおむね確認した。サファヴィー朝が送る年間の絹の量は200荷から100荷に減らされた。こうして1603年から続いた東方戦争の第二局面は閉じた。和平は長続きせず、バグダードが1623年に失われると戦争は再燃することになる。", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["ホティン遠征とホティン条約", "bc4c823c"], "d": ["オスマン2世が自ら指揮した大軍に対し、ホトキェヴィチがホティンの前に築いた要塞化した陣営は突破できず、数か月続いた攻撃からも成果は得られなかった。10月9日に結ばれた条約でドニエストル川が国境とされ、ポーランド人はコサックの襲撃を防ぐことを約束した。勝利として発表されたにもかかわらず成果を出せなかった遠征は、若いスルタンのイェニチェリへの不信と、軍団を粛清する意図を強めた。", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["ホルムズのポルトガル人からの奪取", "93e5f6cf"], "d": ["サファヴィー朝の軍は、1515年からポルトガルの手にあったホルムズを包囲して取り戻した。ゲシュム島と海岸のGamrûn(バンダレ・アッバース)もサファヴィー朝の統治に移り、湾の交易は新しい港に移った。", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["ムスタファ1世の二度目の廃位とムラト4世の即位", "1b3a9e74"], "d": ["オスマン2世の殺害の後、二度目に王位に就けられたムスタファ1世は1年3か月後に再び降ろされ、11歳のムラト4世がスルタンと宣言された。最初の9年間、国家は事実上、母キョセム・スルタンと宮廷の高官たちによって運営された。ムラト4世は1632年以降、自ら政務を執って厳しい中央集権の時代を始めることになる。", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["バグダードのサファヴィー朝への喪失", "db81be0c"], "d": ["バグダードで蜂起したベキル・スバシュがサファヴィー朝と進めた交渉の末、内城を守っていた子のデルヴィシュ・メフメトが、都市をシャー・アッバースの軍に引き渡した。カリフ制の遺産の象徴的な都市の一つとイラクの大部分が失われたことは、イスタンブルで大きな憤激を呼んだ。バグダードを取り戻すことは、15年間、オスマンの東方政策の唯一の目標となる。", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["アバザ・メフメト・パシャのエルズルムを拠点とする反乱の鎮圧", "e6da2729"], "d": ["オスマン2世殺害の復讐を掲げてイェニチェリに対し蜂起したエルズルム総督アバザ・メフメト・パシャは、数年間東アナトリアを支配下に置いて中央に抵抗した。大宰相ヒュスレヴ・パシャのエルズルム包囲により降伏を余儀なくされ、赦されてボスニアに任命された。反乱の終結は、ムラト4世がイランへ出征できるための前提条件であった。", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["最初のシェイヒュルイスラーム処刑:アヒーザーデ・ヒュセイン・エフェンディ", "a60a58c5"], "d": ["軍の混乱で仲介を行ったことと、スルタンに裁判の手続きについて書面で警告を送ったことを理由に、シェイヒュルイスラームのアヒーザーデ・ヒュセイン・エフェンディはビュユクチェクメジェ近郊で処刑された。処刑された最初のオスマンのシェイヒュルイスラームであることは、イルミイェ(学識階層)の成員に対する最も重い刑は追放であるという根づいた伝統を破った。この事件は、ムラト4世の強まった権威と、国家とウラマーの均衡の崩れの象徴とされる。", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["ムラト4世のエレバン征服", "b65a9b73"], "d": ["1635年3月28日にイスタンブルを発ったムラト4世は、7月28-29日にエレバンを包囲し、8月8日に城を接収した。続いて無人となったタブリーズに入り、都市を破壊させた。スルタンは勝利の記念としてトプカプ宮殿にレヴァン・キョシュキュ(エレバン亭)を建てさせた。この遠征は、スルタンが自ら軍を指揮した、30年ぶりの最初の大きな東方作戦であった。", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["エレバンのサファヴィー朝への喪失", "fbb8dd25"], "d": ["オスマン軍が撤退した後、シャー・サフィの軍はエレバンを包囲し、8か月で取り戻した。城がこれほど早く失われたことは、カフカスでの恒久的な支配が兵站の上でいかに困難であるかを示した。エレバンは1639年のカスレ・シーリーン条約でもイランに残され、オスマンはアゼルバイジャンの要求を放棄することになる。", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["バグダードの奪回", "4d2f27f3"], "d": ["1638年5月8日にイスタンブルを出たムラト4世は、40日間続いた激しい包囲の末、15年間サファヴィー朝の手にあったバグダードを取り戻した。包囲で宰相タイヤル・メフメト・パシャが殉死した。都市の征服によりイラクでオスマンの統治が再建され、スルタンは「バグダード征服者」の称号を得た。征服は翌年のカスレ・シーリーン条約で恒久化され、今日のトルコ-イラン国境の礎を築いた。", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["ムラト4世の死とスルタン・イブラヒムの即位", "e2ca1ca0"], "d": ["27歳(ヒジュラ暦の数えで28歳)で死んだムラト4世の後、王家の生き残る唯一の男子成員であった弟イブラヒムが王位に就いた。長年カフェスで暮らしてきた新しいスルタンの治世には、宮廷の支出と宮廷内の勢力争いが国家の秩序を揺るがした。8年後に廃位されて殺害され、オスマン史で二人目のスルタン殺害が起こることになる。", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["アゾフ城のコサックからの奪回", "e5fcf160"], "d": ["1637年にドン・コサックが奪ったアゾフ城は、スルタンザーデ・メフメト・パシャとクリム・ハンのメフメト4世・ギレイの共同作戦の前に明け渡された。コサックは城に火を放って退いた。黒海北方の門が取り戻されたことで、コサックの襲撃がイスタンブル海峡にまで及んだ危険な時代は閉じた。城は1696年に、今度はロシアのピョートル1世に奪われることになる。", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["クレタ遠征の開始とハニアの征服", "a1b0c77f"], "d": ["マルタの海賊がオスマンの巡礼船を襲ってクレタに逃げ込んだことを口実にヴェネツィアに宣戦し、ユースフ・パシャ指揮下の艦隊が島に兵を上陸させた。54日間の包囲の後、ハニア城が奪われ、クレタに最初の恒久的なオスマンの基地が築かれた。こうしてオスマン史で最も長く続く戦争が始まり、島が完全に征服されるのは24年後の1669年となる。", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["レティムノの征服 — クレタの二分", "8f2c4353"], "d": ["ハニアの占領から1年後、島の中部のレティムノ要塞も陥落し、クレタの西半分が完全にオスマンの統治に入った。ヴェネツィアの手に残ったのは首都カンディアと東端だけで、島は23年間二つに分かれたまま存続した。レティムノの占領はカンディア包囲を始める一歩となった。歴史上最長の包囲はここから始まったのである。", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["クリスのヴェネツィアへの喪失", "5473c22c"], "d": ["クレタ(カンディア)戦争のダルマチア戦線で、ヴェネツィアの司令官レオナルド・フォスコロの反攻は、1537年からサンジャクの中心であったクリスにも及び、城はヴェネツィアに移った。オスマンがすべての力をクレタに集中していたため、ダルマチア国境でのこの喪失を取り戻すことは不可能であった。クリスは二度とオスマンの統治に戻らず、サンジャクの中心はリヴノに移された。", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["カンディア攻囲の開始", "13016b10"], "d": ["ハニアとレシムノの奪取の後、オスマン軍はヴェネツィアの島における最後の大きな拠点カンディアを包囲下に置いた。21年続くことになるこの封鎖は、世界の軍事史で最も長い攻囲の一つとして記録された。攻囲の間、ヴェネツィア艦隊がダーダネルス海峡を封鎖しようとした試みは、戦争をエーゲ海の中心へ持ち込むことになる。", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["大ヴァーリデ、キョセム・スルタンの殺害", "9d763f79"], "d": ["約62歳のキョセム・スルタンは、メフメト4世の母トゥルハン・スルタンの命で動いたバシュララ・ウズン・スレイマン・アー(Uzun Süleyman Ağa)とその配下により、ハレムの一室で見つけられて殺された。三人のスルタンの時代に国家の政策を導いたこの有力な王家の女性の死は、「女人の治世」と呼ばれる時代の事実上の終わりとされる。空いた権威は、5年後にキョプリュリュ・メフメト・パシャが並外れた権限で大宰相になる道を開いた。", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["ダーダネルスの敗北とボズジャアダとリムノスの喪失", "e01a1f7e"], "d": ["ヴェネツィアの提督モチェニーゴが1656年6月にダーダネルス海峡の前で収めた大海戦の勝利は、オスマン艦隊をほぼ完全に壊滅させた。続いてボズジャアダ、リムノス、サモトラキが占領された。海峡がヴェネツィアの封鎖に入ったことで、イスタンブルでは食料の価格が高騰し、首都への攻撃の恐れが広がった。この惨事は、1656年9月にキョプリュリュ・メフメト・パシャが条件付きで並外れた権限とともに大宰相に就く直接の原因となった。", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["ダーダネルスの勝利とボズジャアダの奪回", "603da863"], "d": ["キョプリュリュ・メフメト・パシャが動員した艦隊は、1657年7月19日に海峡の前でヴェネツィア艦隊を破った。続いてクルド・パシャ指揮下の部隊が8月25日にボズジャアダを取り戻し、8月30日にヴェネツィア人は島を完全に明け渡した。11月にはリムノスも解放されてダーダネルスの封鎖は破られ、イスタンブルの糧食路が再び開かれた。キョプリュリュは自ら島に渡って防備を修理させた。この成功は、キョプリュリュ時代の最初の大きな軍事的獲得である。", "af4d7bfd"]},
"OLAYLAR_EK5:1657-11-15:0":{"b": ["レムノスのヴェネツィアからの奪還", "a4c3c69b"], "d": ["1656年7月にヴェネツィアが取ったレムノスは、1657年11月にオスマンに戻った。", "1d61fe33"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["ヤノヴァ(Ineu)の征服とトランシルヴァニア遠征", "d1089616"], "d": ["許可なくポーランド遠征に出てオスマンの保護を踏みにじったトランシルヴァニア公ラーコーツィ・ジェルジ2世を罰するために出征したキョプリュリュ・メフメト・パシャは、ベオグラード経由で進軍して戦略上の要衝ヤノヴァ城を奪った。トランシルヴァニアには新しい公が任命され、臣従の関係が厳しく思い起こさせられた。この遠征は、オスマンが中欧で権威を再建しようとした試みの最初の環であった。トランシルヴァニアはすでにオスマンに服属する公国であった。ヤノヴァの奪取は外国の国家からの征服ではなく、服属するトランシルヴァニアのこの城を公国の統治から外して直接オスマンのサンジャクに結びつけることであり、公国の残りは服属の地位に留まった。", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["アバザ・ハサン・パシャの反乱の鎮圧", "4ba74321"], "d": ["キョプリュリュ・メフメト・パシャの厳しい粛清に対し、アナトリアの総督たちとセクバンの頭目たちを後ろ盾としたアバザ・ハサン・パシャは、大宰相の罷免を求めて大規模な蜂起を起こした。反乱はアレッポで鎮圧され、首謀者たちは排除された。これは、地方のパシャたちによる中央への最後の集団的抵抗となった。キョプリュリュの権威はこうして揺るぎないものとなり、大宰相の職は再び国家の実質的な執行の中心の地位に昇った。", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["ヴァラド(オラデア)の征服", "0e6ad300"], "d": ["オスマンに宣戦したトランシルヴァニア公ラーコーツィ・ジェルジ2世に対する遠征の枠内で、ヴァラド城と都市が奪われた。トランシルヴァニアの要衝の一つの陥落により、地域に新たなオスマンの州(ヴァラド州)が設置された。征服はハプスブルクを警戒させ、3年後に始まるオスマン-オーストリア戦争の直接の原因の一つとなった。同日に編入されたその他の地:ヴァラト。ここでも土地は外国の国家から取られたのではない:トランシルヴァニアはすでに服属するオスマンの公国であった。ヴァラドが州になったことは、この都市の統治を服属する公国から取ってスルタンに直接結びつけただけであり、2年前のヤノヴァの場合と同様である。", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["ザンクト・ゴットハルト(Sen Gotar)の戦い", "61ebc1f2"], "d": ["ラーブ川を渡ったオスマン軍は、モンテクッコリ指揮下のヨーロッパ連合軍に阻まれ、大きな損害を出した。この戦いは、規律ある火器歩兵の射撃がオスマンの騎兵突撃に対して持つ優位を初めて明確に示した点で、軍事史上の転換点とされる。敗北にもかかわらず、オスマンは9日後に結ばれたヴァシュヴァール条約で有利な条件を得ることに成功した。", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["ヴァシュヴァール条約", "089c978c"], "d": ["ザンクト・ゴットハルトの敗北にもかかわらず結ばれた条約は、ウイヴァールとヴァラドがオスマンに留まること、トランシルヴァニアがオスマンの保護下で中立に置かれること、オーストリアが20万クルシュの「贈り物」を支払うことを定めた。20年期限のこの和平は、戦争に敗れた側が交渉の席で勝ち取った稀な例の一つである。条約がハプスブルクの世論に生んだ不満は、中部ハンガリーの運動と、間接的に1683年のウィーン遠征を養うことになる。", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["アルジェにおけるデイ統治の開始", "e99faa51"], "d": ["アルジェの軍団とタイファ・イ・レイース（海賊船長たち）は、最後のアーを罷免して、ハジュ・メフメトを終身の条件でデイに選んだ。この日以降、アルジェを統治したのはイスタンブルが任命するベイレルベイではなく、地元の軍団が自らの中から選ぶデイであった。オスマン朝との結びつきは、フトバでスルタンの名が読まれること、旗、遠征の義務に限られた。アルジェはこうして州から軍団支配領に変わった — 同じ変化をチュニスは1705年にフサイン朝のもとで、トリポリは1711年にカラマンリー家のもとで経験した。", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["ポーランド遠征の開始 - メフメト4世とファーズル・アフメト・パシャが軍の先頭に", "75e15a39"], "d": ["オスマンの保護下に入ったウクライナのヘトマン、ペトロ・ドロシェンコに対するポーランドの攻撃が続くと、イスタンブルはポーランド王に攻撃をやめるよう求めた。好意的な返答が来なかったため、ポーランドへの遠征が決定された。大宰相ファーズル・アフメト・パシャは、スルタンも同行する軍とともに1672年6月4日にポーランドへ出発した。遠征は、カミェニェツの征服とブチャチ条約に帰結することになる。", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["カミェニェツ・ポドルスキの征服とポドリア州の設置", "c3f4f6d0"], "d": ["9日間の包囲の後、ポーランドの東方で最も強力な城とされるカミェニェツ・ポドルスキが接収された。メフメト4世は9月2日、大聖堂から改められたモスクで最初の金曜礼拝を行った。城を中心としてポドリア州が設置され、オスマンの旗は今日のウクライナの地で最北に達した。カミェニェツは、1699年のカルロヴィッツ条約まで帝国の北西端であり続けることになる。", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["カラ・ムスタファ・パシャ、ウマンをポーランドから接収", "0d3543a0"], "d": ["ポーランドに対して送られたカラ・ムスタファ・パシャは、ポーランドの手にあった城のうちウマンを接収した。都市はカルロヴィッツまでオスマンの統治下に留まった。", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["チヒルィン城の征服", "a17cedd0"], "d": ["前年にメレク・イブラヒム・パシャが成果を得られなかった作戦の後、大宰相メルズィフォンル・カラ・ムスタファ・パシャは自ら指揮して堅固なチヒルィン城を包囲し(7月19/21日)、8月21日に占領した。ウクライナのコサックのヘトマン国をめぐるオスマン-ロシアの競合の象徴であった城の陥落は、ロシアを和平に追い込んだ。この成功は、メルズィフォンルがウィーンへ向かう自信の源の一つともなった。", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["バフチェサライ条約 - ロシアとの最初の正式な和平", "df82bc0b"], "d": ["チヒルィン遠征の後、クリム・ハンの仲介で進められた交渉の末、ドニプロ川(オズュ川)が国境とされ、オスマン国家とロシアの間で20年間の和平が結ばれた。これは両国間の最初の包括的な条約であることから、オスマン-ロシア関係の出発点となる文書とされる。この和平により東部戦線が安全になり、軍を中欧に向けることができた。", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["テケリ・イムレへの中部ハンガリー王国の勅許状の授与", "3cd8d51d"], "d": ["ハプスブルクの圧力に対して蜂起したプロテスタントのハンガリー貴族テケリ・イムレは、1682年4月から「中部ハンガリーの選ばれた王」とみなされ始め、9月16日にブダ総督イブラヒム・パシャが彼に公位の印を差し出した。こうしてオスマンの保護下に新たな臣従ハンガリー国家が築かれた。この介入はオーストリアとの戦争を不可避にし、翌年の第二次ウィーン包囲に至る連鎖を始めた。", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["アヤマヴラ(レフカダ)のヴェネツィアへの喪失", "e6905fee"], "d": ["神聖同盟に加わったヴェネツィアの艦隊は、城塞都市を砲撃した後、イオニア海のアヤマヴラ島を占領した。同年プレヴェザも陥落したことで、オスマンのアドリア海口での支配は砕かれた。これらの損失は、モロジーニが3年のうちにモレア全体を奪う作戦の始まりの一歩であった。", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["コロンのヴェネツィアへの喪失", "2ed762bc"], "d": ["モロジーニ指揮下のヴェネツィア軍は、モレア半島南西端のコロン城を占領した。都市はこれ以後30年間ヴェネツィアの統治下に留まることになる。コロンの陥落は、モレアの征服に向けたヴェネツィアの作戦の最初の大きな獲得であった。城は1715年に、スィラフダル・アリ・パシャ指揮下のオスマン軍によってようやく取り戻された。", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["アテネの奪還 — ヴェネツィアの撤退", "03393b46"], "d": ["1687年9月にアクロポリスを砲撃してパルテノンを爆破したモロジーニは、冬をアテネで過ごした後、都市で持ちこたえられないことを悟った。ペストの流行、補給の困難、オスマン軍の立て直しを受けて、ヴェネツィアの守備隊は都市を空けてモレアに退いた。アテネはこうして戦わずに再びオスマンの統治に戻ったが、パルテノンが被った破壊は取り返せなかった。", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["リポヴァ(Lippa)がカラファに降伏した — オーストリアの手に渡った", "7f0a8d38"], "d": ["アントニオ・カラファの3日間の包囲の後、リポヴァは1688年6月12日から22日の間に降伏し、オーストリアの手に渡った。オスマンは後に都市を取り戻し、オーストリアは1691年に再び占領した。1695年の遠征でオスマンは再び支配を確保した。同じ日に本アトラスでオスマンからハプスブルクに移る他の定住地は、アラドとシリア(Világos、Şiria)である。アラドについて史料は年のみを示す(MKL、Arad:1551年から1688年の間はオスマンの手にあった)。日付はリポヴァから取られ、ヴィラゴシュ(Világos)はアラドの連鎖に従う(宣言付きの近似)。", "0dfcf5af"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["ヴェネツィアのエヴリポス(エウボイア)攻囲の撃退", "aae7e6a0"], "d": ["モレアを奪った後エーゲ海に向かったモロジーニは、3か月を超える包囲でエヴリポスを奪おうとしたが、1687-1688年の冬に強化された防備と守備隊の抵抗の前に大きな損害を出して撤退せざるを得なかった。この失敗はヴェネツィアのエーゲ海での進出を止め、モロジーニの軍事的な威信を揺るがした。エヴリポスは、カルロヴィッツでもオスマンの手に残ることになる。", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["カニジェ城のオーストリアへの喪失", "553b45f3"], "d": ["1690年1月から6万の兵のハプスブルク軍の厳重な封鎖下に置かれたカニジェは、数か月にわたり援助を得られないまま抵抗した後、最後の守将ムスタファ・パシャが署名した降伏協定により失われた。こうして、ティリヤキ・ハサン・パシャの叙事詩的な防衛で記憶される城における90年のオスマン支配は終わった。カニジェの喪失は、オスマンのハンガリー西部における最後の大きな拠り所の崩壊であった。", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["スレイマン2世の死", "d2478080"], "d": ["約40年を「鳥籠」(カフェス)で過ごした後、1687年に即位させられたスレイマン2世は、病身で軍の準備を見守っているうち、1691年6月22日の金曜日の昼ごろにエディルネで死去した。治世は3年8か月2日であった。大宰相は、スルタンが亡くなった場合に弟のアフメトを即位させるために必要な指示をあらかじめ出していた。葬儀の礼拝は同日にアライ・キョシュキュで行われ、遺体はイスタンブルに運ばれて、スレイマン1世(カーヌーニー)の廟の、その右側に葬られた。", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["アフメト2世の即位", "52947b14"], "d": ["スレイマン2世の死を受け、49歳の弟アフメト2世がエディルネで王位に就いた。治世は神聖同盟戦争の最も厳しい年月に当たり、即位の2か月後にサランケメンで大宰相ファーズル・ムスタファ・パシャが殉死した。一方、治世に導入されたマーリカーネ制は、オスマン財政の長期的な構造を変えた最も重要な措置の一つとなった。", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["メフメト4世のエディルネでの死去", "17388b7e"], "d": ["1687年に廃位されたAvcı(狩猟王)メフメトは、スレイマン2世の1689年のハンガリー遠征の間にエディルネに連れてこられ、もう一人の弟アフメト2世の治世も目にした。深く愛したこの都市で亡くなった。遺体はイスタンブルに運ばれ、母トゥルハン・スルタンのイェニ・ジャーミー脇の廟に葬られた。", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["アフメト2世のエディルネでの死去", "c6306c08"], "d": ["4年の治世を戦争のうちに過ごしたアフメト2世は、52歳で水腫(istiskā)のためエディルネで亡くなった。遺体はイスタンブルに運ばれ、スレイマン1世(カーヌーニー)の廟に埋葬された。後を甥のムスタファ2世が継いだ。", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["バスラのイラン人による占領", "a9cdf3a3"], "d": ["オスマン帝国が西で神聖同盟の戦争に追われているとき、バスラは1690年のペスト流行の後、まずムンタフィクのシェイフMâni'の、次いでフワイザ侯Ferecullahの略奪を被っていた。この混乱につけ込んだイラン人は1696年に都市を占領し、バスラに守備隊を置いた。", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["イスタンブル条約 - アゾフのロシアへの割譲", "79db4724"], "d": ["カルロヴィッツではロシアとは2年間の休戦しか結べず、恒久的な和平はイスタンブルで1年半に及ぶ難しい交渉の後に結ばれた。オスマン国家は1696年に失ったアゾフ城とその周辺の土地を正式にロシアに放棄し、クリム・ハンがモスクワから受け取っていた年貢を放棄した。その代わりロシアはイスタンブルに常駐の大使を置く権利を得た。こうして、黒海北岸におけるロシアの存在は法的に追認された。", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Daltaban Mustafa Paşaによるクルナとバスラの奪還", "7adb777d"], "d": ["カルロヴィッツ条約の後にバグダード総督とバスラ総司令官に任命されたDaltaban Mustafa Paşaは、アレッポ、ラッカ、シヴァス、カラマンの軍と、ビレジクから下る河川艦隊とともに南へ進軍した。周辺の部族のシェイフたちは一人ずつ服従し、イランのバスラ守備隊長Dâvud Hanは都市を放棄して、クルナとバスラは再びオスマンの統治に入った。", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["ムスタファ2世の死去", "626c394d"], "d": ["エディルネ事件で王位を弟のアフメト3世に譲ったムスタファ2世は、廃位から5か月ほど後に、深く愛したエディルネで亡くなった。病に最近の出来事への悲しみも加わっていた。一部の西欧の史料は、民衆の間で彼が毒殺されたという見方が広まっていたと記す。", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["バグダードでのキョレメン(マムルーク)統治の始まり", "abe52618"], "d": ["グルジア出身のハサン・パシャがバグダード総督に任じられたことで、イラクでは中央から任命される総督に代わって、自らの奴隷から育った統治層が支配する時代が始まった。スレイマン・パシャの1749年の総督在任で制度は定着し、バーブ・アーリーはもはや望む者ではなく、影響力を握ったキョレメンの一人を任命せざるを得なくなった。この半自立的な構造は、イラン国境の防衛には役立ったが、イラクに対する中央の権威の統制を1世紀半にわたり弱めた。", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["チュニスでのフサイン朝の成立", "cb1a98f9"], "d": ["アルジェ軍がチュニスに侵攻したことで生じた権威の空白のなかで、トルコ系のスィパーヒー長フサイン・ブン・アリーがベイ位を掌握し、オスマンのスルタンへの忠誠を表明して正統性を得た。彼が築いた王朝は1705-1735年および1756-1957年にチュニスを統治し、オジャク(軍団)による統治に代わって、父から子に継ぐベイ制が敷かれた。こうして、西方のオジャク諸国で、中央に結びつきつつ事実上自立した王朝構造の最初の例が生まれた。", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["オラン(Vahran)とメルス・エル・ケビールのスペインからの奪取", "b67ce06a"], "d": ["アルジェのオジャクの総督の軍は、2世紀にわたりスペイン守備隊の手にあったオランと港メルス・エル・ケビールを、長い包囲の末に奪った。西地中海で、オスマンの保護下にある西方のオジャク諸国がスペインに対して収めた最大の成功であり、アルジェの西翼を確保した。都市は1732年に再びスペインの占領を受けるが、1792年に最終的に取り戻されることになる。", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["プルート条約 - アゾフとタガンログの返還", "bac5d2a1"], "d": ["プルート川のほとりで包囲されたロシア軍の降伏とともに結ばれた7か条の条約は、アゾフ城がその土地と弾薬とともにオスマンに返還されることを定めた。タガンログ、カメンカ、イェニカレの要塞は破壊され、両者はこれらの地域に新しい城を築かないこととされた。ピョートル1世がヴォロネジとアゾフで16年かけて築いた海軍と基地の体制は崩壊し、ロシアの黒海への進出は約50年遅れた。", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["トリポリ(タラーブルス・ガルブ)でのカラマンル朝の成立", "e1105d4a"], "d": ["オジャクの長たちの争いに疲弊したトリポリで、騎兵将校アフメト・カラマンルが政権を握り、イスタンブルから得た総督の勅許状で自らの地位を公式のものとした。アフメト・パシャ、子メフメト・パシャ、孫ユースフ・パシャの手によって1711-1835年に続く王朝が生まれた。自らの艦隊を築き、ヨーロッパ諸国と直接条約に署名する半独立の構造が現れた。この時代は、1835年に州が直接中央に結びつけられて終わることになる。", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["ロシアとのエディルネ条約", "14901a70"], "d": ["プルートで行われた約束が履行されなかったため、さらに二度宣戦が行われ、ついにロシアが約束を受け入れてエディルネで恒久的な和平が結ばれた。条約はプルートの条件を確認した。ロシアはポーランドの事柄に干渉せず、コサックの土地から退き、スウェーデン王カール12世(デミルバシュ・シャルル)の帰国を妨げないとされた。北方戦線がこうして閉じたことで、オスマン国家は目をモレアとヴェネツィアの戦線に向けることができた。同日に編入されたその他の地:ホティン。", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["ヴェネツィアへの宣戦 - モレア遠征の準備", "d970b122"], "d": ["ヴェネツィアがモンテネグロの反乱者を支援したこと、オスマンの商船を拿捕したこと、カルロヴィッツで得たモレアを重税で圧迫したことを理由に、ディーヴァーンで開戦が決められた。大宰相スィラフダル・ダマト・アリ・パシャが準備した遠征は、翌年100日足らずでモレア半島全体を取り戻すことに終わることになる。ところがこの成功はオーストリアを動かし、1716年に遥かに重い戦争の扉を開くことになる。", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["ティノス(İstendil):ヴェネツィアのエーゲ海における最後の島の降伏", "4abec891"], "d": ["モレア遠征に向かう艦隊は、途上でヴェネツィアがエーゲ海に唯一残していた島ティノス(İstendil)の前に投錨した。ナクソス公国が1566年に陥落したにもかかわらず、ラテン系の住民のおかげでさらに150年ヴェネツィアの旗を掲げていた島は、短い包囲の後、血を流すことなく降伏した。こうしてエーゲ海におけるヴェネツィアの最後の足跡は消され、海は完全にオスマンの内海となった。", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["ナフプリオ(Anabolu)の征服 — モレアの鍵の要塞", "62a5808a"], "d": ["ヴェネツィアのモレアにおける首都で最も強力な要塞であったナフプリオ(Anabolu)は、パラミディの堡塁が9日間の砲撃の後に占領されたことで陥落した。要塞があまりにも早く取られたことが、半島の残りの地域の抵抗を砕いた。カルロヴィッツで失われたモレアの奪還は、事実上ここで完成した。同じ日に本アトラスでヴェネツィアからオスマンに移る他の定住地は、アルゴスである。これはAnabolu(ナフプリオ)の兄貴分中心地の連鎖に従う(TDV anabolu。宣言付きの近似)。", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["モドニの降伏", "43faa909"], "d": ["ナフプリオの陥落の後、モレアの南西端のモドニ要塞は、陸から軍、海から艦隊によって包囲され、まもなく降伏した。ヴェネツィアが東地中海の遠征で200年にわたって使ってきたこの港は、船が水と糧食を得る必須の寄港地であった。その喪失は、ヴェネツィア艦隊のエーゲ海における機動力を終わらせた。", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["コロニの降伏 — モレア遠征の完了", "e4b9c8a4"], "d": ["メッシニア湾の口を押さえるコロニ要塞が降伏したことで、モレア半島におけるヴェネツィアの統治は完全に終わった。カルロヴィッツで失われた半島は、遠征の開始からわずか3か月で完全に取り戻された。同じ遠征の続きとして、1715年9月にはイオニア海のAyamavra(レフカダ)島もヴェネツィアから奪われた。この速さはヴェネツィアにオーストリアを参戦させることを強い、3年後にパッサロヴィッツへの道が開かれた。", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["キティラ島(Çuha Adası)の占領", "494de6c6"], "d": ["モレアの南端にあるキティラ島(Çuha Adası)は、半島の完成の後に艦隊によって受け取られた。イオニア海とエーゲ海の間の通路を見張る島は、ヴェネツィアがこれらの海を統制するために使っていた前進基地であった。しかし、保持された唯一のオスマンの島として残りはしなかった。3年後にパッサロヴィッツでヴェネツィアに返還された。", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["オーストリアとヴェネツィアが同盟を結ぶ - 1716-1718年オスマン-オーストリア戦争への扉", "99511ca2"], "d": ["オスマンがモレアをヴェネツィアから取り戻したことを受け、オーストリアはカルロヴィッツ条約が破られたと主張してヴェネツィアと同盟条約を結んだ。オイゲン公は大宰相への書簡で、ヴェネツィアから奪った地の返還を求めた。ダヴト・パシャの陣営での協議で、大宰相アリ・パシャの圧力によりオーストリアに宣戦することが決まり、そのためシェイヒュルイスラームからファトワーが得られた。", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["大宰相アリ・パシャ、オーストリア遠征に出発", "2fbdce42"], "d": ["オーストリアへの宣戦の後、セルダール・エクレム(総司令官)アリ・パシャは10万を超える軍でオーストリア遠征に出発した。艦隊は同じ夏にコルフに向かった。軍はベオグラードからペトロヴァラディンに向けて進軍し、8月初めの敗北で大宰相が殉死することになる。", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["ヴァラディン(ペトロヴァラディン)の敗北 - ダマト・アリ・パシャの殉死", "265c1d81"], "d": ["ベオグラードからドナウ川を渡ったオスマン軍は、オイゲン公指揮下のオーストリア軍とヴァラディンの前で会戦した。最初の攻撃ではイェニチェリの突撃が敵の塹壕を突破したが、騎兵の翼が崩れて陣形が散り散りになった。大宰相スィラフダル・ダマト・アリ・パシャは額を撃ち抜かれて殉死し、陣営と砲兵部隊はすべて敵の手に落ちた。オスマンの年代記が「ヴァラディンの年」と呼ぶこの敗北は、ティミショアラの喪失と翌年のベオグラードの喪失に至る連鎖の最初の環であった。", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["コルフ島包囲戦の失敗", "b2aa7011"], "d": ["モレア軍司令官Kara Mustafa Paşaが陸から、海軍提督Canım Hoca Mehmed Paşaが艦隊を率いて海から、コルフ島を攻撃した。島はヴェネツィアのアドリア海における要衝であった。しかし要塞の防備が極めて堅固であったこと、ヴェネツィア艦隊が増援をもたらしたこと、ドナウ戦線からの敗報が届いたことにより、包囲は解かれた。コルフ島を攻略できなかったことで、モレア再征服で高まった戦勝気分は冷え込み、戦争の重心はハンガリーへ移った。", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["ティミショアラ(Timişvar)のオーストリアへの喪失", "27fe1365"], "d": ["ペトロヴァラディンでの敗北の後、オイゲン公は直接ティミショアラに進軍し、要塞は40日を超える包囲の末、降伏条件に従って明け渡された。1552年にスレイマン1世(カーヌーニー)の時代に征服され、164年間ベイレルベイ(州総督)の所在地としてハンガリー防衛の東の柱とされた都市は、こうして失われた。ティミショアラの陥落によりバナト地方の全域がオーストリアに移り、オスマン帝国の国境はドナウ川の南に押し戻された。同じ日に、本アトラスでオスマン帝国からハプスブルクへ移る他の定住地は、Csákóvár、Facset、Karánşebeş(Caransebeş)である。これらはティミショアラ州の移管に伴うものである(TDV timisvar。地点単位の日付は史料にない。兄貴分中心地の連鎖、宣言付きの近似)。", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Haram(Yeni Palanka)要塞のオーストリアへの引き渡し — バナトのドナウ河岸の喪失", "38ee4c6d"], "d": ["ティミショアラ陥落後、バナトの残りを取るよう命じられたオーストリアの騎兵大将メルシーは、11月14日にドナウ河岸のHaram(Yeni Palanka)に向けて進軍した。16日に要塞に到着すると、200人のオスマン守備隊は白旗を掲げ、自由に撤退できることを条件に降伏した。こうして1552年からオスマン帝国の手にあった南バナトのドナウ線もオーストリアに移った。同じ日に本アトラスでオスマン帝国からハプスブルクへ移るもう一つの定住地はVersecであり、Haramの兄貴分中心地の連鎖に従う(Bánlaky 0019/1703。宣言付きの近似)。", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["パッサロヴィッツ条約 — モレアを得て、ベオグラードとバナトを失った", "d46aa216"], "d": ["ヴェネツィアからモレアは取り戻されていたが、参戦したオーストリアはペトロヴァラディンとベオグラードで収めた勝利によって交渉の席で優位に立った。イギリスとオランダの仲介で署名された条約はモレアをオスマンに残し、その代わりベオグラードとともに北セルビア、バナト、小ワラキアがオーストリアに割譲された。TDVの表現では「北ボスニアは完全にオーストリアに残された」とされ、サヴァ川沿いのボスニア・ドゥビツァやボスニア・ブロドなどの要塞は、地図ではこの日からオーストリアに移る(正確な国境は委員たちが一つ一つ引き、TDVはこれらの要塞を名指ししない)。ヴェネツィアはイオニア海岸のプレヴェザやキティラなどの拠点を保った。同日に署名された通商アフドナーメにより、オーストリア商品に課される関税は5パーセントから3パーセントに引き下げられた。条約は、オスマン帝国の中央ヨーロッパからの後退を確認するとともに、開いた27年間の平和がチューリップ時代(1718年から1730年)の素地を築いた。Nevşehirli Damad İbrahim Paşaの統治下での最初のオスマン印刷所(1727年、イブラヒム・ミュテフェッリカ)、翻訳委員会、種痘の観察、新しい宮廷・文化生活は、この平和の年月の産物である。同日に本アトラスで手が替わるその他の定住地は、クラヨヴァ(Craiova)、Rimnik(Râmnicu Vâlcea)、トゥルヌ・セヴェリン(小ワラキア/オルテニア、オスマンからオーストリアへ)と、Ayamavra(レフカダ)(オスマンからヴェネツィアへ。TDV ayamavra:1718年にパッサロヴィッツ条約で島はヴェネツィアに譲られた)である。小ワラキアではさらにトゥルグ・ジウがオーストリアに、ヴォニツァ(Voniçe、TDV pasarofca-antlasmasi)とキティラ島(Çuha Adası、TDV cuka-adasi:パッサロヴィッツ条約第3条)がヴェネツィアに移る。", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["東方遠征 — トビリシの占領とイラン戦争の開始", "78343dc2"], "d": ["サファヴィー朝がアフガンの侵攻で崩壊し、ロシアがカスピ海沿岸に下りてきたため、オスマン帝国は空白がすべてロシアの影響下に入るのを避けるべく、東方に軍を送った。トビリシが占領されてグルジアはオスマン帝国の統治下に入り、続いてギャンジャ、エレヴァン、ナヒチェヴァンの方面へ進軍が続いた。チューリップ時代の平和な外観の裏で進められたこの遠征は、13年続き、最後には獲得したすべての地の返還で終わる長い東方の冒険の始まりとなった。", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["1723年のイラン遠征:シルヴァンとグルジアへの進入", "c81189fc"], "d": ["サファヴィー朝がアフガンの侵攻で崩壊したことを受けて、ロシアがカスピ海沿岸に下りるのを防ぐことを理由に、東方への遠征が開始された。エルズルム軍はグルジア経由でトビリシに、シルヴァン方面隊はシェマハに入り、130年前に失った土地を取り戻した。この遠征は、オスマンのコーカサスにおける最後の大きな前進となった。", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["ケルマーンシャーの占領 — ザグロスの門", "ad14799f"], "d": ["バグダード軍はザグロスの峠を越えて、イランの西の門とされるケルマーンシャーを占領した。都市はバグダードからイスファハーンに通じる隊商と軍の道上にあり、その占領はイラク州の東方の安全を確保した。この前進は、崩れたサファヴィー朝の領土をめぐるオスマンとロシアの分割競争を始めた。", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["イスタンブル条約 — イランのロシアとの分割", "fce8eec2"], "d": ["崩壊したサファヴィー朝の領土をめぐってオスマン帝国とロシアが衝突するのを避けるため、フランス大使の仲介で分割条約が結ばれた。カスピ海の西岸と南岸はロシアに、グルジア、シルヴァン、アゼルバイジャン、西イランの諸都市はオスマン帝国に残された。紙の上では大きな利得のように見えたこの分割は、ほどなくナーディル・シャーの台頭によって事実上無効となった。条約によりShabranやMüşkürなど、シルヴァンの肥沃な土地はロシア側に残された(Çaycıoğlu、DergiPark)。", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["ナヒチェヴァンの占領", "bdf14d0a"], "d": ["アラス川に沿って進んだオスマン軍は、ナヒチェヴァンとOrdubadを取り、ジョルファもナヒチェヴァン・リヴァーに加えられた。都市は、イランの北西の門として、新設のエレヴァン州に結びつけられた。こうしてオスマンの国境は、カーヌーニーの時代の最も東の線に再び達した。", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["ハマダーンの征服", "e1339a97"], "d": ["ケルマーンシャーから東に進んだ軍は、イラン高原の西の入口にあるハマダーンを長い包囲の後に占領した。都市は、オスマン軍が両イラク遠征以来到達できた最も東の地点であるイスファハーンへの道の最後の大きな宿営地であった。同年にロシアと署名されたイスタンブル協約は、崩れたイランのオスマンとロシアの間での分割を紙に書き表した。", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["エレヴァンの再征服", "88acabef"], "d": ["90日に及ぶ厳しい包囲の後、アラス川流域の鍵の要塞エレヴァンが再びオスマンの統治に入った。1583年に築かれ1604年に失われた要塞は、今度はより強力な守備隊で固められた。包囲の長さは、オスマン軍がもはや容易に進めないことの指標であった。Karpi(Üçkilise)、Şerür、Makû、Şüregelの各ナーヒエもエレヴァン州に結びつけられた。", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["タブリーズの占領 — アゼルバイジャンの掌握", "e502a4f7"], "d": ["前年の攻略失敗の後に再び包囲されたタブリーズは、一街区ごとに争われる激戦の末、オスマン軍に降伏した。タブリーズ州に属するMerend、Merâga、Sovukbulak(Mahabad)もオスマン帝国の統治下に入った。同年にはLori、ギャンジャ、Erdebil、Hürremâbâdも奪取され、イスタンブル条約でオスマン帝国の取り分とされた地域は事実上占領された。東方で到達したこの広がりは、Ferhad Paşa条約の時代以後で最も東に進んだ国境であったが、これを保持することは軍と財政に重い負担を課した。", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["ギャンジャの征服 — コーカサス遠征の終わり", "875bca7a"], "d": ["コーカサス作戦の最後の目標であったギャンジャは、クル川とアラス川の間のカラバフの中心として受け取られた。シルヴァン、エレヴァン、ナヒチェヴァン、ギャンジャの線の完成によって、オスマン帝国はコーカサスで1590年の広がりに達した。しかしこの獲得は短命であった。ナーディル・シャーの台頭が10年のうちに地域全体を取り戻すことになる。", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["ハマダーン条約 — 西イランのオスマン帝国への編入", "94a29dc3"], "d": ["アフガンの君主アシュラフ・シャーと結ばれた条約により、4年続いた戦争が終結し、オスマン帝国が占領した西イランの領土が法的に承認された。アシュラフ・シャーは見返りにオスマン帝国のスルタンのカリフ位を認め、イランでのフトバ(金曜説教)をスルタンの名で読むことを引き受けた。この外交上の勝利は短命に終わった。ナーディル・シャーが1730年に始めた反攻は、条約の成果を数年のうちに消し去ることになる。", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoğlu Ali Paşaがルーミーイェ(Rûmiye)を占領した", "eac7f64d"], "d": ["イラン遠征でHekimoğlu Ali Paşaはまずウルミア(Rûmiye)を、続いてオスマンに明け渡されたタブリーズを1731年11月15日に取った。TDVはウルミアの占領の日を示さない。年と、それがタブリーズより前であることだけが分かっている。", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Ahmed Paşa条約 — 西イランの大部分の返還", "590d839f"], "d": ["ナーディル・シャーがMelâyirで収めた勝利と相次ぐイランの攻勢を受けて、バグダード総督Ahmed Paşaは中央に諮らずに和平文書に署名した。条約によりアラス川が国境とされ、ハマダーン、ケルマーンシャー、Erdelan、Erdebil、タブリーズなどの西イランの都市がイランに返還され、ギャンジャとトビリシはオスマン帝国に残された。イスタンブルで反発をもって迎えられたこの文書は、ナーディル・シャーからも不十分とされ、1732年が終わらないうちに戦争が再燃した。本アトラスは、Hoyの連鎖に従うKoturもこの日にオスマン帝国からサファヴィー朝に移ったものとみなす(TDV hoy。Koturに固有の日付は史料にない — 宣言付きの近似)。", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["オラン(Vahran)の再度のスペインへの喪失", "20485027"], "d": ["スペイン王フェリペ5世が派遣した大規模な上陸艦隊が、モンテマール伯の指揮下でオラン沖に到着し、アルジェ軍団(オジャク)の部隊を敗走させて都市を奪還した。24年前に征服された港は、以後60年にわたってスペインの守備隊の手に残ることになる。西地中海におけるマグリブ諸オジャクの力の限界を示したこの喪失は、1792年のオラン最終征服によってようやく埋め合わせられた。", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["ハンバラジュ軍団のヨーロッパ式改革とHumbarahâneの設立", "d980cf2a"], "d": ["オスマン帝国に仕えたフランス出身のHumbaracı Ahmed Paşaは、大宰相Hekimoğlu Ali Paşaの支援を得て、ハンバラジュ(擲弾兵)軍団を俸給制でヨーロッパ式に編成された部隊に作り変えた。ボスニアで徴用された300人の兵に、算術と幾何学に基づく定期的な訓練が施され、編成、装備、退役のための新しい規則が整えられ、当時の技術で100門の擲弾砲と5万個の擲弾が製造された。幾何学が教えられたHumbarahâneは、オスマン帝国における近代的な軍事工学教育の最初の核とみなされる。", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["アフメト3世の死去", "455f7fba"], "d": ["パトロナ・ハリルの反乱で1730年に廃位されたアフメト3世は、生涯最後の6年をトプカプ宮殿の廃位されたスルタンのための居室で過ごし、63歳で亡くなった。バフチェカプのイェニ・ジャーミー脇にある、祖母トゥルハン・スルタンの廟に葬られた。", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["イスタンブル条約 — 南コーカサスのイランへの割譲", "8c205aab"], "d": ["4年続いた第二次イラン戦争は、アルパチャイでの敗北とギャンジャおよびトビリシの喪失の後に結ばれた条約で終わった。オスマン帝国は1723年から獲得してきた南コーカサスと西イランのすべての領土から撤退し、国境は1639年のKasr-ı Şîrin線に戻った。13年に及ぶ東方遠征の後には、重い財政負担と空になった国庫が残った。一方、ロシアとの新たな戦争が始まる中で、東部戦線が閉じられたことは死活的な利得であった。", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["オチャーコフ(Özi)要塞のロシアへの陥落", "f93e61f3"], "d": ["ミュンニヒ元帥率いるロシア軍が、ドニエプル河口のオチャーコフ要塞を包囲した。弾薬庫の爆発で防衛が崩れ、要塞は大きな人的損失を出して陥落した。黒海北西岸の鍵とされるオチャーコフの喪失は、クリミアへの道をロシアに開き、イスタンブルに大きな動揺を引き起こした。要塞は翌年、疫病と補給の困難のためロシアによって放棄され、再びオスマン帝国の手に戻ることになる。", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["バニャ・ルカの勝利 — ボスニアの解放", "f603865a"], "d": ["オーストリア軍がボスニアに侵入してバニャ・ルカを包囲すると、ボスニア総督Hekimoğlu Ali Paşaは現地の住民から集めた兵力で救援に駆けつけ、数で勝る敵に大敗を喫させた。この勝利はオーストリアのボスニア占領計画を最初の一手で挫き、州の北部は完全に奪還された。バニャ・ルカは、1683年以後オーストリアに対して後退を続けたオスマン軍の士気を回復させた転換点の一つとなった。", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["フルツカ(Hisarcık、Grocka)の勝利 — ベオグラードへの道の開通", "2101cdff"], "d": ["ベオグラードを守るために進軍したオーストリア軍は、ドナウ河岸の狭い隘路で待ち伏せされ、一日中続いた戦闘で大きな損害を出した。ヴァリス元帥の軍が乱れたままベオグラードに退くと、オスマン軍は要塞の前に迫り包囲を開始した。フルツカは、カルロヴィッツ条約以来オーストリアに対して収めた最も決定的な野戦の勝利であり、ベオグラードの奪還を直接もたらした。", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["ニシュ条約 — ロシアとの和平、アゾフの中立化とクリミアの襲撃の停止", "674f974e"], "d": ["オーストリアがベオグラードで和平に応じたため孤立したロシアは、フランス大使ヴィルヌーヴの仲介で戦争を終わらせざるを得なかった。アゾフ要塞の防御施設は破壊され、一帯は両国の間の中立地帯と宣言された。ロシアは黒海に軍艦や商船を置かないという条件を受け入れた。こうしてロシアの海への進出という目標は一世代先送りされ、オスマン帝国は18世紀に最後にして、利得を持って交渉の席を立った。", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["オチャーコフ(Özi)のロシア占領からの復帰 — 1739年の和約により要塞が破壊された後に引き渡された", "7ecc2bef"], "d": ["ロシアは1737年7月11日にオチャーコフを占領していた。1739年のロシアとの和約に基づき、要塞の防御施設が破壊された後、再びオスマン帝国に引き渡された。オスマン帝国はオチャーコフを、ヤッシー条約の前の1788年まで保持した。", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["モスルの防衛 — ナーディル・シャーの撃退", "c03ffbc1"], "d": ["キルクークとアルビールを占領してモスルの前に到着したナーディル・シャーは、40日間にわたって都市に砲撃を加え、次々に総攻撃を行った。総督Hüseyin Paşa el-Celîlîが市民にも武装させて指揮した防衛は、イラン軍に大きな損害を出させて包囲を解かせた。モスルが持ちこたえたことでイラク全体の喪失は避けられ、Celîlî家の都市での影響力は1世紀にわたって強まった。", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["ディルイーヤの盟約 — ナジュドにおける第一次サウード首長国の成立", "188751bf"], "d": ["ウヤイナから追放された学者ムハンマド・ブン・アブドゥルワッハーブをディルイーヤで庇護した首長ムハンマド・ブン・サウードは、彼と政治的権威を宗教的な呼びかけに奉仕させる盟約を結んだ。この合意はサウード家に新しい歴史を開き、ナジュドの分散したオアシス首長国を一つの運動のもとに結集させた。半世紀のうちにカルバラー、メッカ、メディナにまで及ぶことになるこの勢力は、オスマン帝国にヒジャーズにおける支配の防衛を強いることになる。", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Kerden条約 — オスマン・イラン戦争の終結", "1d3a919e"], "d": ["4年続いた最後の戦争の後に結ばれた条約で、1639年のKasr-ı Şîrin国境がそのまま更新され、双方とも領土の獲得はなかった。ナーディル・シャーがジャアファル派を第五の法学派として承認するよう執拗に求めたことは、報われなかった。その一方で、イランの巡礼者が自由に巡礼を行うことと、相互に使節を交換することが決められた。2世紀を超えるオスマン・イラン戦争はこうして事実上終わり、この国境は今日まで大筋で保たれている。", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["マフムト1世の死とオスマン3世の即位", "30203700"], "d": ["24年の治世にベオグラード条約で失った領土を取り戻し、ハンバラジュ軍団の改革を支援したマフムト1世は、金曜礼拝から戻る途中で亡くなった。後を継いだのは、58歳まで「鳥籠」(カフェス)の生活を送った弟のオスマン3世であった。短く不安定な治世が始まり、3年で6人の大宰相を替えたオスマン3世の時代には、国政に顕著な停滞が支配した。", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["オスマン3世の死とムスタファ3世の即位", "3ac10f85"], "d": ["3年の治世の後にオスマン3世が没すると、改革の考えに開かれ、国政に強い関心を示すムスタファ3世が即位した。新しいスルタンは、大宰相Koca Râgıb Paşaの経験に頼って財政を立て直し、軍を刷新しようと試みた。男爵ド・トットの速射砲兵はこの時期に創設された。しかし1768年に突入したロシアとの戦争は、17年に及ぶ治世のすべての成果を霞ませることになる。", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["ロシアへの宣戦 — バルタ事件と1768年から1774年の戦争の開始", "9c6aabe0"], "d": ["ポーランドのバール連盟を追うロシア軍とコサック部隊が、オスマン帝国の国境にあるバルタの町を襲って焼いたため、ディヴァン(御前会議)は開戦を決議し、ロシア大使はイェディクレ(七塔)に投獄された。本格的な軍事準備をせず、6か月前に宣言して始められたこの戦争は、最初からうまく進まなかった。6年続くこの戦いは、チェシュメの奇襲、カグールの敗北、クリミアの占領を経て、オスマン史上最も重い敗北の連続の一つとなった。", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["ホティン要塞のロシアへの喪失", "66d43ea4"], "d": ["ゴリツィン公率いるロシア軍の二度の試みが退けられていたが、カミャネツとホティンの間で大宰相が被った敗北を受けて軍は後退し、守備兵が要塞を明け渡した。ドナウ川以北で最も強力なオスマンの要塞が抵抗もなく失われたことは、ワラキアとモルダヴィアの門をロシアに開いた。両公国は同年に占領され、ホティンは1774年のキュチュク・カイナルジャ条約でようやく取り戻された。", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["カグール(Kartal)平原の敗北", "6f408eaf"], "d": ["チェシュメで艦隊が焼かれてから3週間後、ドナウ沿いのオスマン主力軍は、カグール平原でルミャンツェフ元帥の、数ではるかに小さいが規律ある部隊の前に潰走した。陣営、輜重、数百門の大砲が敵の手に落ち、逃げる部隊はドナウを渡るときに大きな損害を出した。同じ夏のうちに艦隊と陸軍の両方が壊滅したことは、Kili、Akkirman、İsmail、Benderが相次いで陥落し、クリミアが占領される原因となった。", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["ロシアによるクリミア半島の占領", "217837b0"], "d": ["前年にブジャクを占領していたロシア軍は、ドルゴルーコフ公の指揮でOr Kapı(ペレコプ地峡)を越え、クリミア半島の全域に侵入した。ハンは廃位され、親ロシアのSâhib Girayが即位させられて、ハン国をオスマン帝国から切り離す最初の一歩が踏み出された。3世紀にわたりオスマン帝国の北の盾であったクリミアの喪失は、1774年の独立、1783年の直接併合へ至る過程の始まりであった。", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["ムスタファ3世の死とアブデュルハミト1世の即位", "42cba8e2"], "d": ["ロシア戦争の最も危機的な時期に没したムスタファ3世に代わり、43年を宮殿の「鳥籠」(カフェス)で過ごした弟のアブデュルハミト1世が、49歳で即位した。国家の最も困難な時期の一つを引き継いだ新しいスルタンは、同年に結ばれるキュチュク・カイナルジャ条約の重い条件と向き合わざるを得なかった。15年の治世はクリミアの喪失と新たなロシアとの戦争のうちに過ぎ、1789年にオチャーコフ陥落の報を読んでいるときに起きた卒中で終わることになる。", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Kozluca(コズルジャ)の敗北 — キュチュク・カイナルジャへ至る敗戦", "8e0542f9"], "d": ["シュメンの前に集結したオスマン軍は、Kozlucaでスヴォーロフとカメンスキーの合同部隊に敗れ、軍の大部分が潰走した。この敗北によってバルカンには抵抗できる戦力が残らず、ロシアの先鋒はシュメンを包囲し、大宰相の本営は脅威にさらされた。1か月もたたないうちにキュチュク・カイナルジャで交渉の席に着き、並外れて重い条件が受け入れられたのは、直接にはこの敗北の結果である。", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["ブコヴィナ(北モルダヴィア)のオーストリアへの割譲", "190f9caa"], "d": ["キュチュク・カイナルジャがもたらした弱体化につけ込んだオーストリアは、モルダヴィアとトランシルヴァニアを結ぶブコヴィナ地方を要求し、戦争に入ることなく、脅しと賄賂によってこの土地を手に入れた。ホティンの南西にあるこの肥沃で戦略的な地域の喪失は、モルダヴィア公国を事実上二つに分けた。一発の弾も撃たれずに行われたこの割譲は、オスマン帝国が抑止力を失ったことを示す最も明白な徴候の一つとされた。1775年のブコヴィナ割譲によりスチャヴァとチェルニウツィーがオーストリアに移った(日付は未確認)。", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["バスラのイランによる占領", "0161e709"], "d": ["ザンド朝の君主カリーム・ハーンの弟サーディク・ハーンは、1年に及ぶ包囲の末にバスラを占領し、オスマン帝国はペルシア湾で最も重要な港を失った。この占領はインド貿易路、ナツメヤシと真珠の収入、イラク南部の防衛を直接揺るがした。都市は、カリーム・ハーンの死(1779年)の後にイランで起きた王位争いのさなかに、ようやく取り戻された。", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Aynalıkavak協定書 — クリミアをめぐる一時的な妥協", "9b3b0468"], "d": ["クリミア・ハン国の首長に誰が就くかをめぐって開戦の瀬戸際にあった両国は、フランスの仲介でAynalıkavak離宮において説明文書に署名した。ロシアはクリミアから軍を撤退させ、オスマン帝国は親ロシアのシャーヒーン・ギレイのハン位を承認することに同意した。クリミアに対するスルタンの宗教上のカリフとしての権利は再確認された。4年続くことになるこの脆い均衡は、1783年のロシアによる半島の直接併合で完全に崩れた。", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["アナパ要塞の建設 — コーカサスの防衛線", "be92a80f"], "d": ["キュチュク・カイナルジャでクリミアが失われたため、コーカサスにおけるオスマンの影響力を守るべく、クバン川の河口に新たな要塞の建設が始められた。ジェノヴァ植民地の遺構の上に築かれたアナパは、市場、浴場、250を超える店とともに、まもなくチェルケスの部族との連絡を確保する都市となった。要塞は、ロシアのコーカサスへの降下に対して、48年にわたってオスマンの最も前進した拠点であり続けた。", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["大宰相Halil Hamîd Paşaの罷免と処刑", "c44001ca"], "d": ["アブデュルハミト1世が様々な機会にその働きへの満足を示していた改革派の大宰相Halil Hamîd Paşaは、1785年3月31日の朝方に突然罷免されてゲリボルに流され、全財産が没収された。まず彼にはハベシュ州、ジッダ・サンジャク、メッカのシェイヒュルハレム職が与えられたが、1785年4月を出発の準備でボズジャアダで過ごしているうちに、この総督職からも罷免され、出された死刑の勅令により、Cezayirli Gazi Hasan Paşaの部下Karakethüdâzâde Aliによって殺された。切られた首はイスタンブルに送られ、オルタカプで晒された。TDVによれば、この突然の失脚は、スルタンを廃位して代わりにシェフザーデ・セリムを据える企てがあったという嫌疑で解釈されたが、本当の理由は、クリミアの併合に沈黙したことへの憤り、改革で害を被った層の敵意、Gazi Hasan Paşaの反対であったと考えられる。", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["ロシアへの宣戦 — 1787年から1792年のオスマン・ロシア戦争の開始", "3bfb870c"], "d": ["エカチェリーナ2世の華々しいクリミア行幸と、グルジアを保護下に置いたことを受けて、ディヴァンは併合を覆すことを目的に開戦を決議し、ロシア大使は再びイェディクレに幽閉された。しかし軍は準備ができておらず、国庫は空であり、同盟国探しは実を結ばなかった。5年続く戦争は、オチャーコフの虐殺を伴う陥落、イズマイルの喪失、ヤッシー条約の重い条件で終わることになる。", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["オーストリアの参戦 — 二正面の戦い", "ae912290"], "d": ["1781年にロシアと結んだ秘密同盟に基づき、オーストリア皇帝ヨーゼフ2世はオスマン帝国に宣戦してベオグラードとボスニアの方面に動いた。オスマン軍は突如として、北でロシア、西でオーストリアという二つの戦線で同時に戦わなければならなくなった。Lazarethane、Muhâdiye、Şebeşでオーストリア軍に対して収めた勝利にもかかわらず、1789年のベオグラードの喪失で西部戦線も崩れることになる。", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["オスマン・プロイセン同盟", "03b88e51"], "d": ["即位するや否やヨーロッパに同盟国を求めたセリム3世は、プロイセンと相互援助を定める同盟条約に署名した。プロイセンはロシアとオーストリアに宣戦すること、オスマン帝国はクリミアを取り戻すまで和平を結ばないことを約束した。これはオスマン史上、ヨーロッパの国と結ばれた最初の真の相互同盟文書であり、古典的な「異教徒との同盟はあり得ない」という考え方が放棄されたことを示していた。プロイセンは参戦しなかったが、オーストリアに和平を強いることで、シストヴァ条約への道を開いた。", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["イズマイル要塞の陥落と虐殺", "6a296b0c"], "d": ["ドナウ・デルタで最も強力な要塞とされたイズマイル要塞は、スヴォーロフ将軍が行った血まみれの総攻撃によって一日で陥落し、守備隊と市民の多くが剣で殺された。ヨーロッパで大きな反響を呼んだこの虐殺は、オスマンの世論に深い衝撃を与え、ドナウ防衛線の背骨を折った。要塞は1年後にヤッシー条約で取り戻されることになるが、戦争の帰趨はすでに決まっていた。", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["シストヴァ条約 — オーストリア戦線の終結", "58741f1d"], "d": ["プロイセンの圧力と、フランス革命がオーストリアを西側で忙殺したことにより、両国は戦前の国境を基準として和平に達した。オーストリアは占領したベオグラードを含むすべての地を返還し、オスマン帝国はクロアチア国境の小さな修正を受け入れただけであった。西部戦線がこの条件で閉じられたことは、オスマン帝国がすべての力をロシアに向けて集めることを可能にし、ヤッシー条約での損失を限定した。クロアチア国境でのこの修正により、Cetin(Cetingrad)とDrežnik Gradがオスマン帝国からハプスブルクに移る(TDV zistovi-antlasmasi。Korić 2016、n. 118、第4条)。Orsova(Eski Orsova)は返還されなかった唯一の地である(Bánlaky 0019/1796)。本アトラスは法的な移管をこの日に記す(実際の占領は1790年4月16日)。", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["ヤッシー条約 — クリミアの最終的喪失とドニエストル川の国境", "a56fd194"], "d": ["5年に及ぶ戦争の末に署名された条約で、Turla(ドニエストル)川が国境とされた。川の左岸はロシアに、右岸はオスマン帝国に残され、オチャーコフとその周辺は最終的に失われた。オスマン帝国はクリミアを取り戻す望みを完全に捨て、1783年の併合を法的に承認した。ワラキアとモルダヴィアは2年間の免税とともに返還された。1200万クルシュの戦争賠償の義務も受け入れられ、黒海の北岸は恒久的にロシアに割譲されることになった。同日に編入されたその他の地は、İsmailである。", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["オラン(Vehrân)のスペインによる撤退とアルジェへの引き渡し", "9f95cee6"], "d": ["1790年の地震で要塞と都市が大きく破壊されると、3世紀にわたって維持してきた費用のかさむ守備隊をもはや支えられなくなったスペインは、アルジェ・オジャクと合意してオランとマルス・エル・ケビールを戦わずに引き渡した。こうして北アフリカ海岸の最後のヨーロッパの拠点も清算された。オスマンのアルジェは、フランスの占領まで続く38年間、海岸全体を支配し続けた。", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Pazvandoğlu Osmanのヴィディンにおける事実上の支配", "0ce70361"], "d": ["ニザーム・ジェディード(新秩序)の施策に反対して蜂起したPazvandoğlu Osmanは、ヴィディン総督を逃亡させて都市を掌握し、ドナウ沿いに深い堀で要塞化した。1797年には力の絶頂期に8万に近い兵力を集め、ニコポル、シストヴァ、ルセ、ソフィア、ニシュを支配下に置いた。彼は自らを反逆者ではなく改革者として示した。1798年から1799年にかけて数か月続いたオスマン政府(Bâbıâli)の包囲は実を結ばず、彼は1807年の死まで北ブルガリアで半独立の支配を続けた。", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Mühendishâne-i Berrî-i Hümâyun(陸軍工学校)の開設", "e9a3a34b"], "d": ["ニザーム・ジェディード軍に砲兵、築城、測量の将校を養成するため、ハスキョイに陸軍工学校が開設された。1773年に設立された海軍工学校の陸軍における対応物であった。課程では代数、幾何、力学、築城、弾道学が教えられ、ヨーロッパ諸語から数学と砲術の書物が翻訳された。トルコにおける近代的工学教育の源とされるこの学校は、今日のイスタンブール工科大学の始まりとみなされる。", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["フランスへの宣戦とロシア・イギリスとの同盟", "80e95bd7"], "d": ["ナポレオンのエジプト侵攻を受けて、オスマン帝国は2世紀半に及ぶ伝統的なフランスとの友好を破り、フランスに宣戦した。同じ過程で歴史上初めてロシアと同盟を結び、ロシア艦隊がボスポラス・ダーダネルス両海峡を通って地中海に出ることを許した。続いてイギリスとも同盟が結ばれた。これらの同盟によりイオニア諸島がフランスから奪われたが、海峡が外国の艦隊に開かれたことは、のちに重い代償を伴う先例となった。", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["フランスからのプレヴェザの奪取 — ニコポリスの戦い", "d8e5e892"], "d": ["ヴェネツィア共和国が1797年に滅びると、イオニア諸島と本土のプレヴェザ、パルガ、ヴォニツァはフランスの手に渡った。ヨアニナ総督Tepedelenli Ali Paşaは、フランスのエジプト侵攻を受けて始まった戦争を利用してプレヴェザに進軍し、都市の外にあるニコポリスの遺跡でフランス守備隊に大敗を喫させた。こうして、パッサロヴィッツでヴェネツィアに残されたこの港は、80年後にオスマンの統治に入った。ブトリント(Butrinto)はフランスの守備隊が防備を爆破してコルフ島に退いたため10月25日に陥落し(Curlin、Preveza B、2010。本アトラスの日付はプレヴェザから取る)、オスマンの統治に入った。", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["アッコの防衛 — ナポレオンの撃退", "56b5c45b"], "d": ["エジプトからシリアに進軍したナポレオンはアッコを包囲し、2か月にわたって次々に攻撃を加えた。都市は、Cezzâr Ahmed Paşa、イギリス艦隊の支援、イスタンブルから送られたニザーム・ジェディード部隊によって守られた。包囲を解いてエジプトに退かざるを得なかったナポレオンは、東方に手を伸ばす夢をこの城壁の前に葬った。報せはイスタンブルで大きな喜びをもって迎えられ、新設の訓練された軍が最初の本格的な試験を乗り越えた証とみなされた。", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["ワッハーブ派によるカルバラー襲撃", "522341ed"], "d": ["ナジュドから出陣したワッハーブ派の軍はカルバラーに入って都市を略奪し、フサイン(ホセイン)の廟を破壊して、3000人以上を殺害した。オスマン帝国のイラクにおけるマムルーク出身の総督たちは襲撃を防げず、この事件はイランでもイスタンブルでも大きな反発を呼んだ。この襲撃は、サウード運動がもはやオアシスの首長国ではなく、オスマン帝国の聖都を脅かす地域的な勢力へと変わったことの宣言であった。", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["カルトリ・カヘティ(東グルジア)のロシアへの併合", "3b650c5e"], "d": ["1783年にロシアの保護を受け入れ、1795年にイランの破壊的な遠征を被ったカルトリ・カヘティ王国は廃され、1801年9月12日付の命令でロシアの一州と宣言されて、ロシアの行政制度が据えられ始めた。グルジアはこの日から独立を失った。数年のうちにミングレリア(1803年)、イメレティ、グリア(1804年)もロシアの支配に入り、ロシアはオスマンのコーカサス国境に迫った。この件によりゴリ、ドゥシェティ(カルトリ)、テラヴィ(カヘティ)がロシアに移った。", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["フランスからのエジプトの解放", "00cfdc8c"], "d": ["オスマン軍とイギリス軍の陸海共同作戦の結果、まずカイロが、次いでアレクサンドリアが受け取られ、フランス軍は船で本国に送られた。3年に及んだ占領が終わり、エジプトは紙の上ではオスマン帝国の統治に戻ったが、マムルーク出身のベイたちとアルバニア人部隊との間の支配権争いが国を混乱に陥れた。この空白は、数年のうちにカヴァラ出身のムハンマド・アリーが台頭する素地を整えることになる。", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["パリ条約 —フランスとの和平の再構築", "1b76991f"], "d": ["エジプトの解放の後に署名された条約によって、オスマン帝国とフランスの間の戦争状態は正式に終わり、旧来のカピチュレーション(通商特権)が更新された。フランスの商船が黒海に入ることが許され、その代わりにフランスはオスマン帝国の領土保全を承認した。和平の成立は、ロシアとイギリスの間で身動きが取れなくなっていたセリム3世の外交に、再び機動の余地を与えた。", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["ワッハーブ派によるターイフの占領", "7b791359"], "d": ["サウード・ブン・アブドゥルアズィーズ率いるワッハーブ派の軍は、ヒジャーズへの最初の攻勢でターイフを包囲して略奪した。都市は聖地に開かれた最初の門として陥落した。両聖都(ハラマイン)の守護者の称号を持つオスマン帝国のスルタンにとって、これは統治の正統性を直接揺るがす一撃であった。2か月半後、同じ軍がメッカに進軍することになる。", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["ワッハーブ派による最初のメッカ占領", "21157c05"], "d": ["ターイフの陥落から2か月半後、ワッハーブ派の軍はメッカに入って廟を破壊し、自らの理解に従った秩序を打ち立てた。Şerif Gālibはジッダに退かざるを得なかった。巡礼路が閉ざされたことはイスラーム世界全体に響き、イスタンブルはエジプト総督ムハンマド・アリーに軍事支援を求めざるを得なくなった。この最初の支配はわずか3か月しか続かなかった。", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Şerif Gālibによるメッカの奪還", "83d08dff"], "d": ["ジッダに退いていたŞerif Gālibは、集めた兵力でメッカを包囲し、25日間の包囲の後に都市をワッハーブ派から取り戻した。オスマン帝国の名でフトバが再び読まれた。この二度目の支配も長続きせず、サウードの軍は1806年に都市を再び奪うことになる。", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["第一次セルビア蜂起の開始", "0f6e8767"], "d": ["ベオグラードで政権を握った反乱イェニチェリのダヒヤ(頭目)たちがセルビアの有力者を集団で虐殺したことを受けて、カラジョルジェを指導者とする武装抵抗が始まった。当初はスルタンに忠実なまま、ダヒヤのみに対して行われた運動は、まもなく自治と独立を求める民族的な蜂起へと変わった。セルビア軍は1806年にベオグラードを占領した。この蜂起は、バルカンにおける民族主義的な独立運動の最初の環となった。", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["ワッハーブ派によるメディナの占領", "84e310d7"], "d": ["メッカに続いてメディナもワッハーブ派の軍の手に落ちた。預言者の廟(ラウダ)の宝物は分配され、都市のドーム付きの廟は破壊された。こうして二つの聖都が同時にオスマンの支配を離れ、ダマスカスとエジプトから来る巡礼隊は何年も出発できなかった。メディナは7年後の1812年に、ムハンマド・アリー・パシャの息子Tosun Paşa率いるエジプト軍によってようやく取り戻された。", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["ロシアとの戦争の開始(1806年から1812年のオスマン・ロシア戦争)と海峡の閉鎖", "ea170804"], "d": ["ナポレオンのアウステルリッツでの勝利の後にフランスに接近したセリム3世が、ロシアの圧力にもかかわらずワラキアとモルダヴィアの公を罷免したため、ロシア軍は二つの公国を占領し、戦争が始まった。オスマン帝国は海峡をロシア艦隊に対して閉ざした。これに対してイギリスもロシアの側に立ち、イスタンブルに艦隊を派遣した。6年続くこの戦争は、カバクチュ蜂起とセリム3世の廃位と絡み合い、1812年のブカレスト条約でのベッサラビアの喪失で終わることになる。", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["イギリス艦隊のイスタンブル沖到来(ダックワース作戦)", "195bb58f"], "d": ["オスマン帝国にフランスとの絆を断たせようとしたイギリスは、ダックワース提督率いる艦隊をダーダネルス海峡経由で通過させ、イスタンブル沖に投錨させた。フランス大使セバスティアーニの指導もあってイスタンブルの住民は動員され、海岸砲台は数日のうちに増強された。都市は砲撃されないまま艦隊は退却を余儀なくされ、帰路のダーダネルスで大きな損害を出した。首都が外国の艦隊によってこれほど間近に脅かされたのは初めてで、海峡問題はヨーロッパ外交の中心に置かれることになった。", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["ムスタファ4世の絞殺", "eeb75c20"], "d": ["Alemdar Mustafa Paşaが襲撃を受けて死に、反乱者たちが宮殿に進もうとしたため、廃位されたムスタファ4世は弟マフムト2世の命令で絞殺された。遺体はバフチェカプの父アブデュルハミト1世の廟に葬られた。反乱者の間には、棺は空だという噂が広まった。", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Kal'a-i Sultâniyye条約(ダーダネルス条約) — イギリスとの和平と海峡の原則", "fe282117"], "d": ["ダックワース作戦の失敗の後にイギリスと署名された条約によって両国間の戦争は終結し、イギリス商人の旧来の特権が返還された。条文にある「古来の原則(カディーム・カイデ)」と呼ばれる規定は、平時にはいかなる外国の軍艦も海峡を通過できないと定めた。この原則は、19世紀を通じて海峡体制を形づくるすべての国際的取り決めの法的な拠り所となった。", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["スロボジアの敗北 — ドナウ軍の包囲", "54b60fd1"], "d": ["ルセ(Rusçuk)の前でドナウを渡ったオスマン軍の大部分は、クトゥーゾフが川の対岸から行った包囲機動によってスロボジアで追い詰められ、飢餓にさらされた。数千の兵が降伏せざるを得なかった。大宰相の手元の戦力は事実上溶けてなくなり、オスマン政府は1か月後に休戦を求めざるを得なかった。この敗北が、1812年のブカレスト条約でベッサラビアの割譲に同意した直接の理由である。", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["ベオグラードの奪還と第一次セルビア蜂起の鎮圧", "06f56f52"], "d": ["ブカレスト条約によってロシアの支援を失ったセルビアの蜂起軍は、ボスニアとルメリアから来た軍の共同作戦に耐えられなかった。Hurşid Ahmed Paşaがベオグラードに入り、9年に及んだ蜂起は完全に鎮圧された。カラジョルジェはオーストリアに逃れ、スメデレヴォのサンジャクは再びオスマン帝国の直接の統治に組み込まれた。しかし、実施された厳しい措置は、2年後にミロシュ・オブレノヴィチを指導者とする二度目の、そして恒久的な蜂起を引き起こすことになる。", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["第二次セルビア蜂起とミロシュ・オブレノヴィチの首席クネズ就任", "e6e82ad2"], "d": ["第一次蜂起の鎮圧後に実施された重い措置に対して、ミロシュ・オブレノヴィチを指導者とする新たな蜂起が勃発した。今回オスマン政府は武力でなく妥協を選んだ。結ばれた合意により、ミロシュは「首席クネズ」の称号で認められ、徴税と内政の運営の権限がセルビアのクネズたちに委ねられた。事実上の自治のこの最初の核は、1830年の勅令と1878年の独立へと続く過程の出発点となった。", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["ワラキア蜂起 — イプシランティスのプルト川渡河とウラディミレスクの蜂起", "67d46a98"], "d": ["ロシア軍の将軍であったアレクサンドロス・イプシランティスは、フィリキ・エテリアの名でプルト川を渡り、ワラキアとモルダヴィアでギリシア人の全面蜂起を起こそうと試みた。同じころトゥドル・ウラディミレスクも現地の農民を動かした。二つの運動は合流できなかった。ウラディミレスクは、イプシランティスのともにトルコ人と戦おうという呼びかけに「私はトルコ人に対してでなく、ギリシア人に対して立ち上がったのだ」と答え、まもなくイプシランティスの部下に殺された。蜂起は5月にオスマン軍によって鎮圧されたが、ファナリオット(ファナル出身)の公位の制度は終わり、蜂起の火はモレアに飛び火した。", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["第二次サウード国のリヤドにおける成立", "34dad3bd"], "d": ["1818年のディルイーヤ陥落と第一次サウード国の滅亡から6年後、トゥルキー・ブン・アブドゥッラーはエジプトの守備隊をナジュドから追い出し、リヤドを中心とする新たなサウード首長国を打ち立てた。新しい体制はヒジャーズへの進出を避けてナジュドにとどまることを選び、オスマン・エジプト軍との直接衝突を遠ざけた。この第二の国は世紀の終わりまで続き、今日のサウジアラビアの建国に至る連鎖の第二の環をなすことになる。同じ日に失われた他の定住地は、ディルイーヤ(ナジュド)である。", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["アッケルマン条約 — セルビアと公国への譲歩", "c75f15d0"], "d": ["イェニチェリ軍団の廃止の直後で軍を持たなかったオスマン帝国は、ロシアの最後通牒の前に厳しい条件の条約を受け入れざるを得なかった。セルビアに約束された自治は再確認され、ワラキアとモルダヴィアの公(ヴォイヴォダ)はロシアの承認なしに罷免できないことが認められ、ロシアの商船には海峡での完全な自由が認められた。オスマン政府が2年後にギリシア問題を理由にこの条約を承認しないと宣言すると、ロシアはそれを開戦の口実とすることになる。", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["ティマール制の廃止", "84d5d1d6"], "d": ["イェニチェリ軍団の廃止から1年後、ルメリアとアナトリアの53のサンジャクにいた約5200人のティマール保有騎兵(シパーヒー)は、ティマールの収入とともにアサーキリ・マンスーレ(新軍)の騎兵に転換された。これによってオスマンの土地、税、軍の制度の4世紀にわたる背骨であったティマール制は事実上終わった。空いたティマールは国庫に移され、中央から俸給を受ける軍と現金税の制度への移行への道が開かれた。", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Tıphâne-i Âmire(帝国医学校)の設立 — 近代医学教育の始まり", "ac3e57c0"], "d": ["新設のアサーキリ・マンスーレ軍に医師と外科医を養成するため、侍医長Mustafa Behçet Efendiの提案によって、シェフザーデバシュにTıphâne-i Âmireが開設された。授業はヨーロッパの課程に従って組まれ、教育は当初フランス語で行われた。数年後にCerrahhâne-i Âmireも設けられ、二つの機関は統合された。トルコにおける近代医学教育の始まりとされるこの学校は、今日のイスタンブル大学医学部の源とみなされる。", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["1828年から1829年のオスマン・ロシア戦争の開始", "9dff4e05"], "d": ["ナヴァリノで艦隊が焼かれ、オスマン政府がアッケルマン条約を承認しないと宣言したことを受けて、ロシアは二つの戦線で同時に戦争を始めた。イェニチェリ軍団が廃止されたばかりで、新しい軍は編成の途上にあったため、オスマンの防衛は最初から弱かった。ロシア軍がドナウを渡るとともに、東ではカルスとアハルツィヘを奪った。1年のうちにエディルネまで進んだロシア軍は、1829年のエディルネ条約の重い条件とギリシアの独立を押しつけることになる。", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["アメリカ合衆国との最初の条約", "d737516f"], "d": ["長年の接触の後に署名された通商航海条約により、アメリカ合衆国はオスマン領において最恵国待遇と、海峡における商業通航の権利を得た。別の秘密条項は、オスマン帝国が望むときにアメリカの造船所で船を建造させ、完成船と木材を購入することを定めていた。アメリカ上院は条約を批准したが、この秘密条項は18対27で否決した。それでも造船の道は閉ざされなかった。ヘンリー・エックフォードは1831年に持ち込んだ船をオスマン帝国に売り、Aynalıkavakで働くアメリカ人の職人たちは海軍に新型の船をもたらした。この条約は、オスマン帝国がヨーロッパ以外の国と結んだ最初の包括的な関係の文書となった。", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["バグダードにおけるマムルーク支配の終結", "7e1d38a3"], "d": ["中央集権化政策を進めるマフムト2世は、求められた金を送らず、中央から来た役人を殺させたバグダード総督Dâvud Paşaを反逆者と宣言した。Ali Rızâ Paşa率いる部隊は90日に及ぶ包囲の末に都市を占領し、マムルークはほぼ完全に一掃された。こうして1704年から続いた半独立のマムルーク統治は終わり、イラクは再び中央に直接結びつけられた。", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Mekteb-i Harbiye(陸軍士官学校)のマチカ兵営における設立", "bf31c7d9"], "d": ["アサーキリ・マンスーレ・ムハンメディイェにヨーロッパ式に教育された将校を供給するため、マチカ兵営にMekteb-i Fünûn-ı Harbiyyeが開設された。学生には数学、地図、築城、外国語が教えられ、まもなくウィーンとパリに学生が派遣されて人材が強化された。この学校は、オスマン軍における学校出身将校の伝統と、ひいては19世紀末に現れる新しい軍人知識人の世代が生まれた場所となった。", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["トリポリの中央への直接編入 — カラマンリー朝の終わり", "faabcb96"], "d": ["カラマンリー家内部の王位争いと、フランスが1830年にアルジェを占領して以後高まったヨーロッパの圧力を受けて、オスマン政府はトリポリに直接介入した。イスタンブルから送られた艦隊が都市に入り、最後のカラマンリーのベイは罷免されてイスタンブルに連れてこられ、州は中央から任命される総督に引き渡された。124年にわたる王朝の時代が終わる一方、北アフリカでオスマン帝国が直接統治する最後の領土が固められた。", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["デフテルダール職の廃止と財務省(Maliye Nezâreti)の設置", "89f8125e"], "d": ["古典期オスマンの財政制度の長であったデフテルダール(財務長官)の職が廃止され、ヨーロッパ式の省である財務省が設置されて、分散していた国庫が一つにまとめられた。同年にはオスマン政府の他の部局も「ネザーレト(省)」の名のもとに再編され、近代的な閣僚会議の構造に移行した。この再編は、1年後に宣言されるタンジマート勅令の行政的な基盤を整えた最も重要な一歩の一つであった。", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["イギリスのアデンへの定着", "ddbd556b"], "d": ["イギリスは、1802年にラヒジュのスルタンAhmed b. Abdülkerîmと結んだ通商友好協定を根拠にアデン港に兵を上陸させ、都市を支配下に置いた。紅海の入り口を押さえるこの港は、インドへの道の石炭補給基地として、イギリス帝国戦略の要所となった。オスマン帝国のイエメンに対する主張は紙の上では続いたが、南岸における実効支配は、この日以後二度と戻らなかった。", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["ティハーマ海岸への復帰:ホデイダ、ザビード、モカの掌握", "353982d2"], "d": ["エジプト軍が1840年に撤退して主のなくなったイエメンの海岸に、メッカのシャリーフの監督のもとで、Tevfik Paşa率いる部隊が上陸し、ホデイダ、ザビード、モカの港をオスマンの統治に組み込んだ。サナアまで進むことが望まれたが、住民の抵抗のためホデイダに引き返した。こうして高地はザイド派のイマームたちの手に残り、オスマンの支配は23年間、ティハーマの帯状地帯だけに続いた。内陸イエメンは1872年のAhmed Muhtar Paşaの遠征でようやく取り戻されることになる。", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Baltalimanı協約:ワラキアとモルダヴィアにおけるオスマン・ロシアの共同保護", "d3bb22e9"], "d": ["1848年の革命がワラキアとモルダヴィアに波及したため、オスマン軍とロシア軍は両公国を共同で占領していた。Baltalimanıで署名された協約により、公(ヴォイヴォダ)を選挙でなくスルタンが7年任期で任命すること、および両国が地域で共同の監督を行うことが決められた。この合意はオスマンの紙の上の宗主権を保つ一方でロシアに実質的な共同の権利を認め、ドナウ公国のオスマンからの離脱を早めた。", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["ハンガリー難民問題:コシュートらのオスマン帝国への庇護申請", "1c7d7ef4"], "d": ["1848年から1849年のハンガリー革命がロシアとオーストリアの介入で鎮圧されたため、ラヨシュ・コシュートと数千人のハンガリー人・ポーランド人の難民がオスマン領に逃れた。オーストリアとロシアは難民の引き渡しを強硬に要求したが、オスマン政府はイギリスとフランスの支持を得て引き渡しを拒み、一行をキュタヒヤに入れた。コシュートの周辺はここに約18か月とどまり、数百人の難民はイスラームに改宗してオスマンに仕えた。この事件は、タンジマート期のオスマン帝国のヨーロッパの世論における評価を高めた、数少ない外交上の勝利の一つとされた。", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Encümen-i Dâniş(学術協会)の設立:イスタンブルにおける最初のオスマン・アカデミー", "6fda1365"], "d": ["普通教育評議会(Meclis-i Maârif-i Umûmiyye)の決定で設立されたEncümen-i Dânişは、トルコ語の学術書と教科書を準備するために組織された最初のオスマンの学術アカデミーである。1851年7月18日にDârülmaârif(教育館)の建物で式典とともに開かれ、国内外の会員の中にはAhmed Cevdet Paşaもいた。短命ではあったが、Cevdet Paşaの『Târih』や『Kavâid-i Osmâniyye』などの著作はこの機関の成果であり、トルコ語が学術語となる上での礎石とみなされた。", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["オルテニツァの勝利:ドナウ戦線における最初のオスマンの成功", "a660ad2f"], "d": ["クリミア戦争の開戦期に、総司令官Ömer Lütfi Paşaはドナウを渡り、オルテニツァでロシア軍を大きな損害を出させて撃退した。この勝利は戦争のごく初めにロシアの前進を止め、オスマン軍がタンジマート後の教育によって得た力をヨーロッパに示した。この成功は、イギリスとフランスがオスマン側に立って参戦することを決める心理的な地ならしとなった。", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["イスタンブルにおけるイギリス・フランスとの同盟条約", "04809278"], "d": ["クリミア戦争でロシアに対してオスマン帝国とイギリス、フランスの間で署名された同盟条約は、三国の共同作戦と、同盟国が戦争の終結前に単独で和平を結ばないことを規定した。こうしてオスマン帝国は歴史上初めて、ヨーロッパの大国と対等な当事者として軍事同盟に入った。この条約は、2年後のパリでのオスマン帝国のヨーロッパ国家体系への正式な受け入れの法的基盤ともなった。", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["イスタンブル市政庁(Şehremaneti)の設立:最初の近代的な自治体組織", "be4af27f"], "d": ["クリミア戦争中にイスタンブルに集まった同盟軍の兵士と増加した人口が生んだインフラの危機は、カーディー(裁判官)を中心とする古典的な都市行政の不十分さを明らかにした。ヨーロッパの例にならって設けられたŞehremanetiによって、清掃、公定価格、市場の監督、建設の事務が一つにまとめられた。翌年にはベイオール・ガラタに、第六区自治体(Altıncı Daire-i Belediye)が試験区として組織された。この一歩はオスマンにおける近代的な自治体行政の始まりとされる。", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["パリ条約:クリミア戦争の終結とオスマン帝国のヨーロッパ国家体系への受け入れ", "4aee0e2a"], "d": ["クリミア戦争を終えたパリ条約により、オスマン帝国はヨーロッパ国際法の対等な構成員と宣言され、その領土保全は列強の共同の保障のもとに置かれた。黒海は中立化され、ロシアがキュチュク・カイナルジャ以来得ていた正教徒臣民に対する保護の主張は無効とされ、ベッサラビア南部(Kili、Kahul、İsmail、Bolgradの各郡)がモルダヴィアに与えられた。しかし同じ条約は改革勅令を国際的な約束としたことで、内政への干渉の扉を開くことにもなった。", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["ドルマバフチェ宮殿の開館:政庁のトプカプからの移転", "71ad26d0"], "d": ["アブデュルメジト1世が1842年にバリヤン家に発注した宮殿は、14年の工事の後に開館し、国家の政庁は4世紀にわたるトプカプからボスポラス海峡沿いに移った。ヨーロッパ風の様式、クリスタルの階段、式典の間(ムアイェデ・サロヌ)を備えた宮殿は、タンジマートの西欧化の意志を石で表現したものとなった。その莫大な費用は、オスマン財政が外債の悪循環に陥った年月の中で、最も批判された項目の一つとなった。", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["ワラキアとモルダヴィアのクザ統治下での統合:ルーマニアの誕生", "baef4da5"], "d": ["パリ条約の後に行われた選挙で、両公国ともアレクサンドル・ヨアン・クザ大佐を公に選び、事実上の統合を実現した。オスマン政府とオーストリアはこれに反対したが、フランスが支持した既成事実として受け入れざるを得なかった。紙の上ではオスマン帝国に従属したままであったこの連合は、1862年にルーマニアの名を取り、1877年に一方的に独立を宣言することになる。ドナウ沿いのオスマンの支配が解けていく過程の転換点である。", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Kuleli事件:イスタンブルにおけるアブデュルメジトに対する最初のクーデター未遂", "e3653b21"], "d": ["タンジマート政策と、改革勅令が非ムスリムに認めた平等に反発した軍人・民間人混成の秘密結社は、スルタンの廃位を企てている最中、Kılıç Ali Paşa モスクでの会合の場で摘発された。被告がKuleli兵営で裁かれたため、事件はこの名で呼ばれる。死刑判決は流刑に減刑された。オスマン史上、イデオロギー上の理由で作られた組織が試みた最初の宮廷クーデター未遂とされる。", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["レバノン山のドルーズ・マロン派内戦とダマスカス事件", "5595fdd6"], "d": ["1860年5月にシドン近郊で二人のドルーズ派信徒が殺されたことで勃発した衝突は、山岳地帯で最も血なまぐさいドルーズ派とマロン派の内戦となり、7月にダマスカスに波及して数千人のキリスト教徒の死をもたらした。フランスの上陸を受けて、オスマン政府は特別な権限を与えたFuad Paşaを現地に派遣し、厳しい鎮圧が行われた。事件はヨーロッパの介入の口実となり、レバノンが特別な地位を得る直接の原因となった。", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Tercümân-ı Ahvâlの刊行開始:イスタンブル最初の民間トルコ語新聞", "24792957"], "d": ["Agâh Efendiが発行し、Şinâsiが編集を担ったTercümân-ı Ahvâlは、国家の支援を受けずに刊行された最初のトルコ語新聞である。創刊号の序文では民衆が自らのことについて発言する権利が擁護され、新聞はŞinâsiの『Şair Evlenmesi』を連載して、近代トルコ文学の扉も開いた。オスマンにおける世論という概念と、反対派の報道の誕生は、この日に求められる。", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["レバノン山規約:レバノンに特権的ムタサッルフ制の地位", "bf375603"], "d": ["1860年の虐殺の後に列強の圧力で作成された規約は、レバノン山をオスマン政府に直接従属し、宗派間の均衡に基づく行政評議会で統治される特権的なムタサッルフ(県知事)制の県とした。ムタサッルフはオスマン臣民のカトリックのキリスト教徒であること、その任命は列強の承認に付されることが条件とされ、最初のムタサッルフはDâvud Paşaとなった。この体制は1915年まで続き、近代レバノン国家の核となった。", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["アブデュルメジトの死とスルタン・アブデュルアズィーズの即位", "27204d7c"], "d": ["22年の治世でタンジマート勅令と改革勅令に署名したアブデュルメジトが結核で亡くなったため、弟のアブデュルアズィーズが即位した。新しいスルタンは、最初の数年は倹約策と簡素な暮らしで期待を抱かせ、海軍を世界有数の強国の一つにした。しかし治世の終わりには、重い外債、1875年の破産、バルカンの反乱が積み重なって、1876年の廃位の素地を整えることになる。", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["統合公国のルーマニアの名の採用", "d960e3fc"], "d": ["1859年にクザが二重に選ばれたことで事実上統合していたワラキアとモルダヴィアは、1862年に議会と政府をブカレストで一つの屋根の下にまとめ、正式にルーマニアの名を取った。オスマン帝国は法的には宗主の地位と年貢を保ったものの、公国に対する統制は事実上失った。ドナウ以北の4世紀に及んだオスマンの影響力の終わりは、この日付で象徴される。", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["スアキン、マッサワ、ダフラクのエジプトへの帰属", "a0924860"], "d": ["1846年にスルタン・アブデュルメジトによってエジプトのヘディーヴ(副王)ムハンマド・アリー・パシャにスアキンとともにサーリヤーネ(年額の収入割当)として与えられていたマッサワは、ヘディーヴ・イスマーイール・パシャの時代にダフラク、スアキンとともにエジプトの領地に編入され、カイマカム(郡長)の地位で組織された。こうして紅海のアフリカ側の海岸にあるこの三つの港は、法的にはオスマン領のままでありながら、行政上はオスマン政府から直接カイロに移った。近隣のエジプトとスーダンと同じ従属の層に入ったのである。", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["クレタ蜂起の開始(1866年から1869年)", "3679b861"], "d": ["ギリシアの公然の支援を受けて島で勃発した大規模な蜂起は、クレタのギリシア人のエノシス(ギリシアへの併合)の要求を初めて国際問題とした。3年続いた過酷な山岳戦はオスマン軍に大きな損害を与え、ヨーロッパの世論に大きな反響を呼んだ。蜂起は1868年に、Âlî Paşaが島に赴いて広範な特権を認める規約を施行することで、ようやく収まった。", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["ベオグラードとセルビアの要塞からの最後のオスマン守備隊の撤退", "b34217db"], "d": ["列強の圧力とミハイロ公の粘り強い要求を受けて、オスマン政府はセルビアに残る最後の軍事拠点を空けることに同意した。1867年4月18日にベオグラード要塞のオスマンの旗が降ろされ、鍵が公に引き渡された。こうして1521年から続いたオスマンの事実上の軍事的存在は終わり、セルビアの独立への道の最後の大きな障害が取り除かれた。スルタンの宗主権は、象徴的な旗と年貢の問題だけに切り縮められた。", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["エジプト総督へのヘディーヴの称号の授与", "09e10c12"], "d": ["カヴァラ出身の王朝の第3世代であるイスマーイール・パシャの活発なロビー活動とイスタンブルに注ぎ込んだ金の結果、エジプト総督には、他の総督より上位であることを強調するヘディーヴ(副王)の称号が与えられた。同じころ継承の方式も父から子へ移るように改められ、エジプトには外債の起債、勲章の授与、領事の駐在といった、主権の性格を持つ権限が認められた。これらの措置は、エジプトのオスマンからの法的離脱を早めた連鎖の最初の環である。", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["クレタ規約:島への広範な行政上の特権", "12052262"], "d": ["3年に及ぶ蜂起を終わらせるため、大宰相Âlî Paşa自らが島に渡り、スルタンの承認を得て公布された規約により、クレタの人々に混成の行政評議会、地方裁判所、公的手続でのギリシア語の使用、税の軽減が認められた。この措置は島におけるオスマンの支配をさらに30年保った。しかしキリスト教徒の住民に与えられた特権はムスリムのクレタ人の立場を弱め、1896年から1898年の危機の種をまいた。", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Şûrâ-yı Devlet(国家評議会)の開設:オスマンの国務院の設立", "70b16497"], "d": ["1868年3月5日付の勅令でMeclis-i Ahkâm-ı Adliyyeが二つに分けられ、行政・立法の事務がŞûrâ-yı Devletに、司法の事務がDîvân-ı Ahkâm-ı Adliyyeに委ねられた。機関はオスマン政府で式典とともに開かれ、初代議長にはミドハト・パシャが就いた。法案の準備、行政上の紛争の解決、官吏の審理の遂行が任務とされた。ムスリムと非ムスリムが混在する構成を持ち、オスマンにおける権力分立の考えの最初の制度的な実践とされる。", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["スエズ運河の開通:エジプトを経由するインド航路の短縮", "377ccd04"], "d": ["1859年に始まった工事は10年続き、地中海と紅海を結ぶ全長163キロメートルの運河が壮麗な式典とともに供用された。ヨーロッパとインドを結ぶ航路が数千マイル短くなったことで、エジプトは一躍世界貿易の要衝となった。この地政学的な価値は、運河開通の13年後にイギリスがエジプトを占領する主な理由となり、運河がエジプトに負わせた債務はヘディーヴ制を破産に追い込むことになる。", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["ブルガリア総主教座(エクザルフ)の設立:ブルガリア教会のファナルからの分離", "33a8272c"], "d": ["スルタンの勅令により、ギリシア正教の総主教座とは別に独立したブルガリア教会(エクザルフ制)が設けられ、どの郡をエクザルフに属させるかは住民投票に委ねられた。オスマン政府はこの措置をギリシア人の影響力を削ぐために講じたが、結果は逆に働いた。教会はブルガリアの民族的アイデンティティと、マケドニアに対するブルガリアの主張の組織的な中心となった。バルカンにおけるブルガリア・ギリシア・セルビアの対立と、1876年の蜂起の制度的な基盤がこうして築かれた。", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["アシールの直接統治への編入", "4559e099"], "d": ["スエズ運河の開通で紅海の戦略的価値が高まると、イエメンに行く陸路の中央にあるアシールの山地を無統制のまま置くことはできないと判断された。イエメン遠征に出たRedif Paşaの部隊はアブハーに入って地域を直接オスマンの統治に結びつけ、アシール・サンジャクが設けられた。山がちの地形とイドリース家の影響力のため、この支配は決して完全には定着しなかった。", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["ミドハト・パシャのナジュド遠征:ハサーにおけるオスマンの支配の再建", "7db51461"], "d": ["バグダード総督ミドハト・パシャは、サウード家内部の王位争いを利用してペルシア湾西岸に兵を送り、ハサー地方をナジュド・サンジャクの名でバスラ州に編入した。Abdullah b. Faysalがムタサッルフに任命され、オスマンの支配は紙の上で確立された。遠征はペルシア湾でイギリスの影響力が広がるのを食い止める目的を持ち、同年のカタールもオスマンの統制下に入ることにつながった。", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["大宰相Âlî Paşaの死:タンジマート世代の終わり", "1cf0141c"], "d": ["1869年のFuad Paşaの死の後、ひとりでタンジマート政策を担ってきたÂlî Paşaが亡くなったことで、国家の外交を30年にわたって率いた熟達の外交官の世代は尽きた。後任のMahmud Nedim Paşaの親ロシア的で恣意的な統治は、アブデュルアズィーズの個人支配を強めた。Âlî Paşaの死後5年のうちに、財政は破産し、バルカンは蜂起し、スルタンの交代は避けられなくなった。", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["カタールにおけるオスマンの統制の確立", "3b453165"], "d": ["イギリスの圧力を受けていたシェイフKāsım b. Sânîの招きに応じて、オスマン軍はカタール半島に上陸し、1871年の秋に地域でオスマンの統制が確保された。カタールはナジュド・サンジャクに属する郡(カザー)として組織され、シェイフはカイマカムに任命された。この動きは、ミドハト・パシャがペルシア湾でイギリスに対して進めた前進政策の最も具体的な成果となった。オスマンの旗は半島で1913年まではためいた。", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["チュニスへの世襲勅令 — 侯位がMehmed Sâdık Paşaの家系に", "1509ebb0"], "d": ["フランスのプロイセンに対する敗北を好機とみたチュニスのベイMehmed Sâdık Paşaがイスタンブルに送ったハイルッディン・パシャの働きかけで出された勅令により、チュニスは、直接イスタンブルに従属したまま、Mehmed Sâdık Paşaとその子孫に世襲の方式で与えられた。スルタンの許可なしに戦争や和平の交渉は行わず、国からいかなる土地も他者に与えず、オスマンの兵の要求には応じるものとされた。フランスは勅令を承認せず、10年後にチュニスを占領した。", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["サナアの占領:イエメンにおけるオスマンの権威の再建", "978e20a0"], "d": ["スエズ運河の開通で紅海の戦略的な価値が高まったため、オスマン政府はAhmed Muhtar Paşaの指揮する予備師団の軍をイエメンに送った。サナアの占領により、2世紀にわたって事実上失われていた内陸イエメンで国家の権威が再建され、地域は県(ヴィラーイェト)とされた。しかしザイド派のイマームたちとの闘争は終わらなかった。1891年、1898年、1904年の蜂起は、オスマンにとって最も費用がかさみ最も長く続く国内戦線となった。同日に編入されたその他の地は、サナア、ターイズである。", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["ヘルツェゴヴィナ蜂起の開始:東方問題の再燃", "571b18ec"], "d": ["重い税と地方名士(アーヤーン)の圧迫のために、Nevesinje周辺のキリスト教徒の農民が起こした蜂起はまもなくヘルツェゴヴィナ全域に広がり、セルビアとモンテネグロから来た義勇兵によって養われた。オーストリアとロシアによる改革の押しつけを招いた蜂起は、翌年のブルガリアの蜂起とセルビア・モンテネグロの宣戦を引き起こした。こうして、1877年から78年の露土戦争(93年戦争)と、ベルリン条約でのバルカンの喪失に至る大きな連鎖の最初の環が壊れた。", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["オスマン財政の破産:外債の支払いの半減", "2cac2fa5"], "d": ["1854年から重ねられた借款、クリミア戦争の費用、宮殿の建設、1873年から74年のアナトリアの飢饉によって、予算の赤字は500万リラを超える深淵となった。Mahmud Nedim Paşa政府は、債務の利子と元本の支払いを5年間半分にすると宣言し、事実上のモラトリアムを宣言した。ヨーロッパの株式市場で大きな反発を呼んだこの決定は、6年後のMuharrem布告とDüyûn-ı Umûmiyye(オスマン債務管理局)の設立に至る過程を始動させた。", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["ムラト5世の廃位とアブデュルハミト2世の即位", "cffb2271"], "d": ["アブデュルアズィーズの廃位の後に即位したムラト5世は、叔父の死とÇerkes Hasan事件に揺さぶられた精神状態のため職務を果たせなくなった。93日の治世のうち、判断力が確かだったのはわずか7日であった。シェイヒュルイスラームのファトワーにより廃位され、弟のアブデュルハミト2世が代わりに就いた。新しいスルタンは、ミドハト・パシャに立憲制を宣言すると約束して即位した。33年続く時代が始まろうとしていた。", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["造船所会議(イスタンブル会議):列強によるバルカン改革の押しつけ", "b5006a2c"], "d": ["バルカン危機を解決するために列強がイスタンブルで開いた会議は、ブルガリアを二つの自治県に分けること、およびボスニア・ヘルツェゴヴィナに国際的な監督付きの改革を施すことを求めた。オスマン政府は、会議が開かれた日に礼砲でカーヌーン・エ・エサースィー(憲法)の宣言を告げ、押しつけを立憲的改革で迎え撃とうとした。代表たちはこれを引き延ばしとみなして1877年1月20日に解散し、4か月後にロシアが宣戦した。", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["最初のメクリス・イ・メブウサーン(議会)のドルマバフチェにおける開会", "429bb279"], "d": ["カーヌーン・エ・エサースィーに従って選ばれた115人の議員は、1877年3月19日にドルマバフチェ宮殿の式典の間で行われた式典で初めて集まり、こうしてオスマン史に代議制の議会の時代が始まった。ムスリムと非ムスリムの議員は政府を厳しく問いただし、戦争の運営と大臣の責任を議論した。この大胆な反対は、議会の寿命を縮める主な原因となる。", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["プレヴェン防衛の開始:Gazi Osman Paşaの抵抗", "0e04a878"], "d": ["93年戦争(1877年から78年の露土戦争)でドナウを渡ったロシア軍がイスタンブルへの道を断つのを阻むため、ヴィディンからプレヴェンへ進軍したOsman Paşaは、町を堡塁と塹壕で要塞化し、5か月に及ぶ伝説的な防衛を始めた。三度にわたるロシア・ルーマニア軍の大攻勢は大きな損害を出して退けられ、皇帝アレクサンドル2世自らが指揮する軍は包囲に切り替えざるを得なかった。プレヴェンは、19世紀におけるオスマン軍の最も輝かしい防衛の成功として歴史に残った。", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["プレヴェンの陥落:ドナウ戦線の崩壊", "185e7602"], "d": ["5か月の包囲で糧食が尽きたOsman Paşaは、ヴィト川方面へ突破作戦に出たが、負傷して捕虜となり、都市は降伏した。ロシアの指揮官たちは、捕らえたパシャに剣を返して敬意を表し、Osman Paşaには「ガーズィー」の称号が与えられた。プレヴェンの陥落でロシア軍の前途は開け、2か月のうちにソフィア、プロヴディフ、エディルネが陥落し、ロシアの先鋒はイェシルキョイに達した。", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["ロシア軍によるソフィアの占領", "ef369d22"], "d": ["プレヴェンの陥落の後にバルカンを越えたロシア軍は、無防備となったソフィアに入った。都市は二度とオスマンの統治に戻らず、1878年末に自治的なブルガリア公国の、1879年に事実上の首都となる。地図上のソフィアは、この日付からオスマンの直接統治を離れて一時的なロシアの占領に、続いて自治的なブルガリアの統治に移る。", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["エディルネ休戦協定:93年戦争での停戦", "1f899180"], "d": ["ソフィア、プロヴディフ、エディルネが相次いで陥落し、ロシア軍がマルマラ海岸に迫ったため、オスマン政府は休戦を求めざるを得なかった。エディルネで署名された停戦は、ブルガリアの自治、モンテネグロ・セルビア・ルーマニアの独立、重い戦争賠償といった予備講和の条件をオスマン帝国に受け入れさせた。これらの条件は1か月後にサン・ステファノで条約文書となる。", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["アブデュルハミト2世によるメクリス・イ・メブウサーン(議会)の無期限休会", "e770b540"], "d": ["戦争が破局に終わったことの責任を政府と宮廷に問う議員たちの厳しい批判を受けて、アブデュルハミト2世はカーヌーン・エ・エサースィーが自らに認めた権限に基づいて議会を無期限に休会とした。約11か月働いた最初のオスマン議会はこうして閉じられ、30年続く専制(イスティブダード)の時代が始まった。議会は1908年の革命の後にようやく再び集まることができた。", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["サン・ステファノ条約:大ブルガリア構想", "2c7cc611"], "d": ["93年戦争を終えたサン・ステファノ条約は、エーゲ海まで延びマケドニアを含む巨大な自治ブルガリアを作り、セルビア、モンテネグロ、ルーマニアの独立を承認し、カルス、アルダハン、バトゥム、ドゥバヤジトをロシアに譲り、さらに支払いが不可能な戦争賠償を課した。ロシアを地中海に下ろすこの文書は、イギリスとオーストリアの激しい反発を招いた。実施されないまま4か月のうちにベルリン会議で再編されたが、それでもオスマンのルメリアの終わりを告げる文書として残った。", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["カルス、アルダハン、バトゥムがロシアに譲られた — 三郡", "99bdfad2"], "d": ["ベルリン条約により、オスマン帝国はカルス、アルダハン、バトゥムを戦争賠償の一部の代わりにロシアに譲った。サン・ステファノでロシアに与えられたドゥバヤジトとエレシュキルトの谷はオスマンに残った。バトゥムは自由港として与えられたが、この地位を1886年までしか保てなかった。ロシア人はカルスを、中心がトビリシにあるザカフカース総督府に属する県とした。三郡から10万人に達する住民がエルズルムの方面に移住せざるを得なかった。同じ条約で南ベッサラビア(Kili、Kahul、Bolgrad)がルーマニアからロシアに返還された。", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["ボスニア・ヘルツェゴヴィナとノヴィ・パザルのオーストリア・ハンガリーによる占領", "e5f901df"], "d": ["ベルリン条約が与えた権限に基づいてオーストリア・ハンガリー軍がボスニアに入った。オスマン政府が抵抗しないことを受け入れていたにもかかわらず、サラエヴォとモスタルでは現地のムスリムと正教徒の住民が武器を取り、3か月にわたって激しい抵抗を示した。占領は1878年10月20日にようやく完了した。スルタンの法的な主権は1908年まで紙の上で続いたが、4世紀に及んだオスマンのボスニアは事実上失われ、ムスリムの大規模な移住の波が始まった。同じ日に失われた他の定住地は、バニャ・ルカである。", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Muharrem布告とDüyûn-ı Umûmiyye(オスマン債務管理局)の設立", "02b7cc03"], "d": ["1875年の破産の後、債権国の代表との間で進められた交渉は、ヒジュラ暦1299年ムハッラム月28日(1881年12月20日)付の布告に結実した。債務の元本は半分以上削減され、その代わりに塩、タバコ、絹、印紙、魚の税といった最も収益の高い収入項目が、債権者が直接管理するDüyûn-ı Umûmiyyeに移された。数千人の官吏を雇ったこの管理局は、国家の中の別個の財務組織となった。オスマンの財政的独立が事実上終わった日とみなされる。", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["スアキン — マフディーの手に落ちなかった唯一の港", "5a37b198"], "d": ["1884年2月以降、スアキンを除く東スーダンのすべての地域がムハンマド・アフマド・アルマフディーの支配に移るなか、この港はグレアム将軍率いる3個大隊のイギリス軍による軍事的保護によって持ちこたえた。これは事実上と法的な状態が分かれる時代の始まりであった。海岸は事実上イギリスの軍事統制下にあったが、その行政上の結びつきは1885年にエジプトから外されて直接イエメン県、すなわちオスマン政府に結びつけられることになり、この体制は1888年にフランスがゼイラを占領して終わるまで続いた。", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["ミドハト・パシャのターイフの牢獄での殺害", "f4562261"], "d": ["カーヌーン・エ・エサースィーの設計者で、第一次立憲制の象徴的な名であったミドハト・パシャは、アブデュルアズィーズの死に関するYıldız法廷で有罪とされ、死刑判決が流刑に減刑されてターイフに送られていた。TDVの記録によれば、1884年5月7日から8日にかけての夜に独房で絞殺され、公式の理由は「şîrpençe」という病気とされた。彼の死は、アブデュルハミト2世の時代における立憲的反対派の一掃の象徴となった。", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["ハイダルパシャ・アンカラ鉄道の利権のドイツ人への付与", "5705b163"], "d": ["スルタンの勅令により、ハイダルパシャ・アンカラ線の建設と運営の利権が、ドイツ銀行を代表する銀行家アルフレート・フォン・カウラに与えられ、アナトリア鉄道会社が設立された。この利権は、オスマンの交通と外交において英仏の独占を破り、ドイツの影響力を定着させる転換点となった。11年後に同じ会社に与えられるバグダード鉄道の利権とともに「ベルリン・バグダード」の構想が生まれ、これは第一次世界大戦前の大国間の対立の主軸の一つとなった。", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["İttihâd-ı Osmânî Cemiyeti(オスマン統一協会)のイスタンブルにおける設立", "b7187939"], "d": ["陸軍医学校の4人の学生が、専制の統治に対する秘密組織としてİttihâd-ı Osmânî Cemiyetiを設立した。この組織はまもなく、青年トルコ運動のすべての反対派の要素を傘下に収める統一進歩協会(İttihat ve Terakkî Cemiyeti)へと変わった。細胞(ヒュクレ)方式による組織は、ヨーロッパにいる亡命者とテッサロニキの将校たちと結びついた。1908年に第二次立憲制を宣言させ、1913年以後は国家を単独で統治する幹部たちが、この小さな学生の細胞から出た。", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["オスマン銀行襲撃:ダシュナク活動家によるガラタでの行動", "08b3095f"], "d": ["アルメニアのダシュナクツチュン組織の武装グループは、ヨーロッパの関心をアルメニア問題に引きつけるため、ガラタのオスマン銀行本店を襲って人質を取り、建物を爆破すると脅した。危機は、大使たちが介入して、活動家を船で国外に出すことと引き換えに終わった。襲撃に続く日々にイスタンブルで起きた血なまぐさい事件は、アルメニア問題が国際的な介入の梃子となる上で決定的であった。", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["1897年のオスマン・ギリシア戦争の開始:テッサリア戦線", "33e490ab"], "d": ["ギリシアがクレタに艦隊と兵を上陸させたことと、ルメリア国境での武装集団の攻撃を受けて、オスマン帝国は宣戦した。ドイツの改革使節団が訓練したオスマン軍はテッサリアで急速に進み、1か月のうちにYenişehir、Çatalca、Dömekeを占領して、ギリシア軍は潰走した。列強の介入によって獲得した領土は返還されたが、この戦争はアブデュルハミト2世の時代における唯一の決定的な軍事的勝利として残り、クレタの事実上の喪失を防げなかった。", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["コンヤ・バグダード線の利権のドイツ人への付与", "fd8b6cbd"], "d": ["皇帝ヴィルヘルム2世の1898年のイスタンブルとダマスカスの訪問の後に、アナトリア鉄道会社にコンヤからバグダードとバスラへ延びる線の予備的な利権が与えられた。バグダード鉄道計画は、オスマンにとってはアラブ諸州に対する中央の統制を強めること、ドイツにとってはペルシア湾に到達することを意味した。イギリスとロシアが激しく反対したこの計画は、第一次世界大戦へ向かう帝国主義的対立の中でも最も論争を呼んだ案件の一つとなった。", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["ヒジャーズ鉄道の建設のダマスカスにおける開始", "62f58f68"], "d": ["アブデュルハミト2世の1900年5月2日付の勅令で命じられた路線は、1900年9月1日にダマスカスで行われた正式な式典で建設が始まった。もっぱらイスラーム世界から集められた寄付と、オスマンの技師・軍人の労働で行われたこの計画は、巡礼者のダマスカス・メディナ間の旅を40日から5日に短縮した。カリフ位の精神的な権威を強める威信の事業であると同時に、ヒジャーズに対する軍事的な統制を強める戦略的な投資でもあった。", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["ミュルツシュテーク綱領:マケドニアにおける国際的な改革の監督", "4c7464da"], "d": ["イリンデン蜂起の後、ロシアとオーストリアの皇帝はミュルツシュテークで会い、マケドニアのための新たな改革案を準備した。綱領は、オスマンの総監察官の傍らに二人の外国人文民代理人を置くこと、憲兵隊をヨーロッパの将校によって再編すること、行政区画の境界を民族に基づいて変更することを定めていた。オスマン政府は主権の侵害を理由に抵抗したが、共同の圧力の前に受け入れざるを得なかった。綱領は、若い将校たちの間で統一進歩派の組織化を早めた基本的な要因の一つとなった。", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["ムラト5世の死去", "396659a7"], "d": ["1876年に3か月ほど在位して廃位されたムラト5世は、彼を王位に戻そうとする企ての後、厳重な監視下で28年を幽閉されて過ごし、糖尿病で亡くなった。イェニ・ジャーミーのCedîd Havâtîn廟の母の傍らに葬られた。在位が最も短かったオスマンのスルタンとして歴史に残った。", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["サナアのイマーム・ヤフヤーへの喪失", "e7f876cb"], "d": ["ザイド派のイマーム・ヤフヤー・ハミードゥッディーンが1904年に始めた蜂起は、1905年4月にサナアが包囲の末に陥落することで頂点に達した。都市はオスマンの統治を離れ、包囲の間に飢餓と疫病が現れた。イエメンの山がちな地形、補給線の長さ、ザイド派イマーム制の現地での正統性は、ここでのオスマンの支配を成立当初から脆いものにしていた。都市は5か月後に大きな損害を出して取り戻されたが、イエメン問題は1918年まで終わらなかった。", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Yıldız暗殺未遂:アブデュルハミト2世への爆弾攻撃", "1ee2e1a6"], "d": ["ダシュナクツチュン組織は、金曜礼拝から出てきたスルタンの馬車の近くで、時限爆弾を積んだ馬車を爆発させて暗殺を企てた。アブデュルハミトがシェイヒュルイスラームと話して数分遅れたことが、彼の命を救った。爆発で26人が死に、50人以上が負傷した。この事件はスルタンの安全への固執と、密偵組織に基づく専制の統治をさらに厳しくした。Tevfik Fikretの詩『Bir Lahza-i Taahhur』の題材にもなった。", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["サナアの奪還:イマーム・ヤフヤーの蜂起の鎮圧", "dec3b8f9"], "d": ["1904年にザイド派のイマーム・ヤフヤーを指導者として始まった蜂起は、1905年4月のサナア陥落で頂点に達し、都市では飢餓と疫病が現れた。Ali Rızâ PaşaとAhmed Feyzi Paşa率いる増援軍は、1905年7月15日から9月1日まで行った、ターイズの部隊の支援も受けた作戦で、大きな損害を出しながら都市を取り戻し、蜂起は鎮圧された。イエメン作戦はオスマン軍に数万の損失と莫大な財政負担をもたらした。ルメリアの将校たちの間で「イエメンへの流刑」への恐れは、統一進歩派の組織化を養った不満の筆頭であった。", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["第二次立憲制の最初のメクリス・イ・メブウサーン(議会)の招集", "e7fd2716"], "d": ["30年の空白の後に二段階選挙で構成された議会は、1908年12月17日にスルタンの勅語とともに開かれ、議長には青年トルコ運動の指導者Ahmed Rızâ Beyが選ばれた。トルコ人、アラブ人、アルバニア人、ギリシア人、アルメニア人、ユダヤ人の議員からなる議会は、オスマン主義の理想の最後の大きな試みであった。しかしブルガリアの独立、ボスニアの併合、クレタのギリシア編入宣言が、議会が開かれる前から、この楽観を曇らせていた。", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["行動軍とアブデュルハミト2世の廃位:メフメト5世レシャトの即位", "6a65a704"], "d": ["3月31日事件を受けてテッサロニキから出た行動軍(ヒャレケト・オルドゥス)は、4月22日から23日にかけての夜に四方からイスタンブルに入り、24日にYıldız宮殿が降伏した。国民議会(Meclis-i Umûmî-i Millî)は27日にアブデュルハミト2世の廃位を決定し、スルタンはテッサロニキに送られ、弟のメフメト5世レシャトが即位させられた。33年に及んだ個人統治はこうして終わったが、その後には、スルタンが象徴となり、統一進歩党が軍の支持を得て統治する新たな時代が来た。", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["アルバニア蜂起:コソヴォとシュコドラにおける武装抵抗", "93ed30c6"], "d": ["統一進歩派政府の中央集権的な税政策、武器回収運動、ラテン文字をめぐる論争は、それまで国家に最も忠実とされていたアルバニアの部族を蜂起させた。Mahmud Şevket Paşa率いる軍が蜂起を厳しく鎮圧したが、不穏は1911年と1912年に再燃した。これらの蜂起はバルカン戦争の前夜にオスマン軍を消耗させたとともに、アルバニア民族運動の誕生も早めた。", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["ウシー条約:トリポリタニアとベンガジのイタリアへの割譲", "4ffa1fd2"], "d": ["バルカン諸国の戦争準備を前に二正面の戦いを覚悟できなかったオスマン政府は、スイスのウシー(Uşi)でイタリアと秘密の和平に署名し、トリポリタニアとベンガジを手放した。オスマン帝国はアフリカに残る最後の領土をこうして失った。その代わり、イタリアが占領したロドス島とドデカネス諸島の返還が約束されたが、この約束は果たされなかった。条約が署名されたとき、バルカン戦争はすでに始まっていた。この件により、Murzuk(Fizan)、Gât、Sebha、Ubârî、Tırgan(Traghan)、Zevîle(Zawila)、el-Katrûn(Fizan(トリポリ県のサンジャク))がイタリアの統治に移った。", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["レムノスのギリシアによる占領", "9555af1d"], "d": ["第一次バルカン戦争でギリシア艦隊はレムノスを占領した。島のムドロス港は、ダーダネルス海峡の封鎖のための基地となった。島はローザンヌ(1923年7月24日)でギリシアに残された。", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["タソスのギリシアによる占領", "6c03c7f0"], "d": ["第一次バルカン戦争でギリシアはタソスとサモトラケを占領した。", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["サモトラケのギリシアによる占領", "911e82a3"], "d": ["第一次バルカン戦争でギリシアはサモトラケを占領した。", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["レスボス(Midilli)のギリシアによる占領", "6b2b07ba"], "d": ["ギリシア艦隊はレスボスに上陸した。島は第一次バルカン戦争の終わりにギリシアの陸海軍によって占領された。ロンドン会議(1913年5月)が状況を追認した。", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["キオスへのギリシア軍の上陸", "901c6539"], "d": ["第一次バルカン戦争で1912年4月7日に砲撃されたキオスに、ギリシア軍が上陸した。オスマンの守備隊は1913年1月3日に降伏した。島はローザンヌ条約(1923年7月24日)でギリシアに残された。", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["大宰相Mahmud Şevket Paşaのイスタンブルにおける暗殺", "68e60e63"], "d": ["Bâb-ı Âli襲撃(オスマン政府襲撃)の後に大宰相に就いたMahmud Şevket Paşaは、陸軍省に向かう途中、Çarşıkapı付近で馬車に銃撃を受けて殺された。統一進歩党は暗殺を反対派のせいにして、広範な逮捕と処刑の波を始め、自由協商党は事実上一掃された。この事件とともに、エンヴェル、タラート、ジェマルの三人組に基づく一党独裁が決定的に確立された。", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["第二次バルカン戦争の開始:同盟国の分け前争い", "48d088a2"], "d": ["ロンドン条約でオスマン帝国から得た領土を分け合えなかったバルカン同盟国は互いに争い、ブルガリアがセルビアとギリシアの陣地を攻撃することで第二次戦争が始まった。ルーマニアとモンテネグロもブルガリアに対する戦線に加わると、ブルガリア軍は崩壊した。オスマン帝国はこの機会を利用して、ロンドン条約が引いたミディエ・エネズ線を越え、東トラキアをエディルネとともに取り戻した。", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["イスタンブル条約:ブルガリアとの和平とエディルネの確認", "c8c18b2d"], "d": ["第二次バルカン戦争の後にオスマン帝国とブルガリアの間で署名された条約は、マリツァ川を国境として、エディルネ、クルクラレリ、ディディモティホ、東トラキアがオスマンに残ることを法的に確認した。ドゥデアーチ(アレクサンドルーポリ)はブルガリアに残された(カヴァラは1912年秋のブルガリアによる占領の後、1913年7月にギリシアに移り、1913年8月10日のブカレスト条約でギリシア領と確認されていた)。両国間の相互の住民交換とブルガリアのムスリムの権利が規定された。バルカンの破局から取り戻せた唯一の土地の保証は、この文書である。同日に編入された他の地は、ギュムルジネ(コモティニ)である。", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["ボズジャアダとイムブロスの奪還 — アテネ条約", "ec084d09"], "d": ["バルカン戦争でギリシアが占領した北エーゲ海の島々のうち、海峡の口を押さえるボズジャアダ(テネドス)とイムブロス(Imroz)は、アテネ条約の交渉でダーダネルスの防衛に不可欠とされ、オスマンに返還された。他の島はギリシアに残った。この二つの島は、帝国がエーゲ海に保持した最後の土地となり、ローザンヌでもトルコに残された。", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["アテネ条約:ギリシアとの和平とテッサロニキ・ヨアニナの譲渡", "8e94def7"], "d": ["オスマン帝国とギリシアの間で署名された条約は、バルカン戦争で失ったテッサロニキ、ヨアニナ、南マケドニアのギリシアへの移行を正式に承認し、クレタに対するオスマンの権利を放棄した。ギリシアに残るムスリムの信仰と財産の権利、ワクフの地位、ムフティー(法官)の任命が詳細に規定された。エーゲ海の島々の地位は未解決のまま残され、両国間の継続的な緊張の源として残った。", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["イスタンブルにおけるオスマン・ドイツ秘密同盟条約の署名", "0472efb3"], "d": ["ヨーロッパで戦争が勃発するや否や、大宰相Said Halim Paşaの邸宅で、オスマン帝国とドイツの間で秘密の同盟条約が署名された。条文は、ロシアがドイツに対して参戦した場合にはオスマン帝国もドイツの側に立つことを定めていた。条約は内閣にさえ秘匿され、知っていたのはわずか4人であった。3か月後の黒海襲撃によってオスマン帝国は事実上戦争に引きずり込まれ、帝国の運命はこの文書によって結びつけられることになった。", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["カピチュレーション(通商特権)の一方的廃止", "ec773d18"], "d": ["オスマン政府は、ヨーロッパが戦争に忙殺されているときに、外国人に司法、財政、関税の特権を認めるカピチュレーションを、1914年10月1日から一方的に廃止すると宣言した。4世紀にわたるこの特権の体制の終了は、国内で大きな独立の高揚とともに迎えられ、イスタンブルでは祝賀が行われた。同盟国ドイツを含むすべての国が決定に抗議した。カピチュレーションは1923年のローザンヌでようやく決定的に歴史のものとなる。", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["黒海襲撃:オスマン艦隊によるロシアの港の砲撃", "8ad4ef61"], "d": ["ドイツから逃れ、「購入された」という形でオスマン艦隊に加わったゲーベンとブレスラウ(ヤヴズとミディッリ)は、スーション提督の指揮で黒海に出てロシアの港を砲撃し、船を沈めた。エンヴェル・パシャが内閣に秘密で与えたこの命令は、中立を事実上終わらせた。1週間のうちにロシア、イギリス、フランスが宣戦し、オスマン帝国は後戻りできない形で第一次世界大戦に入った。", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["イギリス・インド軍によるファーオの占領 — イラク戦線の開幕", "08663813"], "d": ["協商国がオスマン帝国に宣戦した日の翌朝、バーレーンで待機していたイギリス・インド軍の旅団が、シャットゥルアラブの河口にあるファーオに上陸した。荒れたファーオ要塞にいたオスマンの小部隊は軍艦の砲火のもとで退き、インド電信線の局はイギリスの手に渡った。イラク戦線はこうして開かれた。", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["大ジハード(Cihâd-ı Ekber)の宣言:ファーティフ・モスクでのジハードのファトワーの朗読", "2a6174e8"], "d": ["シェイヒュルイスラームÜrgüplü Hayri Efendiが出した五つのファトワーが、カリフであるスルタンの名でファーティフ・モスクで読まれ、すべてのムスリムが協商国に対するジハードに呼びかけられた。ドイツが大きな期待を寄せたこの一手は、イギリスとフランスの植民地のムスリムを蜂起させることを狙っていた。期待された全面蜂起は起こらなかった。それどころか、2年後にメッカの首長シャリーフ・フサインがイギリスの支援を受けて反乱を起こしたことは、カリフ位の政治的影響力の限界を痛烈に示した。", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["クルナのイギリスへの降伏", "621d36b0"], "d": ["バスラの陥落の後、ティグリス川とユーフラテス川が合流するクルナに退いたバスラ総督Subhi Beyの部隊は、12月4日から8日の戦闘の後、1914年12月9日の朝に降伏した。", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["エジプトのイギリス保護下への編入とスルタン国の宣言", "55d4e520"], "d": ["オスマン帝国の参戦を受けて、イギリスは1882年から事実上占領していたエジプトを正式に保護下に置くと宣言した。オスマンへの忠誠を保っていたヘディーヴ・アッバース・ヒルミー・パシャは廃位され、代わりにフサイン・カーミルが「スルタン」の称号で据えられた。こうして1517年から続いた法的なオスマンの宗主権は一方的に終了させられた。オスマン政府はこの決定を承認せず、2か月後のスエズ運河攻撃でエジプトを取り戻そうと試みた。", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["サルカムシュ作戦:コーカサス戦線での破局", "5cbde7f0"], "d": ["エンヴェル・パシャは、1878年に失ったカルス、アルダハン、バトゥムを取り戻し、コーカサスのトルコ系の人々を蜂起させる目的で、第3軍を冬にアッラーフ・アクバル山地を越えてロシア軍を包囲する機動に送り出した。不十分な冬の装備、尽きた補給、氷点下30度に達する吹雪のために、軍は戦闘に入る前から溶けるように消え、数万の兵が凍死した。この作戦はオスマンの戦争における最も重い破局の一つとなり、東部戦線を2年間無防備にした。", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["第一次運河作戦:シナイ砂漠を越えたスエズへの攻勢", "02dd72f5"], "d": ["第4軍司令官ジェマル・パシャは、エジプトをイギリスの占領から解放し、スエズ運河を航行に対して閉ざす目的で、シナイ砂漠を越える攻勢を行った。オスマン部隊は運河の東岸に達し、一部は対岸に渡ることに成功したが、イギリスの優勢と、期待されたエジプトの民衆蜂起が起きなかったことから後退した。作戦は目標に達しなかったが、イギリスにエジプトで大兵力を置くことを強いることで、間接的な戦略的効果を生んだ。", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["移送・定住法(Sevk ve İskân Kanunu、「テフジル」)の制定", "2f2bc22c"], "d": ["ヴァン蜂起とロシアの進撃の後、政府は、前線の後方で治安を乱すと判断された住民を軍司令官が他の地域に移送することを認める臨時法を制定し、スルタンは1915年5月27日に裁可した。実施の結果、アナトリアの東部と南部の県にいたアルメニア人住民の大部分がシリアとモスルの方向に移送された。移送の間に、病気、飢え、襲撃のために非常に多くの人命が失われた。この決定は、オスマン最末期の最も重く、今日でも最も論争の多い問題として残っている。", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["オスマン軍部隊がムシュをロシアの占領から取り戻した", "fb1be113"], "d": ["ムシュの最初のロシア占領から6か月後、オスマン第16軍団は、ビトリス・ムシュの反攻で町に入った。", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["ムシュが再びロシアの手に渡った", "43ad8a03"], "d": ["ロシアの反攻を受けて、オスマンの分遣隊はムシュを空けた。町は1916年8月22日から25日の間に再びロシアの占領に入り、1917年春まで手に残った。", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["ムシュがロシアの占領から最終的に解放された", "f0e89703"], "d": ["第一次世界大戦でロシアの占領下に入ったムシュは、1917年5月1日にオスマン軍によって最終的に取り戻された。", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["アブデュルハミト2世のベイレルベイ宮殿における死去", "c9662582"], "d": ["1909年に廃位されてまずテッサロニキに、バルカン戦争で都市が失われたためイスタンブルに連れてこられ、ベイレルベイ宮殿で軟禁されていたアブデュルハミト2世が亡くなった。33年の治世を通じて国家を戦争から遠ざけることで時間を稼ごうとしたが、専制の統治でも記憶されていた。遺体は大勢の群衆とともにディヴァンヨルのマフムト1世廟に埋葬された。彼の死は、自らが築いた体制がとうに一掃されていた戦争の年に重なった。", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["ブレスト・リトフスク条約:カルス、アルダハン、バトゥムの奪還", "da82636f"], "d": ["ボリシェヴィキ革命の後に戦争から離脱したロシアと同盟国の間で署名された条約は、東部戦線を閉じ、1878年のベルリン条約で失ったカルス、アルダハン、バトゥム(三郡 Elviye-i Selâse)をオスマン帝国に取り戻させた。これは、オスマン史上40年の空白を経て得られた唯一の領土的な獲得であった。しかしムドロス休戦協定の後に地域は再び失われ、最終的な解決は1921年のカルス条約でもたらされることになる。", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["オスマン軍部隊がアルトヴィンに入った", "ca7d1778"], "d": ["3月25日に1914年の国境を越えたオスマン軍部隊は、ブレスト・リトフスクが1878年以前の国境を返還した三郡に向けて進軍し、1918年3月28日にアルトヴィンに入った。アルトヴィンはバトゥム・サンジャクの一部として1878年にロシアに残されていた。TDVのアルトヴィンの項は復帰を「1918年3月」とのみ記し、日付はMustafa Sarıが与える。", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["アルダハンがトルコ軍の手に入った", "7fd9e3db"], "d": ["三郡作戦でオスマン軍はアルトヴィンの後に、1918年4月3日にアルダハンを占領した。アルダハンは93年戦争の1877年に陥落し、1878年にロシアに残されていた。カルスは1か月後の4月25日に占領されることになる。", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["バトゥムの奪還", "d37a1a0d"], "d": ["ブレスト・リトフスク条約でロシアが戦争から離脱したことを受けて東に進んだオスマン軍は、1878年に失ったバトゥム港を40年後に取り戻した。黒海の東端にあるこの港は、バクー石油の海への出口であった。獲得はわずか7か月しか続かず、ムドロス休戦協定の後、地域は空けられることになる。", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["三郡(Elviye-i Selâse):カルスがオスマンの統治に入った", "02cbf0b3"], "d": ["ブレスト・リトフスクで、1878年のベルリン条約で失った三つのサンジャク、すなわちカルス、アルダハン、バトゥムの返還が決められた。オスマン軍は4月3日にアルダハンに、4月14日にバトゥムに、1918年4月25日にカルスに入り、統治が事実上確立された。「三郡」の名で呼ばれるこれらの土地は、93年戦争以来続いていた喪失の埋め合わせとみなされた。休戦の後に再び失われ、最終的には1921年のカルス条約でようやくトルコに結びつけられることになる。", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["ウードゥルの占領 — アラス川流域での前進", "87ebf4d3"], "d": ["1918年2月に始まった前進作戦の枠内で、トルコ軍部隊はアラス川の北のSerderabadでアルメニア軍部隊を破り、1918年5月20日にウードゥルを占領した。ウードゥルは三郡には含まれず、エレヴァン県のSürmeli郡であった。約180年ぶりに地域で最初のオスマンの統治が確立された。", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["メフメト5世レシャトの死去とメフメト6世ヴァフデッティンの即位", "d302ba07"], "d": ["9年の治世をトリポリタニア戦争、バルカン戦争、世界大戦のうちに過ごしたメフメト5世レシャトは、戦争の最も重大な時期に亡くなり、弟のヴァフデッティンがメフメト6世の名で即位した。新しいスルタンは統一進歩派幹部の後見から逃れようと試みたが、4か月後に休戦協定が署名されると、帝国の整理を指揮せざるを得なくなる。オスマン朝の第36代、最後のスルタンであった。", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["協商国艦隊のイスタンブル沖への到来と都市の事実上の占領", "d10cb14d"], "d": ["ムドロス休戦協定の後、イギリス、フランス、イタリア、ギリシアの艦船からなる60隻を超える連合国艦隊がドルマバフチェの前に投錨し、イスタンブルは事実上占領下に入った。465年ぶりに首都が初めて外国の兵士の統制下に置かれたのである。同じ日にムスタファ・ケマル・パシャがハイダルパシャに降り立ち、光景を見て言ったと伝えられる「来たように去っていく」という言葉は、民族闘争の象徴的な言葉の一つとなる。", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["アラス地方での後退:ウードゥルの撤収", "57572ab4"], "d": ["ムドロス休戦協定の1914年の国境の内側への撤退の規定に従い、Yakup Şevki Paşaは11月21日の命令でブレスト・リトフスクの国境の外の部隊を12月4日までに引き揚げることを命じた。ウードゥルとその周辺はこの日に完全に空けられた。続いてアラス・トルコ政府は、1918年12月の終わりにアルメニア人によって倒された。", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["イギリス軍がアルトヴィンに定着した", "e2cb3153"], "d": ["1918年10月30日のムドロス休戦協定がオスマン軍の1914年の国境の内側への撤退を条件としたため、アルトヴィンは空けられ、1918年12月17日にイギリスによって占領された。TDVのアルトヴィンの項によれば、イギリスの占領は1920年4月まで続いた。", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["ムドロス後のバトゥムにおけるイギリスの統治", "9dd768fc"], "d": ["1918年10月30日のムドロス休戦協定により、オスマン帝国はバトゥムから撤退せざるを得なかった。都市は1918年12月24日にイギリス部隊によって保持された。1918年4月に独立したサンジャクの中心とされたバトゥムは、この日から1920年7月まで、イギリスの統制下に残った。", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["アルダハンがグルジアの支配に移った", "97cf47f6"], "d": ["ムドロスの後に空けられたアルダハンを、南西コーカサス政府がイギリスによって解散されたころ、グルジア軍が1919年4月20日に占領した。グルジアの支配は1921年2月23日まで続くことになる。", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["プレストンがカルスの統治をアルメニア人総督に引き渡した", "efa81cb0"], "d": ["1919年4月12日から13日に南西コーカサス政府を解散させたイギリスの指揮官プレストンは、臨時のシューラー(評議会)政府を1919年4月30日に廃止し、都市の統治をカルス総督とされたアルメニア人のKarganofに引き渡した。カルスでアルメニア統治の時代が始まり、Kâzım Karabekirの1920年10月30日の勝利まで続いた。", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["エルズルム会議:東部諸県の民族的抵抗の決定", "41ef0457"], "d": ["東アナトリア権利擁護協会が召集した会議は、イギリスの圧力による延期の後、56人の代議員で開かれ、議長には軍職を辞していたムスタファ・ケマル・パシャが選ばれた。会議は、民族的な国境の内で祖国は一体であること、委任統治と保護は受け入れられないこと、政府が瓦解した場合には国民が自らの運命を手にすることを宣言した。これらの決定は、6か月後に国民誓約(ミサク・ミッリー)の文書の核となる。", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["シヴァス会議:民族的抵抗の一つの屋根の下への統合", "0e9ad36b"], "d": ["1919年9月4日にシヴァス高等学校(Sivas Sultânîsi)で作業を始めた会議は、国の四方の権利擁護協会をアナトリア・ルメリア権利擁護協会の名のもとに統合し、代表委員会(Heyet-i Temsîliyye)を選んだ。アメリカの委任統治の提案は長い議論の末に退けられた。9月11日に公表された宣言によって、民族闘争は単一の中心を持つ正統な政治運動となり、イスタンブル政府との公然とした力の争いが始まった。", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["アマスヤ議定書:イスタンブル政府と代表委員会の会談", "40e6a6ab"], "d": ["ダマト・フェリトが倒れてAli Rızâ Paşa政府が成立した後、海軍大臣Salih Paşaが代表委員会と会談するためアマスヤに派遣された。合意された議定書によって、イスタンブル政府はアナトリアの運動の存在を事実上承認し、議会(メクリス・イ・メブウサーン)の招集、選挙の自由な実施、民族的な国境の保全が受け入れられた。これは、民族闘争がイスタンブルに対して得た最初の公式の政治的成果である。", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["国民誓約(ミサク・ミッリー)の最後のオスマン議会での採択", "6322865e"], "d": ["最後のオスマン議会で121人の議員が署名した国民誓約の文書は、ムドロス線の内側に残り、ムスリム・トルコ人の多数が住む土地の不可分の一体性、アラブ諸州と西トラキアでの住民投票、カピチュレーションの廃止、完全な政治的・財政的独立を条件としていた。文書は1920年2月17日に全会一致で採択され、世界に宣言された。この宣言は民族闘争の政治綱領であるとともに、ローザンヌで守られることになる国境の地図でもあった。協商国が3月16日にイスタンブルを正式に占領する直接の原因となった。", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["イギリスの撤退に際してアルトヴィンはグルジアに残された", "6d086b06"], "d": ["TDVのアルトヴィンの項によれば、イギリスの占領は1920年4月まで続いた。イギリスは撤退に際して都市をグルジアに残した。アルトヴィンは、グルジアの手に、TBMMの1921年2月23日の最後通牒まで残った。", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["バトゥムがグルジアの統治に引き渡された", "6523d095"], "d": ["イギリスによるバトゥムの正式なグルジアへの引き渡しは1920年7月7日に行われた(TDVのバトゥムの項は「1920年7月」とのみ記す)。アンカラ政府は7月25日に、この引き渡しを「占領」として抗議した。", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["ギュムリ条約:トルコ大国民議会(TBMM)政府の最初の国際条約", "9232c690"], "d": ["Kâzım Karabekir率いる東部戦線軍がサルカムシュとカルスを取り戻したことを受けて、アルメニアは和平を求め、ギュムリで署名された条約でセーヴル条約を承認しないこと、東部の領土要求を放棄することを受け入れた。アンカラ政府が署名したこの最初の条約は、セーヴル条約を事実上拒否した最初の国際文書となり、TBMMに法的承認への道を開いた。東部国境がこうして保障されたことで、西部戦線に兵力を移すことが可能となった。", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["第一次イノニュの戦い:正規軍の最初の勝利", "4add3719"], "d": ["新たに編成された正規軍は、ブルサの方面から進むギリシア軍をイノニュの陣地で阻み、後退を余儀なくさせた。軍事的には限られた規模のこの成功は、政治的な帰結においては非常に大きかった。アンカラ政府はロンドン会議に招かれ、ソヴィエト・ロシアとのモスクワ条約への道が開かれ、基本組織法(Teşkilât-ı Esâsiyye Kanunu)が採択された。国内の世論で正規軍に寄せられる信頼もこの勝利で固まった。", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["第二次イノニュの戦い:ギリシア軍の攻勢の二度目の挫折", "a974521c"], "d": ["ロンドン会議で成果を得られなかったギリシア軍は、ブルサとウシャクの方面から新たな攻勢に移ったが、再びイノニュの丘で止められ、後退せざるを得なかった。ムスタファ・ケマル・パシャがİsmet Paşaに宛てた、「あなたたちはそこで敵だけでなく、国民の悪運にも勝ったのだ」という電報は、この勝利の後に書かれた。戦いは民族闘争の国際的な威信を高め、イタリアのアナトリアからの撤退の過程を早めた。", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["アンカラ協定:フランスとの和平と南部戦線の終結", "35fc32db"], "d": ["サカリヤの勝利の後にフランスとアンカラで署名された協定によって、南部戦線の戦争は終わり、フランス軍はアダナ、アンテプ、マラシュ、ウルファを含むチュクロヴァと南東部を空けてシリア国境に退いた。協商国の一つがこうして事実上アンカラ政府を承認したことになり、セーヴル戦線に最初のひびが入った。空けられた地域から引き継がれた武器と、解放された部隊は、大攻勢(ビュユク・タアッルズ)の準備で決定的な役割を果たした。", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["ムダニア休戦協定:イスタンブルと海峡の無血での引き渡し", "ac0d9baf"], "d": ["大攻勢の後、トルコ軍がダーダネルスとイズミトでイギリス軍と対峙することになったため、ムダニアで開かれた会議は、11日間の厳しい交渉の末、休戦協定に至った。東トラキアをマリツァ川まで15日以内にギリシアが撤退してトルコの統治に引き渡すこと、イスタンブルと海峡も和平条約によって引き渡されることが受け入れられた。こうして民族闘争の武力の段階は、一発の銃弾も撃たれずに勝ち取った外交上の勝利で閉じられ、ローザンヌへの扉が開かれた。", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["メフメト6世ヴァフデッティンのイスタンブル出発とアブデュルメジト・エフェンディのカリフ選出", "8ab0e847"], "d": ["スルタン制の廃止の後に地位が議論の的となった最後のスルタン、メフメト6世ヴァフデッティンは、1922年11月17日金曜日の朝にイギリスの戦艦マラヤでイスタンブルを離れ、マルタに向かった。TBMMは2日後の11月19日に、政治的権限を持たないカリフとしてアブデュルメジト・エフェンディを選んだ。623年にわたるオスマン王朝の君主制はこうして事実上終わり、カリフ制はさらに15か月の間、象徴として続くことになる。マルタ、続いてイタリアに渡ったヴァフデッティンは、サンレモのヴィラ・ノーベルに居を定めた。イスラーム国への受け入れを求める請願は実を結ばず、1926年5月16日にそこで、スルタン位とカリフ位の権利を決して放棄していないと繰り返しつつ亡くなった。", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["最後のスルタンメフメト6世ヴァフデッティンのサンレモでの死去", "7149ed0e"], "d": ["イスタンブルを離れた後にイタリアのサンレモに居を定めた最後のオスマンのスルタン、メフメト・ヴァフデッティンは、スルタン位とカリフ位の権利を決して放棄していないと表明したカリフ制会議(1926年5月13日)が開かれたという知らせを受けないまま、1926年5月16日に亡くなった。彼は重い金銭的困窮にあり、サンレモの商人たちに6万リラの借金があった。死を知った債権者たちは、家の家財に差し押さえをかけさせた。", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["コヌラルプのボル地方の征服 — ムドゥルヌ、Konurapa、ボル", "e245cd27"], "d": ["オルハン・ガーズィーの指揮官コヌラルプは、サカリヤ川の東の山岳地帯に向かい、ムドゥルヌ、Konurapa、ボル一帯をオスマンの統治に結びつけた。デュズジェ平野の町は彼の名で呼ばれた。征服の正確な日付は分からず、叙述はアーシュクパシャザーデの伝承に基づく。地域は当時、ジャンダル侯国とビザンツの間で手が替わる辺境地であり、征服はオスマンを初めて黒海の西岸に近づけた。アンカラの戦いの後、一帯は再びジャンダル侯国に移るが、ファーティフの時代に最終的に取り戻されることになる。", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["マルマラ海の南のビザンツの町の占領 — ミハルチ、Kirmasti、ギョリャズ", "9c61b8d4"], "d": ["ニカイアとイズミットが取られた後、ブルサ平野の西でビザンツの手に残っていた町は一つずつオスマンの統治に入った。ウルアバト湖周辺のギョリャズ(Gölyazı)、ススルルク川沿いのKirmasti、ミハルチは、マルマラ海の南岸をカレスィ侯国の領土に結ぶ回廊を完成させた。これらの町は長い包囲を見ずに、周囲を断たれることで降伏した。地域におけるビザンツの存在はこうしてゲムリク湾に押し込められた。", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["ゴルドゥス(コリントス)がモレア専制公国に移った", "392495eb"], "d": ["1358年からフィレンツェ人アッチャイウォーリ家のアカイア公国に属する封土であったコリントスは、1395年にビザンツのモレア専制公テオドロスの手に渡った。都市はこれ以後、オスマンの征服まで専制公国の統治下に残った。", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["ハジュエミール侯国の併合 — オルドゥとウニエ", "c064f07f"], "d": ["Bayram Beyがオルドゥの周辺に築き、息子Hacı Emîrが1350年代に広げたテュルクメンの侯国は、中心が今日のEskipazarにある、小さいが戦略的な海岸国家であった。サムスンとトラブゾンの間における唯一の独立した支配領域であった。Emîr Süleymanは1398年にバヤジト1世のジャニク作戦で服従を表明していたが、アンカラの戦いの後、侯国は再び自由になっていた。ムラト2世の時代に、Tâceddinoğulları侯国の整理と同じころ、侯国の領土は直接オスマンの統治に結びつけられ、黒海沿岸はサムスンからギレスンまで一手に統合された。", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["ゴルドゥス(コリントス)の征服", "87a2bc59"], "d": ["ファーティフのモレア遠征で、アクロコリントス要塞は3か月包囲され、最終的に和平の形で引き渡された。モレアの門とされるコリントス地峡はこうしてオスマンに移った。", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["モンテネグロのオスマン統治への編入 — ツェティニェ", "7fdb7cc8"], "d": ["ゼタを治めたツルノイェヴィチ家が1496年に支配を手放すと、シュコドラの裏庭にあたるモンテネグロの山岳地帯は直接オスマンの統治に置かれ、まず独立したサンジャクとして、次いでシュコドラ・サンジャクの一部として組織された。ツェティニェ修道院は地域の宗教的な中心としてそのまま残された。地形の厳しさのため、ここでの統治は平野でのように厳密には働かなかった。2世紀後、同じ修道院から生まれたウラディカ(府主教=君侯)の統治が、事実上の独立の核となる。", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["ドゥバヤジト要塞の両イラク遠征におけるオスマン支配の受け入れ", "f29e2e17"], "d": ["大宰相イブラヒム・パシャが両イラク遠征でビンギョル周辺に来ると、地域の多くのクルド人部族とともに、ヴァン、トプラッカレ、Avnik、ドゥバヤジトの要塞がオスマンの支配に入ることに同意した。ドゥバヤジトは1514年のヤヴズの遠征でオスマンに加わっていたが、軍が帰ると、サファヴィー朝が地域を取り戻していた。", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["タブリーズの再びのサファヴィー朝への移行 — 両イラク遠征からの帰還", "80b8b761"], "d": ["両イラク遠征で軍はタブリーズに入ったが、本当の目標はバグダードであったため、都市に恒久的な守備隊は置かれなかった。冬をバグダードで過ごした軍が西に帰る際、シャー・タフマースブは空けられたアゼルバイジャンに再び入り、タブリーズを取り戻した。これはオスマン・サファヴィー戦争の繰り返される型であった。タブリーズは5度取られ、5度とも保持できなかった。都市が長期のオスマン守備隊を得るのは1585年のことになる。", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["ヴァンとエルチシュのタフマースブの手への陥落(オスマンの保持は1534年から35年で終わった)", "cb93d561"], "d": ["1534年にヴァンをオスマンの支配に与えた地域で、Ulama Paşaはヴァン要塞でサファヴィー朝の包囲に耐えていた。要塞はサファヴィー朝の手に渡り、エルチシュを包囲していたサファヴィー朝軍もオスマンの援軍により後退していた。カーヌーニーがアフラトに着いたとき(1535年9月23日)には、ヴァンはすでにタフマースブの手にあった。ヴァンは1548年までサファヴィー朝のまま残った。", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["ドゥバヤジト・サンジャクのサファヴィー朝の支配への移行(ヴァンとエルチシュは1535年にすでにサファヴィー朝のものだった)", "806a2cf1"], "d": ["オスマン・サファヴィー国境の中央にあるドゥバヤジト・サンジャクが再びイランの手に渡った(Kaya 2017はこれを「ヴァン、エルチシュとともに」と述べるが、ヴァンとエルチシュはKarataş 2025とTDVによれば1535年9月22日にサファヴィー朝に戻っていた — 前の項を参照)。この手替わりのなかでサンジャクのいくつかの場所は荒廃した。サンジャクは16世紀の最後の四半期まで二つの国の間で何度も手が替わった。", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["ドゥバヤジト・サンジャクのナヒチェヴァン遠征の際の再びのオスマンへの移行", "cf0171fa"], "d": ["カーヌーニーの第三次イラン(ナヒチェヴァン)遠征の際、ドゥバヤジト・サンジャクは再びオスマンの統治に置かれた。1554年の遠征ではドゥバヤジトは軍にとって重要な基地となった。サンジャクは1578年に最終的にオスマンの主権に入った。", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["エレヴァンのシャー・アッバースへの喪失", "34413cf2"], "d": ["ジェラーリーの反乱がアナトリアを麻痺させていた年月に、東部戦線が無防備のまま残されたため、軍をヨーロッパ式に再編していたシャー・アッバースは攻勢に出た。1583年にFerhad Paşaが築かせたエレヴァン要塞は、7か月の包囲の後に降伏した。Ferhad Paşa条約で得たコーカサス線の最初の環が切れ、その後の3年のうちに南コーカサス全体が失われることになる。", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["トビリシとギャンジャの喪失", "3fb51753"], "d": ["エレヴァンの陥落の後、サファヴィー朝軍はクル川流域に沿って進んだ。カラバフの中心ギャンジャとグルジアの首都トビリシは相次いで失われた。オスマン帝国は同時にオーストリア戦線で13年続く長い戦争を戦い、アナトリアでジェラーリーに手を焼いており、東に送れる兵力はなかった。こうして1590年のFerhad Paşa条約で築かれた広大なコーカサスの州の体制は、事実上終わった。", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["シルヴァンの喪失 — シェマハ、バクー、デルベント", "81beab11"], "d": ["カスピ海沿岸のシルヴァン州は、Özdemiroğlu Osman Paşaの1578年から1585年の遠征で得られ、絹交易の主な源として、オスマン財政に重要な収入をもたらしていた。北に向かったシャー・アッバースの作戦は、シェマハ、バクー、デルベントを続けざまに取ってこの州を清算した。喪失は土地だけではなかった。イラン絹がオスマンを経てヨーロッパに流れる道も統制から外れ、サファヴィー朝は絹をインド洋経由で売り始めた。", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["ターイズの喪失", "65f20d53"], "d": ["オスマンは1038年(1629年)に、サナアのカースィム朝の統治に委ねたイエメンの支配とともにターイズも放棄した。ザイド派のイマームたちが内陸イエメンを取り戻す過程の最初の大きな一歩であった。", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["イエメンの喪失 — カースィム朝のイマームたちの支配", "49e83e3c"], "d": ["イエメンは1538年からオスマンの州であったが、ザイド派のイマームたちの抵抗は決して途切れなかった。イマーム・カースィムが始めた蜂起は、息子のアル・ムアイヤド・ムハンマドの時代に国全体に広がり、オスマンの守備隊は順に包囲された。ムラト4世がバグダードとエレヴァンに集中していた年月に増援は送れなかった。ターイズは1629年に失われ、モカは同じ崩壊の最終局面である1635年10月22日に撤収されていた。1635年にサナアとザビードの最後の部隊もイエメンを撤収した。こうして紅海の東岸は237年間、帝国の外に置かれ、1872年にようやく取り戻された。ラヒジュ(al-Havta)は、TDV『イスラーム百科事典』によれば1635年までオスマンの手にあり、その日付からザイド派のイマームたちが影響力を持った。", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["モカの撤収", "c6b3061a"], "d": ["Mustafa Beyは、ヒジュラ暦1045年ジュマーダー・アル=ウーラー月10日(1635年10月22日)に、残った兵力と武器とともにモカを撤収した。続いてイマーム・カースィムの息子ハサン・ブン・カースィムは、ザビードとモカに自分の部下を任命して、ティハーマの海岸でもカースィム朝の統制を確立した。", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["ハサーのバヌー・ハーリド首長国への喪失", "a9b6131a"], "d": ["ハサーは、1550年にペルシア湾の西岸をポルトガルに対して閉ざすために設けられた州であったが、イスタンブルからは非常に遠く、一本の砂漠の道の先にあった。クレタの包囲が資源を使い果たしていた年月に、地域のバヌー・ハーリド部族は、Berrâk b. Gureyrを指導者としてオスマンの守備隊を追い出し、自らの首長国を築いた。湾の西岸は1世紀半にわたって部族の首長国のもとに残り、1795年にサウード家に、1871年に再びオスマンに移ることになる。", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["プレヴェザとヴォニツァのヴェネツィアへの喪失 — エピロス海岸の開放", "1201204c"], "d": ["神聖同盟に加わったヴェネツィアは、モレア遠征を始める前に、アンブラキア湾の口を押さえる二つの要塞を取った。プレヴェザと、対岸のヴォニツァである。同じ夏にAyamavra(レフカダ)も陥落していた。この三つの拠点は、艦隊がイオニア海からギリシア内陸に安全に入ることを可能にし、翌年に始まるモレア作戦の基地となった。プレヴェザとヴォニツァはパッサロヴィッツでもヴェネツィアに残された。オスマンの統治に戻るのは1798年のことになる。", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["ソルノクの喪失 — ティサ線の解体", "51c2c8ef"], "d": ["ノヴェー・ザームキ(Uyvar)が8月に陥落した後、ハプスブルク軍は南に向かい、ティサ川上の橋頭堡ソルノクを取った。都市はブダとトランシルヴァニアの間の唯一の安全な通路であり、その喪失はハンガリーの東半分のオスマンの要塞が互いに切り離されることを意味した。翌年のブダ包囲で補給路が断たれたことが決定的となった。", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["モドニのヴェネツィアへの喪失", "114c9cc0"], "d": ["モレア半島の南西端のモドニは、ヴェネツィアが3世紀前に失い、「国家の二つの目の一つ」と呼んだ港であった。コロニの陥落の後に包囲された要塞は、陸と海から同時に叩かれて降伏した。モロジーニのモレア作戦はこうして半島の西岸全体を占領し、内陸に開く道が開かれた。", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["ペーチ(Peçuy)の喪失", "99d54cf4"], "d": ["ブダが9月に陥落した後、ハプスブルク軍はドナウの西で南に下り、カーヌーニーの時代からオスマンの手にあったペーチを取った。Gazi Kâsım Paşaモスクで知られる都市は、ブダ州の最も発展したサンジャクの中心の一つであった。その喪失は、モハーチ平野に下る道が開かれることを意味した。翌年の第二モハーチの敗北はまさにここで起こることになる。", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["セゲドの喪失", "9fbee1b2"], "d": ["ティサ川とマロシュ川の合流点にあるセゲドは、ハンガリー平野の南の門であり、ティミショアラ州に至る道を押さえていた。ブダとペーチが同じ秋に陥落した後、包囲された要塞はまもなく降伏した。三つの要塞が一季節のうちに失われたことは、1541年から築かれてきたハンガリーにおけるオスマンの行政構造が崩れ始めた徴候であった。本アトラスは同日にティサ沿いのゼンタもオスマンからハプスブルク側に移ったものとみなす(ゼンタに固有の降伏日は史料に読まれず、日付はセゲドから取られた。TDV zenta:1686年10月からオスマンとハプスブルク主導の同盟国の間で戦闘が始まった — 宣言付きの近似)。", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["パトラ(Balyabadra)の喪失 — モレアの北の門", "b9cff63c"], "d": ["コリントス湾の口にあるパトラは、モレアとルメリアの間の通過を押さえる港であった。ヴェネツィア軍が都市を取った後、湾の両岸の要塞も次々に陥落し、半島は陸から完全に孤立した。この作戦の終わりにモレア全体がヴェネツィアに移り、地域は1715年まで「レーニョ・ディ・モレア(モレア王国)」の名で統治されることになる。", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["ゴルドゥス(コリントス)のヴェネツィアへの譲渡", "9a25b6b9"], "d": ["パトラの陥落の後、コリントスは和平の形でヴェネツィア人に譲られ、ムスリムの住民は都市を去った。1687年8月、モロジーニの軍はアテネ遠征のためコリントスに集結していた。", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["エゲルの喪失", "983391aa"], "d": ["エゲルは、1596年にメフメト3世自らが参加した遠征で取られ、自らの名を冠する州の中心となっていた。北ハンガリーのこの最後の大きなオスマン要塞は、第二モハーチの敗北の後、完全に包囲されたまま1年抵抗し、飢えのため降伏した。その喪失とともに、オスマン帝国のハンガリーにおける北の側面は完全に清算された。", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["セーケシュフェヘールヴァール(İstolni Belgrad)の喪失 — ハンガリー王たちの戴冠の都", "c6147255"], "d": ["ハンガリー王たちが何世紀にもわたり戴冠し、埋葬された都市は、1543年にカーヌーニーによって取られ、ブダ州の最も重要なサンジャクの中心の一つとなっていた。ブダの陥落から約2年後、周囲を完全に断たれた要塞は降伏した。この喪失により、ドナウ西岸のオスマンの存在はスレムとオシエクの周辺に押し込められた。", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["シゲトヴァールの喪失", "834910a7"], "d": ["シゲトヴァールは、スレイマン1世(カーヌーニー)が13度目で最後の遠征の1566年に、包囲のさなかに亡くなった要塞であった。このためオスマンの記憶の中で象徴的な位置を持っていた。123年後、周囲のすべての要塞が陥落した後に、沼地に守られた要塞も降伏した。カーヌーニーの内臓が埋められた廟とその周りの町は、ハプスブルクの統治に移った後に破壊された。同日に本アトラスでオスマンからハプスブルクに移る他の定住地は、バルチュである。これはシゲトヴァールの兄貴分中心地の連鎖に従う(Bánlaky 0017/1449。宣言付きの近似)。", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["ナジヴァーラド(Varad)の喪失", "6cce360d"], "d": ["ナジヴァーラドは、1660年にKöprülü Mehmed Paşaが取り、自らの名の州の中心とした、トランシルヴァニアに開く鍵の要塞であった。サランカメンの敗北の後、完全に孤立した要塞は、2年近く続いた封鎖の後に飢えのため降伏した。その喪失とともにトランシルヴァニアに対するオスマンの影響力は事実上終わり、ハプスブルクの支配はティサ川の東に定着した。", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["ヤノヴァ(Yanova)の喪失 — トランシルヴァニア街道の閉鎖", "4b5e30d8"], "d": ["ヤノヴァは1658年に取られ、ナジヴァーラドとティミショアラの間のつながりを押さえていた要塞であった。ナジヴァーラドの陥落の直後に周囲を断たれると、それも失われた。こうしてティミショアラ州は北から完全に孤立し、カルロヴィッツまでオスマンの手に残る唯一のハンガリーの土地として存続した。", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["モンテネグロにおけるウラディカ統治の成立 — ツェティニェの事実上の離脱", "a924b778"], "d": ["神聖同盟戦争がバルカンにおけるオスマンの統制を緩めた年月に、ツェティニェ修道院を率いる府主教の職は、ペトロヴィチ家で父から子に受け継がれる職となり、地域は事実上別個の統治を得た。山の近寄りがたさのおかげで、このウラディカ制は2世紀にわたり、完全に独立でも完全に従属でもない位置で存続した。法的な独立は1878年のベルリン条約でようやく承認されることになる。", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["ゴルドゥス(コリントス)の奪還", "26f53e3a"], "d": ["Damad Ali Paşaのモレア遠征の最初の大きな宿営地はコリントスとなった。オスマンは1715年6月に都市をヴェネツィア人から取り戻し、ここから半島の残りに進んだ。", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["ナーディルの攻勢:タブリーズ、ナヒチェヴァン、ハマダーン、ケルマーンシャー、Merâga、Kasr-ı Şîrînの喪失", "d95efd59"], "d": ["サファヴィー朝の崩壊を利用して1723年から1727年の間に取られた西イランの都市は、イランで事実上の権力を握ったナーディル・ハーンの攻勢によって、一つずつ失われた。アゼルバイジャンではErdebilとHalhalもナーディルの手に渡った。ハマダーン、ケルマーンシャー、Kasr-ı Şîrînの喪失はイスタンブルで大きな反響を呼んだ。軍が出陣せずユスキュダルで待機したことと、喪失をもみ消そうとしたことは、6週間後に勃発するパトロナ・ハリルの反乱の直接の原因の一つとなった。本アトラスは、Hoyの連鎖に従うKoturもこの日にオスマンからサファヴィー朝に移ったものとみなす(Uluerler 2015、Turkish Studies 10/5、6頁。Koturに固有の日付は史料にない — 宣言付きの近似)。", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["バグヴァード(アルパチャイ)の敗北 — コーカサスのナーディル・ハーンへの喪失", "4262f54c"], "d": ["サファヴィー朝の崩壊を利用して1723年から1725年に取られたコーカサスの諸州は、10年間保持できた。イランで事実上の権力を握ったナーディル・ハーンは、エレヴァン近くのバグヴァードでオスマン軍に大敗を喫させ、総司令官Abdullah Köprülü Paşaは戦場で命を落とした。敗北の後、エレヴァン、トビリシ、ギャンジャ、シルヴァンは数か月のうちに撤収された。東部国境は、1746年に再確認される形で、1639年のKasr-ı Şîrîn線に戻った。", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["ベンデルのロシアへの喪失", "0daca453"], "d": ["カグール平原の敗北の後、オスマン軍はドナウの南に退き、モルダヴィアとオチャーコフの間の要塞は孤立して残された。ドニエストル川の渡河地点を押さえるベンデルは、2か月の包囲の後に強襲で占領され、都市は略奪された。要塞の喪失は黒海北部の防衛線の中央の環を断ち、続いてAkkirmanとKiliも陥落した。キュチュク・カイナルジャでベンデルは返還されるが、1806年に再び失われることになる。", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["クウェートにおけるサバーハ首長国のオスマン保護下への編入", "3584dba0"], "d": ["TDVのクウェートの項によれば、港はナジュドから来たウトゥブ族が18世紀初めに築き、サバーハ家が世紀の後半に統治を引き継いでいた。ハサーがサウード家の手に渡った同じ年月に、ワッハーブ派の圧力を前にバスラに寄るほかなかった首長国は、オスマンの保護下に入った。結びつきは1871年にミドハト・パシャのバスラの再編で正式なものとなり、クウェートはバスラ・サンジャクの三つのカザー(郡)の一つとされることになる。イラクのその後の領土の主張もこの記録に基づく。", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["メッカのワッハーブ派への喪失", "2da23acd"], "d": ["ナジュドに生まれたワッハーブ派の運動は、サウード・ブン・アブドゥルアズィーズの時代にヒジャーズに向かった。ターイフとメディナの後、メッカも二度目に引き渡された。メッカの首長Şerif Gālibは、首長位にとどまることを条件に都市をワッハーブ派に引き渡した。廟は破壊され、ダマスカスとカイロから来る巡礼隊の道は断たれた。スルタンが毎年ハラマイン(両聖都)に送っていたスッレ(贈与)もこの年月に途絶え、1915年まで途切れずに続いたこの支給の唯一の例外が、ワッハーブ派の支配の時代である。両聖都の守護者という称号はスルタンの正統性の基本的な拠り所の一つであったため、この喪失は領土の喪失を超えた重い政治的打撃となった。奪還には7年かかり、ムハンマド・アリー・パシャの軍によって可能となる。", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["ドゥブロヴニク共和国の終わり — フランスの占領", "f8e27bf1"], "d": ["カンポ・フォルミオ条約(1797年)でダルマチア海岸に定着したフランスは、1806年5月27日にドゥブロヴニクを占領し、小さな商業共和国を終わらせた。こうして1458年からオスマンに年貢を払うことで自治と通商特権を保っていたドゥブロヴニクの、3世紀半に及ぶ従属の地位は終わった。都市と共和国のムリェト(Mljet)島は、地図上で直接フランスの統治に移る。", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["スフミのロシアへの喪失 — 東黒海岸の開放", "adc96bd4"], "d": ["1806年から1812年のオスマン・ロシア戦争で、ロシア艦隊は東黒海岸に向かい、アブハジアにおけるオスマンの支配が拠っていたスフムカレ(Sohumkale)を取った。要塞は、コーカサスの部族との連絡と海岸交易の中心であった。その喪失とともに、ロシアは初めて黒海の東岸に恒久的に定着し、オスマンのコーカサスにおける影響力はアナパとポティの周辺に押し込められた。", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["パルガのオスマンの統治への引き渡し", "66e0cc5d"], "d": ["パルガは1401年からヴェネツィアの手にあり、一度もオスマンの統治に入ったことがなかった。ヴェネツィアの滅亡の後、順にフランス、イギリスに移った。TDVのTepedelenli Ali Paşaの項は状況を次のように要約する。都市はイギリス人に降伏し、Ali Paşaの統治には1819年にようやく譲られた。引き渡しは、住民の大部分がイオニア諸島に移住する結果となった。こうして、パッサロヴィッツでヴェネツィアに残されたプレヴェザ・パルガ・ヴォニツァの三つ組の最後のものも帝国に編入された。パルガは94年間オスマンの領土となる。", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["ゴルドゥス(コリントス)のギリシア人反乱者への移行", "892dcdc6"], "d": ["ギリシア独立戦争の間に、アクロコリントスは反乱者の手に渡り、要塞の司令官Kâmil Beyは捕虜となった。", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["ナフプリオ(Anabolu)の反乱者への喪失", "1a67fa50"], "d": ["モレアで最も強力な防備を持つ港であったナフプリオは、1年を超える封鎖の後、飢えのため降伏した。要塞は、蜂起の始まりから、半島におけるオスマンの統制の最後の大きな拠り所であり、その喪失とともにモレア全体が反乱者の手に渡った。都市はまもなく、新しいギリシア国家の最初の首都となる。", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["レパント(İnebahtı)のギリシアの統治への移行", "c9d19d4b"], "d": ["ギリシアの蜂起までオスマンの手に残っていたコリントス湾の北岸のレパント(İnebahtı)は、1829年4月に失われ、ギリシアの統治に入った。町の名は古代のナフパクトス(Navpaktos)に改められた。町のムスリムとユダヤ人の住民は完全に姿を消し、ここは小さな町となった。", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["アルジェのフランスによる占領 — 300年続いたオジャクの終わり", "0be8f568"], "d": ["債権をめぐる紛争から生じた扇事件(扇で打たれた事件)を口実に、フランスはアルジェ沿岸を3年間封鎖し、続いてシディ・フェルーシュに兵を上陸させた。3週間の作戦の終わりにフセイン・ダイは降伏し、1516年から続いたオスマン・アルジェ・オジャクは終わった。占領は首都にとどまらなかった。内陸のトレムセン、シェルシェル、メデアも同じ夏に失われた。海岸全体がフランスの統制下に入るにはさらに24年を要することになる。", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["エヴィア(Eğriboz)のギリシアへの引き渡し — 島(Karistos、Oreoi)とともに", "7b524aa4"], "d": ["ギリシア独立戦争の間、激しい戦闘の舞台となったがオスマンの手に残っていたエヴィアは、和平条約が発効した後、1831年にギリシア人に引き渡された。1470年から重要な海軍基地であった都市のムスリムの住民は、すべての財産を非常に安い値で売り、集団でオスマンの領土に移住した。都市は長く空になり、ドイツ人旅行者ファルメライヤーは1842年にこれを幽霊都市と形容した。", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["オラン(Vehrân)のフランスによる占領", "a8415d66"], "d": ["1792年にスペインが戦わずに引き渡したオランは、アルジェ西部で最大の港であった。首都の陥落の6か月後にフランス軍部隊が都市に入った。ここから始まった西部作戦は、まもなく、アブド・アルカーディルの15年続く抵抗に出会うことになる。", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["アンナバ(ボーヌ)の占領", "21f37fb1"], "d": ["東アルジェのチュニジア国境に近い港アンナバは、フランス軍に取られ、コンスタンティーヌへの進軍の基地とされた。都市はまた、サルデーニャ島の対岸で最も近いアフリカの港でもあった。", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["アテネの新ギリシア国家への引き渡し(バイエルン部隊がアクロポリスを受け取った日)", "deee4d37"], "d": ["1456年からオスマンの手にあったアテネは、ギリシア独立戦争の間に何度か手が替わり、アクロポリスの守備隊は1827年に再びオスマンの統制に入っていた。ロンドン議定書で引かれた国境の北に位置したため、都市は新しい王国に引き渡され、守備隊はアクロポリスを撤収した。アトラスの日付は、バイエルン部隊がアクロポリスを受け取った日である。オスマンの守備隊の実際の退出は数日後に行われた(St Clair、Who Saved the Parthenon?、Open Book Publishers、2022、第13章。Finlay、Journals and Letters、第1巻、67頁)。翌年、アテネはナフプリオに代わってギリシアの首都と宣言された。", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["ベジャイア(Bicâye)の占領", "a8927e00"], "d": ["カビリアの山々が海に開くベジャイア港は、アルジェとアンナバの間の海岸線の最後の独立した環であった。海軍砲兵の支援によって取られたが、背後の山がちの内陸部は、さらに30年フランスの統制に入らなかった。これらの海岸沿いの占領が、オスマン・アルジェが地図上で年ごとに溶けていく様を形づくる。", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["セティフの占領", "2073731a"], "d": ["コンスタンティーヌが1年前に陥落した後、フランス軍は高原に上り、古代ローマの都市セティフを取って恒久的な守備隊を置いた。セティフは、海岸とサハラの間の隊商路が交わる地点であった。その占領は、フランスがもはや港だけでなく内陸の交易網も統制し始めたことを示した。", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["ビスクラの占領 — サハラの門の喪失", "d895cad0"], "d": ["ビスクラは、アトラス山脈の南麓でサハラに開く門であり、ナツメヤシのオアシスの中心であった。アブド・アルカーディルの抵抗が砕け始めた年月に取られたことで、フランスの統制は初めて砂漠の北縁に達した。これ以後は、オアシスごとに進む砂漠の作戦となる。", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["トゥグルトの占領 — アルジェリア全体の喪失", "33c056e2"], "d": ["サハラの北にあるオアシス都市トゥグルトの占領によって、1830年に始まった占領は、今日のアルジェリアの北半分で完成した。オスマン帝国はこの年月、クリミア戦争でフランスと同じ側で戦っていた。アルジェに対する法的な主張を正式に放棄したことはなかったが、事実上は一歩も踏み出せなかった。北アフリカでオスマンの手に残った唯一の土地はトリポリであった。", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["オベイドの陥落 — コルドファンのマフディー軍への移行", "58299f62"], "d": ["マフディーを名乗ったムハンマド・アフマドが始めた運動は、エジプトのスーダンにおける統治に対して急速に広がった。コルドファンの中心オベイドは4か月の包囲の後に陥落し、蜂起の首都となった。都市の国庫と武器庫は、運動の軍隊化を可能にした。スーダンは法的にはまだオスマンに従属するエジプトのヘディーヴ領の土地であり、したがって喪失は地図上で帝国の本体から落ちる。", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["ハルツームの陥落 — スーダン全体の喪失", "d4b98464"], "d": ["10か月に及ぶ包囲の後、マフディー軍は青ナイルと白ナイルが合流する地点のハルツームに入った。都市の総督ゴードンは殺され、救援のために送られたイギリス部隊は2日遅れた。この日以後、センナール、ドンゴラ、コルドファンを含むスーダン全体が14年間マフディー国家の統治下に残った。地域は1899年に、オスマンの結びつきが完全に断たれた状態で、イギリス・エジプト共同統治に入ることになる。", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["マッサワのイタリアによる占領 — 紅海西岸の喪失", "c333b95b"], "d": ["ハベシュ州の中心であるマッサワ港は、マフディーの蜂起がスーダンを覆った混乱を利用したイタリアによって占領された。これがイタリア領エリトリアの核となった。北のスアキンと沖のダフラク諸島も同じ過程で失われた。こうして、ヤヴズ・スルタン・セリムの時代から続いていた紅海の西岸におけるオスマンの支配は終わり、海は両岸とも外国の水域となった。", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["ロドス島のイタリアによる占領", "e08662c5"], "d": ["トリポリタニア戦争でオスマン帝国を交渉の席に着かせようとしたイタリアは、戦争を地中海に持ち込み、ロドスに兵を上陸させた。島は数日のうちに受け取られた。1522年にカーヌーニーが長い包囲の末に取り、390年保持してきたロドスは、こうして帝国の東地中海における最大の島の基地ではなくなった。ウシー条約では一時的な占領とされたが、二度と取り戻されなかった。", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["ドデカネスのイタリアによる占領", "200aacf2"], "d": ["ロドスの占領から1週間のうちに、イタリア艦隊は周囲の島々も占領した。この諸島には後に「ドデカネス(Onikiada)」の名が与えられることになる。島の多くはアナトリア海岸から数マイルの距離にあり、エーゲ海の南東の通路を統制していた。占領はウシー条約でトリポリタニアの割譲の見返りに一時的なものとされたが、イタリアは島々を一度も空けなかった。島は1947年にギリシアに引き渡されることになる。", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["コス島の占領", "ab246c62"], "d": ["ドデカネス作戦の最後の環であるコス島は、ボドルム半島のすぐ対岸にある肥沃で人口の多い島であった。占領とともに、エーゲ海の南東の隅のすべての島がイタリアの統制に入り、アナトリアの南西岸は端から端まで外国の島の鎖で囲まれた。", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["イカリアの独立宣言", "c4452033"], "d": ["サモスとキオスの間の小さなイカリア島で、住民は、イタリアの占領が生んだ不確実な状況のなかで蜂起してオスマンの憲兵を島から追い出し、自らの旗、切手、議会を持つ5か月続く「自由国」を宣言した。1912年11月に島はギリシアに編入された。小さいながら、この事件は、エーゲ海で中央の統治がどのように解体したかの明白な指標である。", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["サモスのオスマン統治からの離脱", "3a862f2b"], "d": ["サモスは、1832年からオスマンに納税し、イスタンブルが任命する侯によって統治される自治侯国であった。トリポリタニア戦争が生んだ空白のなかで、島の統合派の運動が統治を掌握し、自治侯国の体制は事実上終わった。島は同年のうちにギリシアに編入されると宣言した。アナトリア海岸から2キロメートルのこの島は、エーゲ海で失われた最初の土地の一つとなった。", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["ヨアニナの陥落 — エピロスとパルガの喪失", "d42fce18"], "d": ["バルカン戦争で5か月にわたり包囲されたヨアニナは、ビザニ陣地の陥落の後に降伏した。都市とともにエピロス全体がギリシアに移った。ヨアニナ・サンジャクに属するパルガもこの日に失われ、94年に及ぶオスマンの統治は終わった。ヨアニナの喪失は、帝国のアドリア海に開く最後の窓が閉じられることを意味した。", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["エディルネのブルガリアへの陥落", "459d2e56"], "d": ["5か月半に及ぶ包囲の後、弾薬と糧食が尽きたエディルネは降伏し、Şükrü Paşaは捕虜となった。1361年からオスマンの手にあり、92年間首都であった都市の陥落は、バルカン戦争の最も重い打撃とされた。エディルネは4か月後、第二次バルカン戦争でブルガリアが他の戦線で崩れたのを利用して取り戻されることになる。", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["ヤンブーのシャリーフ・フサインの軍への喪失", "e291c816"], "d": ["シャリーフ・フサインが6月に始めた蜂起は紅海沿岸に広がった。メディナの港であるヤンブーは、イギリス艦隊の支援を受けた反乱者の手に渡った。港は、蜂起に外部から入る武器と金の流れの主な門となった。こうして、メディナにいるファフレッティン・パシャの部隊の海との連絡は断たれ、都市はヒジャーズ鉄道の終点で孤立して残された。", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["第三次ガザの戦い — ガザとハーン・ユーニスの喪失", "c142a069"], "d": ["二度の失敗した試みの後、アレンビーは三度目の攻勢でベエルシェバを迂回して戦線を破り、6か月保たれたガザ線は崩れた。ガザとその南のハーン・ユーニスは同日に撤収された。この突破は、パレスチナ戦線の解体の始まりとなった。エルサレムは5週間後に陥落することになる。", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["ギュムルジネの占領 — 西トラキアの喪失", "904d813c"], "d": ["ムドロスの後にまず協商国の部隊の統制下に入った西トラキアは、サンレモ会議の決定でギリシアに残され、ギリシア軍がギュムルジネ(コモティニ)に入った。1913年にブルガリアから取り戻されていた地域は、帝国がルメリアで失った最後の土地となった。地域のトルコ人住民の地位は、3年後のローザンヌで少数者の制度によって規定されることになる。この占領により、西トラキアのギュムルジネ、İskeçe、ドゥデアーチ(Dedeağaç)、Sofuluの各カザーがギリシアに移った。", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["イル・ハン国の解体:アブー・サイード・バハードゥル・ハンの死", "0f187469"], "d": ["TDV『イスラーム百科事典』のİlhanlılar項によれば、アブー・サイードが後継者を残さずに没したことは、1世紀にわたりイランを支配してきたイル・ハン国の分裂を招いた。諸将は王位をめぐる争いを利用して、ジャライル朝、カラ・コユンル、ムザッファル朝、ホラーサーンのサルバダール朝、Eretnaoğullarıといった地方王朝を立てた。この解体は地域を、1世紀続く諸侯国のモザイクに分割した。最終的にはティムールの遠征により再び統一されることになる。", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["ティムール、イランの大部分を支配下に置く", "1cee2b82"], "d": ["TDV『イスラーム百科事典』のTimur項によれば、1380年代初頭から、サルバダール朝、ケルト朝、ムザッファル朝などイル・ハン国以後の地方王朝を一つずつ排除してきたティムールは、1386-1388年の「三年遠征」の間にイランの大部分を事実上支配下に置いた。ムザッファル朝への最終的な止めは1393年に刺されることになる。地域はこうして1世紀に及ぶ分裂の後、再び単一の中央権力のもとに結ばれた。", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["アラス川の勝利:カラ・ユースフ、ティムール朝のアブー・バクル・ミールザーを破る", "4b61a75a"], "d": ["1405年のティムールの死の後、亡命先から戻ったカラ・コユンルの君主カラ・ユースフは、Avnikを奪い東アナトリアの領土を取り戻した後、アゼルバイジャンと二つのイラクの主とされたティムールの孫アブー・バクル・ミールザーに向かって進軍し、アラス川のほとりで彼を破った。この勝利はタブリーズをカラ・コユンルにもたらさなかった。TDVの`tebriz`項は、市が1408年にアブー・バクル・ミールザーの手にあったと記す。アゼルバイジャンをもたらした戦いは1408年4月13日のSerdrûdである。", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Serdrûdの勝利:タブリーズとアゼルバイジャンがカラ・コユンルの手に", "1f0a429d"], "d": ["カラ・ユースフは、ティムール朝のアブー・バクル・ミールザーを、アラス川の戦いに続いて2度目に、タブリーズ近郊のSerdrûdで破った。この勝利はアゼルバイジャンをカラ・コユンルにもたらした。カラ・ユースフはその後、Bistam Beyにイラク・アジャミー征服を命じた。", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["イスタンブルでのペスト流行と宮廷のエディルネへの移動", "70c7a163"], "d": ["TDV『イスラーム百科事典』のイスタンブルの項によれば、都市の急速で密な定住は、時期ごとに疫病が広がる素地を整えた。1466年のペスト流行の際には、宮廷と国家の要人は一時的にエディルネに退いた。都市の人口はこうした流行で深刻な損失を被った。", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["ウズン・ハサン、カラ・コユンル朝を滅ぼす", "ef68399e"], "d": ["TDV『イスラーム百科事典』のUzun Hasan項によれば、アク・コユンルの君主ウズン・ハサンは、カラ・コユンルの君主ジャハーン・シャーを、ヒジュラ暦872年ラビーウ・アーヒル月12日/1467年11月10日にBingöl-Sancak地方で破って殺した。ジャハーン・シャーの子ハサン・アリーは1468年9月にMerendで敗れ、1469年4月から5月にハマダーンの前で殺され、カラ・コユンル朝は最終的に滅ぼされた。領土はアク・コユンルの支配に移り、国家は次の10年でイラン内部にまで拡大することになる。", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["サフヌ・セマーン学院の教育への開放", "021f2a83"], "d": ["TDV『イスラーム百科事典』のSahn-ı Semânの項によれば、ファーティフ・コンプレクスの内に設けられたこの八つのマドラサは、当時最高水準の教育機関として構想され、オスマンのウラマー階層の頂点をなした。ここでの教授職と修了は、後の世紀においてカーディー職と教授職の経歴における最も権威ある段階とされた。", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["トプカプ宮殿(Saray-ı Cedîd)の完成", "d2db6323"], "d": ["TDV『イスラーム百科事典』のトプカプ宮殿の項によれば、当時の史料は工事の開始と終了の日付で食い違う。バーブ・ヒュマーユーンの碑文のヒジュラ暦883年(1478年)の日付によれば、ファーティフの命令でおそらく1465年に始まった工事はこの年までに大部分が完成し、宮殿は旧宮殿にあった国家の中心に取って代わった。こうしてスルタンは、3世紀にわたって国家の行政的・儀礼的な心臓部となる新しい住まいに移った。", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["バヤジト2世のイスタンブルでの即位", "9b686d04"], "d": ["TDV『イスラーム百科事典』のBayezid IIの項によれば、アマスヤのサンジャク・ベイであったシェフザーデ・バヤジトは、父の死の知らせを受けて急いでイスタンブルに来て即位した。弟ジェムのコンヤからの出発を、イェニチェリの支持で後に引き離した。即位に際して、イェニチェリには慣例である即位の祝儀が配られた。この王位の交代は、二人の兄弟間の闘争の導火線ともなった。", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["ジェム・スルタンのブルサでの自らのスルタン宣言", "b355168a"], "d": ["TDV『イスラーム百科事典』のCem Sultanの項によれば、カラマンを経てブルサに達したジェムは、都市を占領して自らをスルタンと宣言し、フトバを読ませた。この短い治世は、兄バヤジト2世が送った軍がイェニシェヒルでジェムを破ったことで終わった。敗北を受けて、ジェムはエジプトに向けて逃れざるを得なかった。", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Gedik Ahmed Paşaの処刑", "6d75a58c"], "d": ["TDV『イスラーム百科事典』のGedik Ahmed Paşaの項によれば、オトラント遠征と大宰相職で知られるこのパシャは、ジェム・スルタン問題での態度とその影響力への懸念から、バヤジト2世の命令でエディルネで処刑された。ファーティフの時代の最も経験豊かな指揮官の一人の死は、宮廷で大きな反響を呼んだ。", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["イスタンブルにおける最初の印刷所の設立", "04475930"], "d": ["TDV『イスラーム百科事典』の印刷の項によれば、スペインから来たユダヤ人移民のダヴィドとサミュエルのイブン・ナフミアス兄弟は、イスタンブルでヘブライ文字による印刷を行う最初の印刷所を設立した。これはオスマン領で活動した最初の印刷事業として記録された。トルコ語・アラビア文字の印刷は、はるかに後の18世紀にようやく可能となる。", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["シャー・イスマーイール、タブリーズを奪取:サファヴィー朝の成立", "014d81e6"], "d": ["TDV『イスラーム百科事典』のSafevîlerおよびAkkoyunlular項によれば、アルダビール道場の若きシェイフであるイスマーイールは、アナトリアのキズルバシュの信徒から組織した軍を率い、ナヒチェヴァン地方でアク・コユンルのスルタン・アルワンドに大敗を与えた。アルワンドはディヤルバクルに逃れ、イスマーイールはタブリーズに入って即位し、十二イマーム派シーア派を公式の宗派と宣言した。こうしてアク・コユンルの支配と、地域のイル・ハン国以後の諸侯国時代がともに幕を閉じ、3世紀続くサファヴィー朝が成立した。", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["イスタンブルの「小審判の日(Küçük Kıyamet)」地震", "53e3b1d6"], "d": ["TDV『イスラーム百科事典』のイスタンブルの項によれば、都市を襲った激しい地震は、当時民衆の間で「小審判の日」と呼ばれた。城壁、モスク、多くの建物に重い被害が生じ、多数の死者が出た。バヤジト2世の命令で、都市では大規模な修復と整備の動員が始められた。", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["シャー・クル蜂起の開始", "3d9a4a90"], "d": ["TDV『イスラーム百科事典』のŞahkulu Baba Tekeliの項によれば、サファヴィー朝の宣伝に養われたシャー・クルは、テケ地方で多数のテュルクメンの群衆を周りに集め、宗教的・社会的性格を持つ大きな蜂起を始めた。蜂起は当時最も深刻な国内の治安危機の一つとして、国家の中央の権威を深く揺さぶった。", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["バヤジト2世のディディモティホへの道での死去", "c46e98c9"], "d": ["退位した後、生まれた都市ディディモティホに行くためイスタンブルを発った先帝は、一日に5、6キロしか進めない輿(タフトゥレヴァン)で進むうち、チョルル近くのアバラル村で具合が悪くなり、ヒジュラ暦918年ラビーウ・アル=アウワル月25日(1512年6月10日)に死去した。TDV『イスラーム百科事典』は死因を非常に疑わしいとみなし、国内外のいくつかの史料によれば毒殺された可能性が指摘されている。31年の治世の後、オスマン・ガーズィーの血を引く第8代のスルタンはこうして命を落とした。", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["シェフザーデ・アフメトのヤヴズ・セリムの命令による処刑", "65abb2f2"], "d": ["TDV『イスラーム百科事典』のSelim Iの項によれば、父バヤジト2世の寵愛を受け、王位の主な競争相手であったシェフザーデ・アフメトは、兄セリムの即位の後に行った闘争でイェニシェヒル平野で敗れ、戦場から逃げる際に捕らえられて殺された。この事件とともに、セリムは兄弟や甥たちの間の王位争いを大部分終わらせた。", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["イブラヒム・パシャの大宰相任命", "9c94c1e3"], "d": ["TDV『イスラーム百科事典』のİbrâhîm Paşa, Makbulの項によれば、侍従頭(ハス・オダバシュ)からルメリアのベイレルベイに、そして同じ日に大宰相に昇進したイブラヒム・パシャは、ヒジュラ暦929年シャアバーン月13日(1523年6月27日)に大宰相となった。これは宮廷勤めから直接大宰相に至るという前例のない任命であり、イブラヒム・パシャのカーヌーニーにおける並外れた近さを示していた。", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["バルバロス・ハイレッディン・パシャの海軍提督任命", "a0ff6bab"], "d": ["TDV『イスラーム百科事典』のBarbaros Hayreddin Paşaの項によれば、アルジェでの成功で知られるハイレッディン・パシャは、1534年4月6日にイスタンブルに呼ばれて、海軍提督とCezâyir-i Bahr-i Sefîd(群島)のベイレルベイに任命された。この任命は、オスマン艦隊の再編と、地中海における海軍力の制度化の始まりとされる。", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["リュステム・パシャの最初の大宰相就任", "ddfcc014"], "d": ["TDV『イスラーム百科事典』のRüstem Paşaの項によれば、Hadım Süleyman Paşaがある宰相との不和を理由に罷免された後、ヒジュラ暦951年ラマダーン月17日(1544年12月2日)にリュステム・パシャが大宰相に任命された。ミフリマー・スルタンとの結婚で宮廷との近さを増したリュステム・パシャは、この職で、カーヌーニーの時代の最も影響力のある政治家の一人となった。", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["エブッスード・エフェンディのシェイヒュルイスラーム就任", "11ed04f8"], "d": ["TDV『イスラーム百科事典』のEbüssuûd Efendiの項によれば、8年間ルメリアのカザスケル(軍法官)を務めたエブッスード・エフェンディは、ヒジュラ暦952年シャアバーン月(1545年10月)にシェイヒュルイスラームに就任し、この職に28年11か月とどまった。カーヌーニーの法令集をシャリーア法と調和させるファトワーで知られたエブッスード・エフェンディは、当時の法と教育の機関の形成において決定的な役割を果たした。", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["バルバロス・ハイレッディン・パシャの死去", "3378a0bf"], "d": ["TDV『イスラーム百科事典』のBarbaros Hayreddin Paşaの項によれば、短い病の後、ヒジュラ暦953年ジュマーダー・アル=ウーラー月6日(1546年7月5日)にイスタンブルで亡くなった。ベシクタシュに自ら建てさせたマドラサに隣接する廟に葬られたバルバロスの死は、オスマン艦隊が築いた地中海の優位の一時代の終わりと見られた。", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["スレイマニエ・モスクとコンプレクスの建設の開始", "101ec36f"], "d": ["TDV『イスラーム百科事典』のSüleymaniye Camii ve Külliyesiの項によれば、ミマール・スィナンを主任建築家として1550年に礎石が置かれたコンプレクスは、モスクの傍らにマドラサ、病院、救貧食堂、図書館からなる大きな社会施設として構想された。建設は、カーヌーニーの治世の力とイスタンブルの整備を象徴する最大の建築事業の一つであった。", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["イスタンブルとその周辺で新たなペストの波が始まった", "547d6bf6"], "d": ["TDV『イスラーム百科事典』のTâunの項によれば、イスラーム世界に影響した16世紀の疫病の一つが1552年から1566年にかけて起こり、特にイスタンブル、アナトリア、ルメリア、エジプト、北アフリカで猛威を振るった。広がる交易路と人口の流動性の増加は、帝国の最強期に疫病の拡大を容易にした要因に数えられる。", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["カラ・アフメト・パシャの大宰相任命", "a7d7748e"], "d": ["TDV『イスラーム百科事典』のKara Ahmed Paşaの項によれば、第二宰相として務めていたカラ・アフメト・パシャは、現職の大宰相が突然罷免された後、ヒジュラ暦960年シャウワール月27日(1553年10月5日)に大宰相に昇進した。この交代は、シェフザーデ・ムスタファの処刑と同じころに重なった、宮廷内の力の均衡が素早く入れ替わった時期を示している。", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["海軍提督ピーリー・レイスの処刑", "3b2ad7a0"], "d": ["TDV『イスラーム百科事典』のPîrî Reisの項によれば、ホルムズの包囲を解く際に賄賂と引き換えにムスリムの財産を略奪し、軍を戦場で見捨てたという嫌疑がエジプトに達したため、有名な航海者で地図製作者は、ヒジュラ暦960年末(1553年末)にカイロで処刑された。財産を没収されたピーリー・レイスの死は、当時のバスラとインド洋の海軍政策におけるパシャ間の対立の結果と評価される。", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["カラ・アフメト・パシャの処刑、リュステム・パシャが再び大宰相に", "9a85076a"], "d": ["TDV『イスラーム百科事典』のRüstem PaşaとKara Ahmed Paşaの項によれば、ヒジュラ暦962年ズルカアダ月13日(1555年9月29日)の日にディヴァンの会合の最中に突然処刑されたカラ・アフメト・パシャの代わりに、ヒュッレム・スルタンとミフリマー・スルタンの支持を得て、リュステム・パシャが同日に二度目の大宰相に任命された。事件の裏側は史料で明らかにされておらず、宮廷内の陰謀の結果と評価されている。", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["ヒュッレム・スルタンの死去", "1ae998b5"], "d": ["TDV『イスラーム百科事典』のHürrem Sultanの項によれば、カーヌーニーのハセキ・スルタンとして長年宮廷内で大きな影響力を持ったヒュッレム・スルタンは、ヒジュラ暦965年ジュマーダー・アル=アーヒラ月26日(1558年4月15日)にイスタンブルで死去し、スレイマニエ・モスクのコンプレクス内の廟に葬られた。ヴァーリデ・スルタン・ハフサの1534年の死の後、ハレムに対する権威を固めていたヒュッレム・スルタンの死は、息子たちバヤジトとセリムの王位争いに対する均衡の働きを取り除いた。", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Sokullu Mehmed Paşaの大宰相への昇進", "896391a2"], "d": ["TDV『イスラーム百科事典』のSokullu Mehmed Paşaの項によれば、Semiz Ali Paşaがヒジュラ暦972年ズルカアダ月30日(1565年6月29日)に死去したことで大宰相に昇進したSokullu Mehmed Paşaは、カーヌーニーの最後の大宰相となり、この職をその後のセリム2世とムラト3世の時代にも続けて、オスマン史上最も長く務めた大宰相の一人となった。", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["セリム2世がイスタンブルに着いて即位した", "0289ef97"], "d": ["スレイマン1世(カーヌーニー)のシゲトヴァールでの死の後、知らせは秩序を乱さぬよう、Sokullu Mehmed Paşaによって何週間も秘密にされた。TDV『イスラーム百科事典』によれば、セラーニキーはセリムのイスタンブル到着の日をヒジュラ暦974年ラビーウ・アル=アウワル月15日(1566年9月30日)とするが、同時代の歴史家の大半は9日(9月24日)を正しいとする。カーヌーニーの死は1566年10月24日から25日にようやくベオグラードで正式に宣言された。", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["Kılıç Ali Paşaが再建した艦隊が出航した", "d0fc9f48"], "d": ["レパントの重い敗北(1571年10月7日)の後、冬の間ずっと造船所で船が造られた。TDV『イスラーム百科事典』によれば、ヒジュラ暦980年サファル月1日(1572年6月13日)に、250隻のガレー船と約300人の志願の漕ぎ手長からなる新しい艦隊が、力の誇示とともに進水した。", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Sokullu Mehmed Paşaが暗殺された", "6ffa8dec"], "d": ["3人のスルタンの時代に14年間大宰相を務めたSokullu Mehmed Paşaは、ヒジュラ暦987年シャアバーン月20日(1579年10月12日)に、邸宅での午後のディヴァンで請願を出すように近づいてきたダルウィーシュに短剣で刺されて殺された。TDV『イスラーム百科事典』によれば、暗殺は処刑されたハムザヴィー教団のシェイフHamza Bâlîの復讐に関係していたかどうかが議論される。", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["イギリスとの最初の通商アフドナーメ — イギリス人へのカピチュレーション付与", "59c8e3ee"], "d": ["1578年10月にイスタンブルに送られたイギリスの代表ウィリアム・ハーボーンは、Sokullu Mehmed PaşaとHoca Sâdeddin Efendiの支持を得て、ムラト3世から1580年付のアフドナーメ(通商特許状)を得た。このアフドナーメによって、イギリス商人は、それ以前にフランス人とヴェネツィア人に認められていた通商上の特権(カピチュレーション)を同じ程度に享受する権利を得た。エリザベス1世女王とムラト3世の間で書簡が交わされ、二国間の正式な関係も築かれた。これらの特権の直後の1581年にロンドンでレヴァント会社が設立され、イギリス人は1825年まで地域での交易をこの会社を通じて行った。", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["イスタンブル天文台が勅令により取り壊された", "3bc0c78c"], "d": ["天文台は国に不運をもたらすというファトワーと宮廷内の反対の影響で、ヒジュラ暦987年ズルヒッジャ月4日(1580年1月22日)付の勅令(ハット・イ・ヒュマーユーン)により、イスタンブル天文台は内部のすべての器具とともに取り壊された。TDV『イスラーム百科事典』によれば、これはタキユッディーン・アッ=ラースィドが設けた機関の短命の終わりとなった。", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["シェフザーデ・メフメトの競馬場(アトメイダヌ)での割礼祝宴の開始", "c2926d5d"], "d": ["ムラト3世の息子シェフザーデ・メフメトは、ヒジュラ暦990年ジュマーダー・アル=ウーラー月6日(1582年5月29日)に始まり56日から57日続く壮麗な式典とともに割礼を受けた。TDV『イスラーム百科事典』によれば、アトメイダヌ(旧競馬場)で催された祝祭は、当時の最も華やかな宮廷の祝賀の一つであった。", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["ヌルバヌ・ヴァーリデ・スルタンの死去", "77d0a577"], "d": ["ムラト3世の母ヌルバヌ・スルタンは、ヒジュラ暦991年ズルカアダ月22日(1583年12月7日)に亡くなった。TDV『イスラーム百科事典』によれば、ヴァーリデ・スルタンとしてヴェネツィアとフランスの宮廷と書簡を交わし、ヴェネツィア元老院は同年、その働きに対して2000ヴェネツィア金貨相当の贈り物を送ることを受け入れていた。", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["悪貨(タグシーシュ)の銀貨のためにベイレルベイ事件が勃発した", "db2f2e61"], "d": ["国家が銀貨の銀の割合を下げて支払ったことを受けて、シパーヒーとイェニチェリは宮殿を包囲し、歴史にベイレルベイ事件の名で残る血なまぐさい蜂起を起こした。TDV『イスラーム百科事典』のAbdülkadir Şeyhî Efendiの項によれば、シェイヒュルイスラームはこの事件を受けて罷免された。", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["メフメト3世が即位し、19人のシェフザーデが絞殺された", "2cd9a8c5"], "d": ["メフメト3世は、父ムラト3世の死を受けてヒジュラ暦1003年ジュマーダー・アル=ウーラー月16日(1595年1月27日)の金曜日にイスタンブルに着いて即位した。TDV『イスラーム百科事典』によれば、同じ夜に、成人した4人(ムスタファ、バヤジト、オスマン、アブドゥッラー)を含む19人のシェフザーデが絞殺された。これはオスマン史上最も多数の兄弟殺しであった。", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["サフィエ・スルタンがヴァーリデ・スルタンとして影響力を得た", "000bec21"], "d": ["ムラト3世の妃でメフメト3世の母サフィエ・スルタンは、息子の即位とともに、ヴァーリデ・スルタンとして宮廷政治で決定的な位置に上った。TDV『イスラーム百科事典』によれば、この時期にハレム由来の影響力は、国政への直接介入の規模に達した。", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["メフメト3世がイェニチェリの圧力で自ら出陣した", "d3c50656"], "d": ["大宰相Damad İbrahim Paşaが反対したにもかかわらず、イェニチェリの圧力によって、メフメト3世は、スレイマン1世(カーヌーニー)以後に自ら軍の先頭に立った最初のスルタンとして、1596年6月20日にイスタンブルから出陣した。TDV『イスラーム百科事典』によれば、これは古いガザー(聖戦)の伝統の復活を意味した。", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["1570年代に始まったペストがイスタンブルに影響し続けていた", "eb4ca37a"], "d": ["TDV『イスラーム百科事典』のペストの項によれば、1570年代に始まった流行は17世紀の初めまで影響を続け、イスタンブルをはじめ、アナトリア、バルカン、エジプト、北アフリカを襲った。流行期は、宮廷と都市の生活をしばしば中断させる慢性的な脅威をなしていた。", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["カラヤズジュ・アブデュルハリムが死んだ。反乱の運動が弱まった", "876ca7a6"], "d": ["1601年8月12日にエルビスタン近くのSepetliで被った大敗の後、負傷して退いたカラヤズジュ・アブデュルハリムは、1010年(1602年)に死んだ。TDV『イスラーム百科事典』によれば、死の知らせはヒジュラ暦1010年のラマダーン月(1602年2月から3月)にイスタンブルに達した。史料は、死が傷によるものか、自らの部下によるものかが議論の的であると述べる。", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["兄弟殺しの慣習の事実上の終わり", "9046c607"], "d": ["アフメト1世は即位に際して、先代のスルタンたちと異なり、弟のシェフザーデ・ムスタファを殺させずに命を助けた。この決定は、オスマンの継承制度において年長者継承(エクベル・エルシェド)の方式が事実上採用される始まりとされる。TDV『イスラーム百科事典』の「Mustafa I」の項は、ムスタファがこの日付以後、宮殿で居室(マフフィル)の生活を送ったと伝える。この措置は、何世紀も続いてきた即位時の殺害に事実上の終止符を打った。", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["スルタンアフメト・モスクの礎石が置かれた", "1683262f"], "d": ["アフメト1世の命令で、アトメイダヌで建築家Sedefkâr Mehmed Ağaが建てるモスクの礎石が式典とともに置かれた。TDV『イスラーム百科事典』の「Sultan Ahmed Camii ve Külliyesi」の項によれば、この建造物は、征服の勝利なしに直接国庫から建てられた最初の大きなスルタン・モスクであった点で、当時の批判の対象ともなった。コンプレクスは、モスクとともにマドラサ、救貧食堂、廟も含むように構想された。", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["若きオスマンのイェニチェリによる殺害(Hâile-i Osmâniye)", "324f6582"], "d": ["巡礼を口実にイスタンブルの外に出てイェニチェリ軍団を解散させる計画だという噂を受けて蜂起したイェニチェリとシパーヒーは、オスマン2世を廃位し、イェディクレの牢獄で絞殺させた。TDV『イスラーム百科事典』の「Osman II」の項によれば、この事件は、オスマン史でスルタンが公然と軍事的な反乱によって殺された最初の例であり、王朝と軍の関係に深い断絶を生んだ。最後の数時間は次のように過ぎた。イェニチェリ長Ali Ağaの邸宅に逃げ込もうとする試みが実を結ばなかったため、スルタンは、TDVの表現では「惨めな様子で、頭を覆わず、身なりも乱れた状態で」馬に乗せられ、重い侮辱を受けながら、まずムスタファ1世のいるオルタ・ジャーミーに、同日の午後にはイェディクレに連れて行かれた。一部の歴史家によれば、死を証明するため耳と鼻が切られ、ムスタファ1世の母に見せられた。事件の後、ムスタファ1世は二度目に即位させられた。「Hâile-i Osmâniye(オスマンの惨劇)」と呼ばれるこの事件は、宮廷とオジャク(軍団)の均衡を恒久的に崩し、1世紀にわたって続く正統性の議論を始めた。", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["ムスタファ1世の二度目の即位", "34a0b29a"], "d": ["若きオスマンがイェニチェリによって殺された後、王朝に他の成人男性の成員がいなかったため、ムスタファ1世が二度目に即位させられた。TDV『イスラーム百科事典』の「Mustafa I」の項によれば、この二度目の治世も、前回と変わらず国政を実際に執れないまま過ぎ、国の運営は宰相たちとヴァーリデ・スルタンの手に委ねられた。14か月続いたこの時期は、1623年のムラト4世の即位で終わった。", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["ジバリ大火", "3e42fb08"], "d": ["ジバリで発生し、風の影響で急速に広がった火災は、イスタンブルの大部分を灰にした。TDV『イスラーム百科事典』の「İstanbul」の項によれば、当時の史料は数千戸が焼けたと伝える。火災が木造家屋の構造とタバコの喫煙に結びつけられたことは、ムラト4世がまもなく宣言する厳しいタバコとコーヒーハウスの禁令の直接の理由となった。災厄は、当時のイスタンブルで繰り返された大火の一つにすぎなかった。", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["ムラト4世のタバコとコーヒーハウスの禁令", "5dd71297"], "d": ["ジバリ大火の後、火事と治安への懸念からムラト4世はタバコの喫煙とコーヒーハウスを禁じ、違反者には死刑を含む重い刑が科された。TDV『イスラーム百科事典』の「Murad IV」の項によれば、スルタンは禁令を監督するため、自ら変装して都市の通りを歩き回るほど厳しい内的規律の政策をとった。これらの厳しい措置は、ムラト4世が中央の権威を再確立しようとした努力の一部と評価される。", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["イスタンブルでのペスト流行", "f33f58c5"], "d": ["ムラト4世の時代、イスタンブルは人口の相当部分に影響する重いペストの流行に揺さぶられた。都市内の交易と日常生活は数か月にわたって滞った。TDV『イスラーム百科事典』の「İstanbul」の項は、17世紀に繰り返された流行が都市の人口の均衡に深刻な影響を与えたと記す。流行期には宮廷と上層の人々は、しばらく都市の外の庭園や離宮に移った。", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["ヘザルフェン・アフメト・チェレビの翼による飛行(伝承)", "df474c04"], "d": ["エヴリヤ・チェレビーが伝える伝承によれば、ヘザルフェン・アフメト・チェレビは、自作の翼でガラタ塔から飛び降り、ユスキュダルまで滑空することに成功した。歴史的な確実性は議論されるが、技術的な想像力の象徴となった。スルタンは当初褒美を与えたヘザルフェンを、事件が生んだ反響を受けて、後にアルジェに流した。", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["ジンジ・ホジャ・ヒュセイン・エフェンディの宮殿における影響力の獲得", "41d21572"], "d": ["スルタン・イブラヒムの精神的な苦しみを治療するため宮殿に呼ばれた祈祷師ヒュセイン・エフェンディは、まもなくスルタンの信頼を得て、アナトリアのカザスケルの職にまで上った。TDV『イスラーム百科事典』の「Hüseyin Efendi, Cinci Hoca」の項によれば、彼はこの影響力を財産の蓄積と当時の政治的な出来事への介入に用いた。イブラヒムの死後、すべての職を奪われ、1648年に処刑された。", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Kemankeş Mustafa Paşaの処刑", "0ecc8030"], "d": ["ムラト4世の時代から大宰相を務め、財政改革で国庫に大きな黒字をもたらしたKemankeş Mustafa Paşaは、宮廷内の敵対者たちがイブラヒムに働きかけ、イェニチェリの蜂起を起こそうとしたと告発したことを受けて、絞殺されて処刑された。TDV『イスラーム百科事典』の「Kemankeş Mustafa Paşa」の項によれば、処刑はヒジュラ暦1053年ズルカアダ月21日/1644年1月31日に行われた。Kemankeş Kara Mustafa Paşaは、Hocapaşa市場で死刑執行人Kara Aliによって絞殺され、Çarşıkapıにある自らの廟に葬られた。その死は、当時の大宰相職の不安定さの顕著な例として語られ、短く続いた厳しい改革の時期を終わらせた。", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["クレタ遠征のディヴァンでの決定と艦隊の出航", "9076827e"], "d": ["ヴェネツィア領のクレタ島に対する大規模な遠征を始めることがディヴァン・イ・ヒュマーユーン(御前会議)で決定され、海軍提督が指揮するオスマン艦隊はイスタンブルからクレタに向けて出航した。TDV『イスラーム百科事典』の「Girit」の項によれば、この決定は、約25年続く長い包囲と戦争の時代の政治的な始まりをなした。遠征の開始は、イブラヒムの時代の最大の対外政策の試みとして、国家の要人の間で広範な議論を引き起こしていた。", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["メフメト4世の7歳での即位", "a197a3bc"], "d": ["イブラヒムの廃位の直後に、まだ7歳の息子メフメトが即位させられ、メフメト4世の称号でスルタンとなった。TDV『イスラーム百科事典』の「Mehmed IV」の項によれば、これほどの若年での即位は、祖母キョセム・スルタンと母トゥルハン・スルタンの間の宮廷内の影響力争いを激化させた。この権力闘争は、1651年のキョセム・スルタンの殺害に至ることになる。", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Tarhuncu Ahmed Paşaの均衡予算の改革", "376fc7f2"], "d": ["大宰相Tarhuncu Ahmed Paşaは、長い戦争の年月が生んだ財政危機を乗り越えるため、宮廷の費用も含む厳しい節約計画を実施し、オスマン史で知られる最初の均衡予算(tarhuncu lâyihası)を作成した。TDV『イスラーム百科事典』の「Tarhuncu Ahmed Paşa」の項によれば、この改革は国庫に相当の黒字をもたらしたが、宮廷周辺と高級官僚の間に広範な不満を生んだ。この不満は、1年後の彼の処刑に至ることになる。", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["チュナル事件(Çınar Vak'ası、ヴァクヴァク事件)", "4c6ed90f"], "d": ["TDV『イスラーム百科事典』のÇınar Vak'ası の項によれば、クレタ遠征から給与を受け取らずに戻ったイェニチェリとシパーヒーは、イスタンブルで蜂起し、汚職の嫌疑をかけた国家の要人たちの処刑を求めた。大宰相Zurnazen Mustafa Paşaの没収と流刑の提案は受け入れられず、まず3人の官吏が、続いて30人近い国家の要人が処刑され、遺体はスルタンアフメト広場のプラタナス(チュナル)の木に吊るされた。事件はこのためチュナル事件の名で呼ばれる。", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["キョプリュリュ・メフメト・パシャの条件付きの受諾による大宰相任命", "3a6b7f8f"], "d": ["TDV『イスラーム百科事典』のKöprülü Mehmed Paşaの項によれば、80歳に近いキョプリュリュ・メフメト・パシャは、ヴァーリデ・トゥルハン・スルタンとメフメト4世に提示した厳しい条件(人事に干渉されないこと、自分に対する中傷を信じないこと)を受け入れさせた後に、はじめて印章を受け取った。Boynueğri Mehmed Paşaの後任としてヒジュラ暦1066年ズルカアダ月26日に職に就き、国家の規律を厳しく再確立しようと動いた。", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["カドゥザーデ派の運動のキョプリュリュ・メフメト・パシャによる鎮圧", "5ec3ce84"], "d": ["TDV『イスラーム百科事典』のKadızâdelilerの項によれば、キョプリュリュ・メフメト・パシャは職に就くとすぐ、Kadızâde Mehmed Efendiの周辺とタリーカ(教団)の人々の間の宗教的な衝突に取り組んだ。ウラマーに諮った後、運動の指導者Üstüvânî Mehmed Efendi、Türk Ahmed、Divâne Mustafaに死刑の勅令を出したが、この刑は流刑に減刑され、三人はキプロスに送られた。こうして運動の第二期は終わった。", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["イスタンブルの大火:アーアカプス(Ağakapısı)の焼失", "b9253b66"], "d": ["TDV『イスラーム百科事典』のAğakapısıの項によれば、メフメト4世の時代の1660年7月に起きた大火で、イェニチェリ長の公式の本営であるAğakapısıが完全に焼け、その後再建された。この火災は、当時のイスタンブルを繰り返し襲った大規模な都市火災の一つであった。", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["キョプリュリュザーデ・ファーズル・アフメト・パシャの大宰相任命", "c1999b5c"], "d": ["TDV『イスラーム百科事典』のKöprülüzâde Fâzıl Ahmed Paşaの項によれば、父キョプリュリュ・メフメト・パシャの死を受けて、ヒジュラ暦1072年ラビーウ・アル=アウワル月8日(1661年11月1日)に大宰相に任命された。父と異なり穏やかな性格で、信仰が篤く、学者や芸術家の保護者として知られたファーズル・アフメト・パシャは、15年を超える大宰相職の間、イスタンブルと征服地に図書館や慈善施設を設けさせた。", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["ヴァーニー・メフメト・エフェンディのイェニ・ジャーミーの説教師およびスルタンの師への任命", "7ea6aaae"], "d": ["TDV『イスラーム百科事典』のMehmed Efendi, Vânîの項によれば、キョプリュリュザーデ・ファーズル・アフメト・パシャが大宰相になったことでイスタンブルに呼ばれ、メフメト4世に引き合わされたヴァーニー・メフメト・エフェンディは、まもなくスルタンの親密な関心を得た。1665年にイェニ・ジャーミーの説教師とスルタンの師に任命され、宮廷で最も影響力のある宗教者の一人となった。", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["メルズィフォンル・カラ・ムスタファ・パシャの大宰相任命", "3d1e836c"], "d": ["TDV『イスラーム百科事典』のMerzifonlu Kara Mustafa Paşaの項によれば、ファーズル・アフメト・パシャの死を受けて、ヒジュラ暦1087年シャアバーン月28日(1676年11月5日)に大宰相に任命された。キョプリュリュ家の婿で、その薫陶を受けて国政に長い経験を持つメルズィフォンルは、メフメト4世の最も強力で影響力のある大宰相の一人となった。", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["ヴァーニー・メフメト・エフェンディの流刑地での死去", "cda714aa"], "d": ["TDV『イスラーム百科事典』のMehmed Efendi, Vânîの項によれば、ウィーン遠征をスルタンに受け入れさせた主な人物の一人とされたヴァーニー・メフメト・エフェンディは、遠征が敗北に終わった後、世論の圧力で失脚し、ブルサのKestel町に流された。ヒジュラ暦1096年ズルカアダ月14日(1685年10月12日)にここで死去し、自ら建てさせたモスクの入口に葬られた。", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["キョプリュリュザーデ・ファーズル・ムスタファ・パシャの大宰相任命と財政改革", "b048570e"], "d": ["TDV『イスラーム百科事典』のKöprülüzâde Fâzıl Mustafa Paşaの項によれば、ヒジュラ暦1101年ムハッラム月11日(1689年10月25日)に大宰相に任命されたファーズル・ムスタファ・パシャは、ジズヤ(人頭税)の徴収方式をシャリーア(イスラーム法)の原則に従って再編し、マンギル(銅貨)のインフレと戦い、宮廷の機関から財源を移して国庫を強化した。さらに地方行政を信頼できる官吏で補強し、中央のディヴァンに似た地方の評議会を設けさせた。", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["マーリカーネ制の施行", "316b8426"], "d": ["TDV『イスラーム百科事典』のMâlikâneの項によれば、17世紀の最後の四半期に戦費の増大と領土の喪失で収入が減少し、国庫は重い財政危機に陥った。1106年(1695年)に施行されたマーリカーネ制では、徴税請負人(ムルテジム)に終身の固定的な徴税の権利が認められ、短期的な搾取に代わって生産を守る誘因がもたらされた。", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["ムスタファ2世の即位", "b53656c7"], "d": ["TDV『イスラーム百科事典』のMustafa IIの項によれば、31歳で即位したムスタファ2世は、大宰相とシェイヒュルイスラームの承認を待たずに治世を宣言し、剣帯の儀式は数日後にエスキ・ジャーミーで行われた。ウィーンの敗北の後に多正面の戦争が続く時期に即位したこのスルタンは、オスマン史において自ら出陣した最後のスルタンとなった。", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Feyzullah Efendi、2度目のシェイヒュルイスラームに任命", "1cf14cff"], "d": ["TDV『イスラーム百科事典』のFeyzullah Efendi, Seyyid項によれば、ムスタファ2世の即位後、ヒジュラ暦1106年シャウワール月11日(1695年5月25日)に2度目のシェイヒュルイスラームに任じられた。8年余り続いたこの在任期間中に、スルタンに対する影響力は次第に増大した。", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Feyzullah Efendi、息子たちを高位に就け、反発が蓄積", "a6398280"], "d": ["TDV『イスラーム百科事典』のFeyzullah Efendi, Seyyid項によれば、シェイヒュルイスラームはムスタファ2世から、息子のFethullah Efendiが自らの後継のシェイヒュルイスラームになるという前例のない勅令を得て、親族を若年のうちに高位に配置した。こうした措置はウラマー層、軍人、イスタンブルの民衆のあいだに広範な不満を生み、首都をエディルネに移すという噂と相まって、1703年のエディルネ事件の素地をつくった。", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["エディルネ事件の発端", "5a106458"], "d": ["TDVの「Edirne Vak'ası」項によれば、俸給(ulufe)を受け取れなかった兵士の蜂起に始まった動きは、短期間のうちにイェニチェリ、メドレセの学生、商工業者、民衆が加わる大規模な反乱に発展した。反乱の主な標的は、国政に過度に干渉したとされるシェイヒュルイスラームのFeyzullah Efendiであった。約6万人の群衆がイスタンブルからエディルネへ行進した。", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Nevşehirli Damad İbrahim Paşa、大宰相に就任", "8d627a6f"], "d": ["TDVの「Damad İbrâhim Paşa, Nevşehirli」項によれば、オーストリアとの和平交渉が続くなか、ヒジュラ暦1130年ジュマーダー・アーヒラ月8日(1718年5月9日)に大宰相の地位に就き、任命されるとただちに戦争を終結させる交渉に向かった。2か月後にパッサロヴィッツ条約が調印された(1718年7月21日)。TDVの表現では、「社会・財政の問題に取り組むことを望み、長年にわたり敗北に終わってきた戦争を忘れさせる平和の時代を待ち望んでいた」という。財政改革を行って兵士の俸給を引き下げ、国庫に大幅な黒字を生み出した。12年間続いた大宰相在任は、その名を冠する時代(チューリップ時代)の政治的枠組みとなった。", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Tulumbacı Ocağı(消防組織)の創設", "f58b0d97"], "d": ["TDVの「Tulumbacı」項によれば、1715年のモレア遠征から戻ったGerçek Dâvudがイスタンブルの火災でポンプ(tulumba)により成果を上げたため、大宰相Nevşehirli Damad İbrahim Paşaは彼に正式な消防組織の設立を命じた。アジェミ・オウランラル兵営に士官6名と兵50名で設けられたこの組織は、1724年に150名、1755年に461名に達した。Dâvudは1733年に没するまで組織の長にとどまった。", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["Mehmed Efendi、ルイ15世に謁見", "0ff5b174"], "d": ["TDVの「Yirmisekiz Çelebi Mehmed Efendi」項によれば、使節はテュイルリー宮殿でフランス王ルイ15世に正式に引見され、アフメト3世の贈り物と書簡を奉呈した。滞在中にヴェルサイユ、トリアノン、マルリーの宮殿のほか、病院、天文台、工房を見学し、見聞したものを図に描いて記録した。", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["Mehmed Efendi、イスタンブルに帰還", "a09a8bba"], "d": ["TDVの「Yirmisekiz Çelebi Mehmed Efendi」項によれば、1年にわたるパリ駐在から戻った使節の見聞は、チューリップ時代の建築趣味に影響を与えた。のちに彼の息子がİbrahim Müteferrikaと共に働いたことは、この使節の最も永続的な遺産である最初のトルコ人の印刷所の創設の素地をつくった。", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Sâdâbâd離宮の造営", "aec9c65e"], "d": ["TDVの「Sâdâbâd」項によれば、キャウトハーネ川のほとりに、フランスの宮殿建築に着想を得た離宮、運河、泉、あずまやからなる広大な遊興・行楽の複合施設が建設された。当時最も人気のある遊興の場となったSâdâbâdは、詩人Nedîmの詩のなかで不朽のものとなった。この施設は1730年のパトロナ・ハリル反乱の際に大部分が破壊された。", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["ロシア軍がデルベントを奪取:ピョートル1世のカスピ海遠征", "c2b269f9"], "d": ["サファヴィー朝がアフガン人の侵入により内乱に陥っていたとき、ロシアのツァーリ、ピョートル1世は、カスピ海沿岸のイラン領を手に入れる目的で遠征に出た。沿岸都市デルベントは目立った抵抗を見せることなくロシア軍に降伏した。TDV『イスラーム百科事典』のDerbend項によれば、この占領は13年続く一時的なロシアの支配の始まりであった。オスマン帝国も同じ混乱を利用してカフカスの西部へ向かった。軍はアストラハンから海路でアグラハン湾に上陸し、そこから沿岸沿いにTarku経由で陸路を進んだ。Tarkuのシャムハルはピョートルを歓待してロシアの臣従に入った。", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Tarkuのシャムハル国の廃止:ロシアの直接統治", "b0f029c6"], "d": ["1722年にピョートルを歓待してロシアの臣従に入ったTarkuのシャムハルAdil-Gireyは、1725年に反乱を起こした。Yeropkinは1725年の秋にTarkuを破壊し、シャムハルは1726年5月中旬に逮捕・追放され、シャムハル国は廃止された。Tarkuとその周辺は、1735年のガンジャ条約まで、ロシアの直接統治下に置かれた。", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["İbrahim Müteferrikaに印刷所設立の許可", "0659dd0a"], "d": ["TDVの「İbrâhim Müteferrika」項によれば、アフメト3世の勅令とシェイヒュルイスラームYenişehirli Abdullah Efendiのファトワーにより、最初のトルコ人の印刷所の設立が許可された。印刷所はイスタンブルのYavuzselim地区で稼働した。Müteferrikaは1747年に没するまでに、23巻、17点の書物を印刷した。", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["最初の印刷書籍『Vankulu Lügati』の完成", "684700e8"], "d": ["TDVの「İbrâhim Müteferrika」項によれば、印刷所の最初の作品であるSıhâhu'l-Cevherîのトルコ語訳(Vankulu Lügati)が1729年初頭に完成した。これはオスマン領内でアラビア文字により印刷された最初の書物であり、トルコの印刷史の始まりとされる。", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Nevşehirli Damad İbrahim Paşaの処刑", "50c64341"], "d": ["TDVの「Damad İbrâhim Paşa, Nevşehirli」項によれば、パトロナ・ハリル反乱の際に宮殿で殺害された大宰相の遺体は、イスタンブルの街路を引きずられ、スルタンアフメト広場のアフメト3世の泉の近くに放置された。12年間の大宰相在任とチューリップ時代はこうして血なまぐさい形で幕を閉じた。", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["アフメト3世の退位、マフムト1世の即位", "a43f5d40"], "d": ["TDVの「Mahmud I」項によれば、反乱者の圧力のもと、アフメト3世は自身と子供たちの安全の保証を得て退位し、甥のシェフザーデ・マフムトを自ら玉座に就けた。叔父の「国事を自らの手に握れ、誰も信用するな」という助言とともに即位したマフムト1世は、まず自分を即位させた反乱者集団の影響力を削ぐことに取りかかった。", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Humbaracı Ahmed Paşa、砲兵組織を改革", "ea3a7c64"], "d": ["TDVの「Humbaracı」項によれば、イスラームに改宗したフランス出身の士官Ahmed Paşaは、大宰相Hekimoğlu Ali Paşaの時代に、俸給制のhumbaracı(擲弾兵・臼砲兵)組織のヨーロッパ式改革に着手した。大宰相に直属し、俸給兵300名とティマール保有兵301名の計601名からなる新しい組織を築いた。当時の技術で臼砲100門と砲弾5万発を製造させた。", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Hendesehâne(工学校の最初の例)の創設", "a77ed1f3"], "d": ["TDVの「Mahmud I」項によれば、Humbaracı Ahmed Paşaはウスキュダルにhumbarahâneとも呼ばれるHendesehâneを設け、宮廷の使用人やbostancıから選んだ学生に、数学と幾何学を基礎とする軍事教育を授けた。この機関は、のちに発展する工学校の最初の例とみなされる。", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["ガンジャ条約:デルベントとバクーのイランへの返還", "ff19d531"], "d": ["オスマンの脅威に対抗してイランとの同盟を求めたロシアは、13年間保持してきたカスピ海沿岸の都市を、ガンジャ条約によって、ナーディル・ハーン(まだシャーの称号は得ていなかった)が指揮するイランに返還した。TDV『イスラーム百科事典』のDerbend項によれば、この撤退は、ロシアが南方で二つの戦線(オスマンとイラン)を同時に抱えることを望まなかった結果であり、数年後のナーディルの即位への道を開く軍事的威信を固めた。ロシア統治下のTarki(Tarku)もこの撤退によりイラン側に戻った(地図ではガンジャ条約の日を用いる)。ロシア統治下のSalyanとŞâbüranもこの撤退によりイラン側に戻る(集落ごとの日付は史料になく、地図ではガンジャ条約の日を用いる——注記付きの近似)。", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["ナーディル・シャー、ムガン平原で即位:サファヴィー朝の事実上の終わり", "4f640979"], "d": ["TDV『イスラーム百科事典』のNadir Şah項によれば、ムガン平原に集まった約2万人のクリルタイは、彼がイランの首長となることを強く求めた。ナーディルは、サファヴィー朝とオスマンの間の戦争の原因となった過激なシーア派の理解を捨て、穏健なジャアファル派を採用することを条件にこの申し出を受け入れ、ヒジュラ暦1148年シャウワール月24日(1736年3月8日)にナーディル・シャーの称号で即位した。これは、2世紀続いたサファヴィー朝が事実上終わり、アフシャール朝が成立したことを意味した。", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["イスタンブルでペストの流行が始まる", "9fa82b56"], "d": ["TDVの「Tâun」項によれば、イスラーム世界で1739年から1743年にかけて猛威を振るったペストの流行は、この時期にイスタンブルをも襲った。同項は、18世紀の流行はそれ以前の世紀に比べて比較的軽く経過したと述べている。流行の時期としては、1713年、1719年、1728-1729年、1759-1765年も数えられる。", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Hocapaşa大火", "321c7d0d"], "d": ["TDVの「Fatma Sultan Camii」項によれば、夜間に発生したHocapaşa大火はBâbıâliとその周辺を荒廃させ、一帯のFatma Sultan Camiiもこの火災で被害を受けたと推測されている。オスマン3世の時代にイスタンブルを襲った大火の一つであるこの災厄は、都市の商業・行政の中心に深刻な被害をもたらした。", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Koca Ragıp Mehmed Paşa、大宰相に就任", "a1846910"], "d": ["詩人・外交官として知られるRagıp Paşaは、オスマン3世により大宰相の地位に就けられた(1757年10月にオスマン3世が没すると職にとどまり、ムスタファ3世から新たに印章を受けた)。七年戦争が続くなか、オスマン帝国をヨーロッパの紛争の外に置く均衡のとれた外交政策をとった。6年続いた大宰相在任中、図書館の設立などの文化活動も重視した。", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Ragıp Paşaの死去", "6bc19323"], "d": ["Ragıp Paşaは6年間の大宰相在任の後に死去した。その死により、ムスタファ3世の時代で最も息の長い、均衡のとれた大宰相在任は終わった。", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["イスタンブル大地震とFâtih Camiiの倒壊", "2475b4dc"], "d": ["TDVの「Fâtih Camii ve Külliyesi」項によれば、1766年の大地震でモスクの主ドームが完全に崩落し、壁も修復不能なほど損傷した。ムスタファ3世の命により、建築家Sarım İbrahim Efendiとİzzet Mehmed Beyの指揮のもと1767年に始まった再建は、従来の設計とは異なる新しい設計で1771年に完成した。", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Baron de Tott主導による短命な砲兵学校の試み", "4192260c"], "d": ["TDVの「Mühendishâne-i Bahrî-i Hümâyun」項によれば、1768年の露土戦争での失敗が技術的な軍事教育の必要性を浮き彫りにした。フランス人士官Baron de Tottの協力で開設された短命な砲兵学校は1772年10月に稼働したが、効果を上げなかった。この試みは、1775年に創設されるMühendishâne-i Bahrî-i Hümâyunの先駆けとみなされる。", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["セリム3世が即位", "00d046d9"], "d": ["アブデュルハミト1世の死去により、甥のセリム3世が即位した。TDV『イスラーム百科事典』のSelim III項によれば、シェフザーデ時代からヨーロッパ軍の改革に関心を抱いていた新スルタンは、即位後まもなく抜本的な刷新計画の策定を開始させた。この計画は数年のうちにニザーム・ジェディードの名で知られることになる。", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["ニザーム・ジェディード改革計画の策定が始まる", "eff78a68"], "d": ["セリム3世は、国家高官や外国人専門家から求めた意見書をもとに、包括的な刷新計画を作成させた。TDV『イスラーム百科事典』のNizâm-ı Cedîd項によれば、この計画は新しい軍の創設にとどまらず、財政、地方行政、外交をも含む広範な改革運動へと発展した。計画はその後15年間、支持者と反対者の双方を生むことになる。", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["ヨーロッパ各国の首都に常駐大使館を設置", "2e9dc8a1"], "d": ["セリム3世は、オスマン帝国史上初めて、ヨーロッパの主要な都市に常駐する大使を派遣した。TDV『イスラーム百科事典』のElçi項によれば、この措置は、それまで臨時の一回限りの使節団で行われていたオスマン外交に恒久的な組織を与えた。新設の大使館の主な任務は、ヨーロッパの政治・軍事の動向を定期的にイスタンブルに報告することであった。", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["İrad-ı Cedîd財庫の設置", "ae5c8ce2"], "d": ["ニザーム・ジェディード軍と改革計画の費用を賄うため、別個の財庫が設けられた。TDV『イスラーム百科事典』のEsham項によれば、新財庫の収入には、一部のmukataa(徴税請負地)の国家による直接経営と、esham(終身年金債券)の売却の統制が含まれていた。この措置は、従来の財政制度の外に新たな財源をつくる試みであった。", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["カバクチュ・ムスタファの反乱が始まる", "b98eee17"], "d": ["ニザーム・ジェディードに対して蓄積した不満は、ヤマク(要塞守備の補助兵)がカバクチュ・ムスタファの指導のもとに蜂起したことで爆発した。TDV『イスラーム百科事典』のKabakçı İsyanı項によれば、反乱者はたちまちイスタンブルの支配を握り、ニザーム・ジェディード支持派の国家高官の首を要求した。蜂起は数日のうちにセリム3世の廃位に至った。", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["セリム3世が廃位", "ff2c30ec"], "d": ["カバクチュ・ムスタファの反乱の圧力のもと、シェイヒュルイスラームから得たファトワーによりセリム3世は廃位された。TDV『イスラーム百科事典』のSelim III項によれば、この決定は18年続いた改革期が事実上終わった瞬間であり、ニザーム・ジェディード軍も短期間のうちに廃止された。セリムはトプカプ宮殿で拘束下に置かれた。", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["ムスタファ4世が即位", "8f1ac86c"], "d": ["セリム3世の廃位の直後、甥のムスタファ4世がスルタンに宣言された。TDV『イスラーム百科事典』のMustafa IV項によれば、新スルタンは、反乱を支持したニザーム・ジェディード反対派の影響下で統治を始めた。短期間に終わったこの時期は、中央の権威が著しく弱まった不安定な局面であった。", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Alemdar Mustafa Paşa、軍を率いてイスタンブルに入る", "0cad3dea"], "d": ["ルセ(ルスチュク)のアーヤーンAlemdar Mustafa Paşaは、セリム3世を再び玉座に就ける目的で、軍を率いてイスタンブル近郊に到着した。TDV『イスラーム百科事典』のAlemdar Mustafa Paşa項によれば、その入市はムスタファ4世自身が出迎えたが、数日のうちに宮廷内の勢力均衡は完全に変わることになる。この入市は、セリムの死と新たな即位に帰結する一連の出来事の発端となった。", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["セリム3世が殺害される", "e452f5f6"], "d": ["Alemdar Mustafa PaşaがBâbıâliを掌握した日、ムスタファ4世の命によりセリム3世は宮殿で殺害された。TDV『イスラーム百科事典』のSelim III項によれば、これは廃位された君主を再び玉座に就けようとする試みを防ぐために下された決定であった。セリムの死は、同日のマフムトの即位に帰結した。", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["マフムト2世が即位", "661c1974"], "d": ["セリム3世の殺害の後、王家で唯一の男子として残ったマフムトが、Alemdar Mustafa Paşaの支持を得て即位した。TDV『イスラーム百科事典』のMahmud II項によれば、新スルタンは治世の最初の数か月を、自らを即位させたAlemdarの後見のもとで、アーヤーンと中央のあいだの均衡を再建しようと努めながら過ごした。この時期は、その後20年に及ぶ抜本的な改革過程の出発点となった。", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["Sekbân-ı Cedîd軍の創設", "6f9eb5e4"], "d": ["Alemdar Mustafa Paşaは、廃止されたニザーム・ジェディードに代わって、ヨーロッパ式の装備を備えた新しい軍を設けさせた。TDV『イスラーム百科事典』のSekbân-ı Cedîd項によれば、3個連隊からなるこの部隊はイェニチェリの目には直接の脅威と映り、創設のわずか数か月後にイェニチェリの蜂起で排除された。", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["İbrâil陥落——ドナウ防衛線に最初の大きな綻び", "ee519321"], "d": ["1806年に始まったロシアとの戦争で、ドナウ北岸のİbrâil要塞はカミンスキー伯指揮下のロシア軍に包囲・砲撃された。内部には歩兵4100、騎兵1100、大砲260門があったが、要塞は食糧不足のためエッセン将軍に降伏した。ドナウ防衛線の北端はこうして開かれた。", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["ルスチュクの降伏——ドナウ南岸も失われる", "084062e8"], "d": ["ルスチュクはカミンスキー伯指揮下のロシア軍の長く血なまぐさい包囲に抵抗したが、守備隊と民間人が安全に市を去ることを条件に降伏した。ドナウ南岸で最も堅固な要塞都市の陥落は、戦争の流れをロシアに有利に転じさせた。", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["Eşkinci Ocağı(新式軍)の創設", "67c56759"], "d": ["マフムト2世は、イェニチェリ軍団の中から選んだ兵でヨーロッパ式の訓練を受ける新しい部隊を設けさせた。TDV『イスラーム百科事典』のEşkinci Ocağı項によれば、部隊は1826年6月12日に訓練を始めたが、イェニチェリはこれを自らの軍団の終わりとみなした。3日後に勃発した反乱は、Eşkinci Ocağıの短い命をも終わらせた。", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["Asâkir-i Mansûre-i Muhammediyye(ムハンマド常勝軍)の創設", "14b84a7e"], "d": ["イェニチェリ軍団の廃止の直後、マフムト2世は、その代わりに常備でヨーロッパ式の教育を受けた新しい軍を設けさせた。TDV『イスラーム百科事典』のAsâkir-i Mansûre-i Muhammediyye項によれば、この軍は階級制度、教育課程、俸給制度により、それ以前の試みとは異なって恒久的な機関となった。軍は後年、タンジマート期のニザーミイェ軍に発展することになる。", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["ベクタシュ教団の閉鎖", "f7d9a367"], "d": ["イェニチェリ軍団の廃止と同時に、軍団と宗教上の結びつきが知られていたベクタシュ教団も禁止された。TDV『イスラーム百科事典』のBektaşîlik項によれば、小規模なテッケの一部のシェイフが処刑される一方、Hacı Bektaş道場のシェイフはアマスヤに流刑となり、テッケはナクシュバンディー教団の管理に移された。教団はこの重い打撃にもかかわらず、組織を秘密裏に維持した。", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["扇事件——占領の口実", "e949001e"], "d": ["フランスのアルジェに対する古い穀物債務が支払われないために緊張した会談で、ダイ(Dayı)のHüseyinは、手にした扇でフランス領事デュヴァルを打った。債権をめぐる紛争から生じたこの事件は、3年後に始まる占領の公式の口実とされた。", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["フランスによるアルジェ沿岸の封鎖——3年に及ぶ包囲", "d0ba97a5"], "d": ["扇事件の後、フランスはアルジェ沿岸を封鎖した。封鎖は3年続き、オジャク(軍団)の海上交易と収入源は枯渇し、抵抗力は占領が始まる前に削がれた。", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["トルクメンチャイ条約:エレヴァンとタリシュのロシアへの移行", "abffcfdb"], "d": ["1826-1828年の露・イラン戦争がイランの大敗に終わると、トルクメンチャイで調印された条約により、エレヴァン・ハン国とナヒチェヴァン・ハン国、およびカスピ海沿岸のタリシュ地方(Lenkeran、Astara)がロシアに譲られた。さらに重い賠償金が課された。TDV『イスラーム百科事典』のRevan項によれば、この損失は、カフカスにおける露・イランの国境が今日まで大部分有効であり続ける形で引かれた瞬間であり、アルメニア人住民のエレヴァンへの移住をも促した。この条約により、エレヴァン・ハン国(Eçmiyadzin、Iğdır、Norapat、Beri)とナヒチェヴァン・ハン国(Culfa、Şerur)がロシアに移った。", "847d76d5"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["İbrâilの2度目の陥落——ツァーリ・ニコライが要塞の前に", "eb6a8741"], "d": ["1812年にオスマン側に返還され、1817-1818年に再び要塞化されたİbrâilは、守備兵4000と大砲278門を擁していた4月に包囲された。守将Ebûbekir Paşaは新たな防衛線を築き、ツァーリのニコライ1世は5月末に自ら要塞の前に到着した。市はロシアの占領を受けたが、エディルネ条約により返還されてワラキア公国に委ねられることになる。", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["フェズを公式の被り物と宣言", "f55be4eb"], "d": ["マフムト2世は、官吏と兵士の服装に抜本的な変更を加え、ターバンに代えてフェズを公式の被り物と宣言した。TDV『イスラーム百科事典』のFes項によれば、この決定はhatt-ı hümâyun(親書)で布告され、Asâkir-i Mansûre-i Muhammediyyeの西洋式改革とともに実施に移された。この変更は、伝統的な服装の序列を終わらせることをも意味していた。", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["アハルツィヘのロシアへの割譲——チルドゥル州の中心が失われる", "e2e00b2a"], "d": ["1578年のチルドゥルの戦い以来オスマンの統治下にあり、チルドゥル州の中心であったアハルツィヘ(Ahıska)は、1828-1829年の戦争の末に調印されたエディルネ条約によりロシアに割譲された。町が失われたことは民衆に深い悲しみを生み、多くの哀歌の題材となった。この出来事により、Ahılkelek、Zazalo、Ts'q'altbila(Ahıska–Ahılkelek地方)がロシアに移った。", "bab87a04"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["シディ・フェルーシュ上陸——フランス軍がアルジェリアの地に", "33327553"], "d": ["3年間の封鎖の後、ブルモン伯指揮下のフランスの上陸軍は、アルジェの西にあるシディ・フェルーシュの入り江に兵を上陸させた。市に向けて進軍した部隊は3週間のうちに防衛線を破り、7月4日に市を見下ろす皇帝要塞が陥落し、翌日にダイのHüseyinが降伏した。", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["ダイHüseyinの追放——アルジェのオジャクの事実上の終焉", "e122403b"], "d": ["降伏条件に従い、最後のアルジェのダイであるHüseyinは、家族と財宝とともに市から出され、ナポリに送られた。1519年にセリム1世(ヤヴズ)に帰属し、300年にわたり地中海で最も強力なオスマンの海軍基地であったオジャクの統治は、こうして終わった。", "bf7169cf"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["ロシア軍がワラキアとモルダヴィアから撤退——6年に及ぶ占領の終わり", "efdb0275"], "d": ["1828-1829年の露土戦争でロシアはワラキアとモルダヴィアを占領し、エディルネ条約の後も、戦争賠償金が支払われるまで撤退しなかった。1834年1月に賠償金が500万に引き下げられると、ロシア軍はMemleketeyn(両公国)を撤退し、二つの公国に新たなヴォイヴォダが任命された。オスマンの宗主権は紙の上では戻ったが、ロシアはReglement Organiqueによって築いた影響力を保った。", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["Redif-i Asâkir-i Mansûre組織の創設", "15947493"], "d": ["Asâkir-i Mansûre-i Muhammediyyeを支える予備戦力として、Redif組織は1834年7月8日付の規則により創設された。TDV『イスラーム百科事典』のRedif項によれば、陸軍総司令官Koca Hüsrev Paşaの指揮のもと、地方のカザーで1個あたり約1400人の大隊が編成された。この組織は、常時の勤務に就かせることなく、地方の治安をも支えるように設計されていた。", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["外務省(Hariciye Nezareti)の創設", "750c6c7d"], "d": ["マフムト2世は、外交を担っていたReisülküttâblık職を廃止し、その代わりにHariciye Nezaretiを設けた。TDV『イスラーム百科事典』のHariciye Nezâreti項によれば、新省の初代大臣にはMehmed Âkif Paşaが就き、組織はウィーン駐在大使Rıfat Beyの邸宅で活動を始めた。この措置は、オスマンの外交が近代的な省の原則に従って運営される端緒となった。", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["Meclis-i Vâlâ-yı Ahkâm-ı Adliyyeの創設", "69db056e"], "d": ["マフムト2世は、準備される法令・規則を審議する上級の会議として、Meclis-i Vâlâ-yı Ahkâm-ı Adliyyeを設けさせた。TDV『イスラーム百科事典』のMeclis-i Vâlâ-yı Ahkâm-ı Adliyye項によれば、会議は1838年3月31日に実際に活動を始め、その後のタンジマート改革のほぼすべてがこの機関を通じて準備・審査された。この機関は、近代オスマン官僚制の最も重要な中枢の一つとなった。", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["シノプ襲撃", "5947e93f"], "d": ["ロシア黒海艦隊は、ナヒーモフ提督の指揮のもと、宣戦布告なしにシノプ港に停泊するオスマン艦隊を襲撃した。12隻の艦船が沈み、2000人を超える兵士が殉職し、艦隊司令官Osman Paşaは捕虜となった。TDV『イスラーム百科事典』のSinop項によれば、襲撃では市内でも7つのマスジド、2つの学校、247軒の家、170軒の店が焼け、ムスリム5人とキリスト教徒16人の民間人が命を落とした。ヨーロッパの世論で「シノプの惨劇」として反響を呼んだこの出来事は、イギリスとフランスが数か月のうちにオスマン側に立って参戦する直接の引き金となった。", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Tasvir-i Efkâr紙の刊行", "506c98e2"], "d": ["Şinasiが発行したTasvir-i Efkârは、Takvîm-i Vekāyi'、Cerîde-i Havâdis、Tercüman-ı Ahvâlに次ぐ4番目のトルコ語新聞として刊行を始めた。TDVの「Tasvîr-i Efkâr」項によれば、この新聞は、のちに主筆を務めたNâmık Kemalの時代に、新オスマン人運動の機関紙となった。", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["新オスマン人協会の結成", "335fb02d"], "d": ["Mustafa Fâzıl Paşaの主導でヨーロッパに逃れたオスマンの知識人たちは、13条の規約により、「若きトルコ」の名で組織された。TDVの「Yeni Osmanlılar Cemiyeti」項によれば、この集団はパリ、ロンドン、ジュネーヴでMuhbirやHürriyetなどの新聞を発行し、立憲政治の要求を広めた。", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["Şûrâ-yı Devlet(国家評議会)の創設", "b863b306"], "d": ["Meclis-i Ahkâm-ı Adliyyeが二つに分けられ、行政事務を担うŞûrâ-yı Devletと、司法を扱うDîvân-ı Ahkâm-ı Adliyyeが設けられた。TDVの「Şûrâ-yı Devlet」項によれば、フランスのコンセイユ・デタを手本としたこの機関の初代議長にMidhat Paşaが就いた。目的は立法・行政・司法の分離であった。", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["Darülfünun設立の勅令が出される", "513704bf"], "d": ["大宰相Âli Paşaと教育大臣Saffet Paşaが準備した勅令により、Darülfünunは正式に設立された。最初の講義はそれ以前の1863年に始まっていた。TDVの「Darülfünun」項によれば、この機関は1870年2月に、Hoca Tahsin Efendiを学長として、哲学・文学、理学、法学の各部で実際に教育を開始した。", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Mecelle-i Ahkâm-ı Adliyye(民法典)の編纂が始まる", "8abdcbee"], "d": ["Dîvân-ı Ahkâm-ı Adliyye議長のAhmed Cevdet Paşaを長として設けられたMecelle委員会は、ハナフィー派法学を基礎とする民法典の準備に着手した。TDVの「Mecelle-i Ahkâm-ı Adliyye」項によれば、16編1851条からなるこの書の最終分冊は1876年9月15日に完成して施行された。イスラーム法の最初の法典化とされる。", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["「祖国あるいはシリストラ」が上演され、Nâmık Kemalが流刑に", "3861284c"], "d": ["Nâmık Kemalの愛国をテーマとする戯曲がゲディクパシャ劇場で上演されると、観客は「祖国万歳、ケマル万歳」と叫んで街頭にあふれた。TDVの「Nâmık Kemal」項によれば、政府はこのデモに怯えてİbret紙を閉鎖し、1873年4月6日にNâmık Kemalを裁判にかけることなくキプロス(マゴサ)に流刑とした。", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["アブデュルアズィズが不審な状況で死去", "85816692"], "d": ["廃位の後、自らの望みでフェリイェ宮殿に移された(1876年6月1日)アブデュルアズィズは、6月4日、自室で手首の血管を切られた状態で発見された。大使館付きの医師も加わった19人の医師団は曖昧な表現の報告書を作成し、死は6月6日に新聞で自殺と発表された。しかしアブデュルハミト2世が開かせた調査は、死は自殺ではなく殺人であるとの結論に達し、被告たちは1881年にユルドゥズ法廷で裁かれた。この問題は歴史叙述において今日でも議論がある。", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["Midhat Paşa、大宰相を罷免され流刑に", "b5247b06"], "d": ["憲法(Kanun-i Esasi)の立案者である大宰相Midhat Paşaは、憲法公布の6週間後、アブデュルハミト2世により解任され、一夜のうちに国外に追放された。TDV『イスラーム百科事典』のMidhat Paşa項によれば、罷免は、スルタンが憲法中の自らの権限を制限する条項に抱いた不快と結びつけられる。パシャはまずナポリへ、次いでヨーロッパの各都市へ赴いた。", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["アブドゥルアズィーズ・イブン・サウード、リヤドをラシード家から奪回", "75eb8830"], "d": ["10年前にクウェートに亡命していたサウード家の若きアブドゥルアズィーズは、小部隊でリヤドを急襲し、アール・ラシード(Şammar)の総督代理を殺害して市を奪取した。TDV『イスラーム百科事典』のRiyad項によれば、ラシード家が次第に弱体化し市に援軍を送れなかったことが、この襲撃の成功を容易にした。この出来事は、その後の30年間に今日のサウジアラビアの中核を形成することになる第二次サウード国の成立の瞬間とされる。", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["行動軍(Hareket Ordusu)のイスタンブル入城", "41c8304c"], "d": ["テッサロニキから出発した、大半が統一と進歩委員会に連なる部隊からなる行動軍は、3月31日事件を鎮圧するためイスタンブルに入った。TDV『イスラーム百科事典』のHareket Ordusu項によれば、司令官はMahmud Şevket Paşaが務め、参謀長はKolağası Mustafa Kemalが務めた。短い戦闘の後、市内の治安は回復された。", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["最後のオスマン帝国議会(Meclis-i Mebusan)の解散", "2b709269"], "d": ["連合国軍によるイスタンブルの正式な占領と多くの議員の逮捕の後、議会は機能できなくなり、メフメト6世の勅令で正式に解散された。TDV『イスラーム百科事典』のMeclis-i Mebusan項によれば、この解散は、オスマンの立憲議会の伝統が事実上終わったことを象徴した。閉鎖は、アンカラで新たな国民議会を召集する必要性を強めた。", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["トルコ大国民議会の開会", "6eab539d"], "d": ["イスタンブルのMeclis-i Mebusanの解散の後、議員たちはアンカラに集まってトルコ大国民議会を開会し、Mustafa Kemal Paşaが議長に選ばれた。TDV『イスラーム百科事典』のTürkiye Büyük Millet Meclisi項によれば、議会は立法と行政の両権を自らに集める異例の性格を帯びた。この開会は、民族闘争の政治的・制度的中心がアンカラに移った転換点となった。この出来事により、コンヤ、スィヴァス、カイセリ、エスキシェヒル、エルズルム、トラブゾン、サムスン、ディヤルバクル、ヴァン、マラティヤ、デニズリ、ウスパルタを含む124の集落(トルコの占領下にない地域)がTBMM政府の統治下に入った。", "47a80fa7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["İzvornik(ズヴォルニク)要塞の征服", "657c465a"], "d": ["ドリナ川沿いのİzvornik要塞は1460年にオスマンにより征服された。TDV『イスラーム百科事典』によれば、行政・軍事の面で有利な位置にあったためまずカザーの中心とされ、1480年に同名のサンジャクの中心となり、1491年に石の城壁で固められ、6つのモスク、8つのテッケ、ハンマームを備えた重要な行政・商業の中心となった。", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["カーシム・ハンの死、ダニヤル・ハンの即位(カシモフ・ハン国)", "522fd0fd"], "d": ["ハン国の創設者カーシム・ハンが873年/1468年に没すると、息子のダニヤルが後を継いだ。ダニヤルは1486年まで統治した。", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["ディウ沖海戦——インド洋におけるポルトガルの優位", "1778d347"], "d": ["グジャラート・スルタン朝のためにこの地方を治めていたマリク・アヤーズの、マムルーク朝の支援を受けた艦隊は、この沿岸に補給基地を築こうとしていたポルトガルのインド総督フランシスコ・デ・アルメイダの艦隊に、ディウ沖で大敗を喫した。この敗北はポルトガルにインド洋での恒久的な海上優位をもたらし、マムルーク朝・グジャラートの海軍力を打ち砕いた。オスマンが1517年以後に引き継ぐ紅海・インド洋での争い(ジッダの防衛、1538年のディウ包囲)の背景をなす力の不均衡の始まりとされる。", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["カレンダル・シャーの反乱", "f60f6ca4"], "d": ["アナトリアの財政難、新しい行政措置への不満、サファヴィー朝の宣伝の影響により、Çiçekli、Akça Koyunlu、Masadlı、Bozokluなどの大きなトルクメン部族と、それ以前のBaba Zünnûn反乱の残党がカレンダル・シャーの周りに集まり、約3万人の勢力に達した。反乱者はまずルーム(Rum)のベイレルベイを破った。大宰相Makbul İbrâhim Paşaが兵を集めて彼らの権利を約束したことでカレンダルへの支持は薄れ、反乱はエルビスタン周辺で鎮圧され、カレンダル・シャーとVeli Dündarは1527年6月に殺された。", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["Şehrizor(シャフリゾール)の征服——Zalm要塞の奪取", "4320d9b8"], "d": ["スレイマン1世のナヒチェヴァン遠征の間、バグダードのベイレルベイOsman Paşaは、Şehrizor地方を奪取するよう命じられていた。彼の死でバグダードのベイレルベイとなったBaltacı Mehmed Paşaは、地方の中心要塞Zalmを包囲し、1554年8月22日(ヒジュラ暦961年ラマダーン月23日)に奪取した。こうしてザグロス山脈の西斜面のŞehrizor盆地はオスマンの統治下に入り、バグダードとクルディスターンの連絡が確保された。地方はまずサンジャクとされ、Murad Beyに与えられた。1563年にベイレルベイMuzaffer Paşaは新たな州の中心としてGülanber要塞を築いた。要塞は1623年にシャー・アッバースの命で破壊され、1638年にHüsrev Paşaの時代に再建されることになる。", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["カシモフ・ハン国の君主のキリスト教への改宗とハン位の剥奪", "a1a8eeb9"], "d": ["ハン国の首長であった君主は「セミョーン(Simeon)」の名を受けてキリスト教徒となった。ロシア人はムスリムの臣民の反発を考慮して、彼をハン位から退けた。この人物はまもなくイヴァン雷帝により、「ツァーリとロシアの大公」の称号でモスクワの名目上の君主と宣言された(1575年)——カシモフ・ハン国とモスクワの王座との間で最も印象的な交差である。", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["フェザーン(Fizan)サンジャクのトリポリへの編入——ムルズクとサハラの隊商の要衝", "2e6554a4"], "d": ["トリポリのベイレルベイ領の圧力の結果、サハラの隊商の要衝であるフェザーンは、ムルズクを中心にオスマンの宗主権を受け入れた。TDV『イスラーム百科事典』のFizan項によれば、地域を治めていたEvlâd-ı Muhammed王朝は、定期的に税を納めることを条件に内政の自由を認められた。フェザーンは1551年に獲得されたトリポリ州に属するサンジャクとして組織された。こうしてトリポリ-ムルズク-ボルヌ線上の奴隷、金、ラクダの交易がオスマンの管理下に入った。この間接統治は、1711年にカラマンリー朝の、1842年には直接のカザー組織の手に渡ることになる。", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["ナヒチェヴァンとオルドゥバードがオスマンの統治下に入る", "24d939b3"], "d": ["1583年にエレヴァンが奪取されてベイレルベイ領の中心とされた後、アラス川流域を南東に下った部隊がナヒチェヴァンとオルドゥバードをオスマンの統治に結びつけ、二つの町は新設のエレヴァン州のサンジャクとなった。TDV『イスラーム百科事典』のNahcıvan項によれば、市における最初の恒久的なオスマン統治はこの戦争の間に確立された。1553年のナヒチェヴァン遠征では市は奪われたものの略奪されて放棄されただけであった。こうしてエレヴァンとタブリーズの間の軍用路が開かれ、同年9月にはタブリーズに入ることができた。シャー・アッバースは1603年にナヒチェヴァンを奪い返すことになる。", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["Deli Hasan Paşaの反乱とボスニアのベイレルベイ職による懐柔", "144f3f2d"], "d": ["ジェラーリーの指導者Karayazıcı Abdülhalimが1602年に没した後、運動の首領となった弟のDeli Hasanは、続くオーストリアとの戦争がジェラーリー集団に与えた行動の自由を利用してキュタヒヤを侵し、アフヨンカラヒサルに向けて進軍した。国家がオーストリアとイランの両戦線を同時に抱えていたこの時期に、問題は「穏やかに」解決された。Deli Hasanにパシャの位とボスニアのベイレルベイ職が与えられ、反乱運動は1603年に正式に終結させられた。", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["ロシア軍によるカシモフ市の占領、ウラズ・ムハンマド・ハン", "b3f0bd34"], "d": ["ロシアの動乱時代(スムータ)の余波として、ロシア軍はカシモフ(Kâsım)市を包囲して占領し、住民の大半を剣にかけた。ハン国の首長であったウラズ・ムハンマドは、偽ドミトリー2世を支持したため標的とされた。翌年(1610年)、彼自身も陰謀により殺された。", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["アゾフ要塞のドン・コサックへの喪失", "ba068b2f"], "d": ["ドン・コサックは1637年4月21日に包囲したアゾフ要塞を2か月後に奪取した。黒海北東の門であり、ドン交易の鍵であったこの要塞が、初めてオスマンの手から離れた。TDV『イスラーム百科事典』のAzak項によれば、コサックは要塞を1637年に奪い、1641年にDeli Hüseyin Paşa指揮下の3か月に及ぶ大規模な包囲に耐え、1642年にクリム・ハンMehmed Girayの到来によってようやく要塞を明け渡した。国家はそのときバグダード戦線にかかりきりであった。要塞を5年間保持できなかったことは、黒海が「オスマンの湖」であるという性格の最初の亀裂である。", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["リムノス島とサモトラキ島の奪回", "c445553b"], "d": ["1657年8月31日のボズジャアダ(テネドス)の奪回の後、Köprülü Mehmed Paşaは艦隊を北へ向け、ヴェネツィアが16か月保持していたリムノス島とサモトラキ島を取り戻した。TDV『イスラーム百科事典』のLimni項によれば、島は1656年7月にヴェネツィアの手に渡り、1657年11月に奪回された。こうしてダーダネルス海峡の入口におけるヴェネツィアの封鎖は完全に破られ、イスタンブルの穀物の道が再び確保された。大宰相が非常大権をもって就いた最初の年の、最も具体的な成果である。", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["クニンのヴェネツィアへの喪失——166年間のダルマチア国境要塞が陥落", "252406b7"], "d": ["1683年のウィーンでの敗北の後、多方面に広がった戦争で、ヴェネツィア軍はダルマチアの内陸に進んだ。ダルマチア総督ジローラモ・コルナーロが包囲したクニンは、12日間の包囲の後、ベイレルベイMehmed Paşaにより明け渡された。クニンは、1522年にGazi Hüsrev Beyが征服し、166年間オスマンの手にあったダルマチア国境線の要の要塞であり、その喪失は地方の大部分をヴェネツィアに開くことになった。", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["バスラのイラン占領からの奪回", "5b10c5c1"], "d": ["カリーム・ハーン・ザンドの弟サーディク・ハーンが1776年に奪取したバスラは、カリーム・ハーンが1779年3月2日に没した後、イランで王位争いが始まったため明け渡された。サーディク・ハーンは王位を主張してイランに戻った。市は短期間Müntefik部族の手にあった後、再びオスマンの統治下に入った。シーラーズから戻った元ムテセッリムSüleyman Ağaはバスラ総督の職を求め、Büyük Süleyman Paşaの名でバスラ、バグダード、Şehrizorの総督となった。湾岸交易はオスマンの管理に戻った。占領期には交易の一部がクウェートに移り、1778年からは砂漠の郵便もクウェートから出されていた。", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["ティムール・シャーの死、ザマーン・シャーの即位(ドゥッラーニー朝)", "c3effdb2"], "d": ["20年以上にわたり国内を固めてきたティムール・シャーの死により、カンダハール・ヘラート・カーブルの総督である3人の兄弟が王位を争った。首都を握るカーブル総督ザマーン・シャーが1793年5月20日にシャーとなった。この継承の危機は、王朝の分裂過程の事実上の始まりである。", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa——ハワイにおける伝統的カプ制度の廃止", "0b10e1d8"], "d": ["カメハメハ1世の死の6か月後、新王リホリホは母カアフマヌの支持を得て、男女別々に食事をするという禁(ʻaikapu)をあえて破った。「ʻAi Noa」(自由な食事)として知られるこの行為は、伝統的なカプの宗教・法の制度を正式に終わらせた。島々の古い神殿(heiau)は短期間のうちに破壊された。西洋の宣教師の到来(1820年)以前における最大の宗教・政治上の断絶である。", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["ロンドン議定書——ギリシアの独立の承認", "4c7b4b72"], "d": ["イギリス、フランス、ロシアがロンドンで調印した議定書は、エディルネ条約が定めていた自治を超えて、ギリシアを独立国家として承認した。条項:モレア半島、アッティカ、エヴィア(Eğriboz)とキクラデス諸島が新国家に譲られた。国境はアルタ-ヴォロス線に引かれた。オスマン帝国への賠償金の支払いが定められた。国家の統治形態は「独立した君主制」とされた。これは帝国から離脱した最初の独立国家であり、その後のバルカンの独立の法的な先例となった。ロンドン議定書により独立が承認されたギリシアには、キクラデス諸島(ナクソス、Istendil、サントリーニ、パロス、Değirmenlik、シロス、ミコノスなど)が含まれた。", "920bfab9"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["アブドゥッラー・ブン・ラシード、ハーイル首長国を掌握——シャンマル(ラシード)王朝の成立", "fb513b8a"], "d": ["1818年にメフメト・アリー・パシャの軍がディルイーヤを陥落させたことで、ジャバル・シャンマル地方はサウード家の支配を離れ、首長国はİbn Ali家の手に残った。オスマンの支配の再確立を支持したアブドゥッラー・ブン・ラシードは、兄弟のUbeydとともにİbn Ali家に対して始めた闘争に1835年に勝利して、ハーイル首長国を掌握し、ラシード王朝の支配を確立した。", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["ハワイ最初の成文憲法が公布", "401a8a1d"], "d": ["王国最初の完全な成文憲法が公布された。国王の権限を制限し、代議制の議会を設けたこの文書は、ハワイを立憲君主制に変えた。", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["銃剣憲法——カラカウア王の権限が削がれる", "4953363b"], "d": ["武装した民兵集団がカラカウア王を脅し、王国の権限を大幅に削ぐ新しい憲法に署名させた。この文書は「銃剣憲法」(Bayonet Constitution)として知られ、王位を事実上白人入植者のエリートの管理下に置いた。", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["ジョージ・ツポウ1世の死、ジョージ・ツポウ2世の即位(トンガ)", "b56e2b32"], "d": ["建国の王ジョージ・ツポウ1世の死により、曾孫のジョージ・ツポウ2世が即位した。戴冠式は1893年3月17日にヌクアロファで行われた。", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["ニュージーランド、女性に参政権を認めた最初の自治国に", "0d277cde"], "d": ["総督グラスゴー卿が署名した新しい選挙法により、ニュージーランドは、女性に議会選挙での投票権を認めた世界で最初の自治国となった。", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["ハワイ共和国が宣言される", "4346bd5d"], "d": ["1893年にリリウオカラニ女王を倒した陰謀者たちは、暫定政府を正式な共和国に変えた。サンフォード・ドールが大統領と宣言された。この過渡的な体制は1898年のアメリカによる併合まで続いた。", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["ニュージーランドの境界がクック諸島とニウエを含むよう拡大", "d0370a33"], "d": ["ニュージーランドの境界は、クック諸島(ラロトンガ、アイツタキと南部の島々、および北クック諸島)とニウエを含むよう拡大された。これらの島々はニュージーランドに属する領域となった。", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["ジョージ・ツポウ2世の死、サーロテ・トゥポウ3世の即位(トンガ)", "a3084f3b"], "d": ["ジョージ・ツポウ2世は結核で死去した。18歳の娘サーロテは翌日に女王と宣言され、戴冠式は1918年10月11日に行われた。", "a63672b5"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["ホラズム人民共和国が宣言される", "0a6b79f9"], "d": ["1917年の10月革命後、ヒヴァ・ハンが倒された後に、ホラズム人民共和国が宣言された。", "1934b071"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["セーヴル条約——帝国の分割文書", "64980d7b"], "d": ["オスマン政府が連合国と調印し、帝国を事実上解体する文書。条項:東トラキアとイズミル地方はギリシアに。東アナトリアには独立のアルメニアと自治のクルディスターンが構想された。シリアはフランスに、イラクとパレスチナはイギリスに委任統治として委ねられた。海峡は国際委員会に移された。軍は5万700人に削減され、カピチュレーションが復活し、財政は連合国の管理下に置かれた。アンカラの大国民議会は条約を一切認めず、調印者を祖国への反逆者と宣言した。文書は発効せず、1923年にローザンヌ条約がこれに代わった。地図に対応するものがないのはこのためである——セーヴル条約は法的に一度も適用されなかった。", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["赤軍がブハラ市に入る——最後のアミール、アーリム・ハンが退位", "f8f5bfcf"], "d": ["赤軍は1920年9月2日にブハラ市に入り、最後のマンギト朝アミールであるアーリム・ハンは退位させられた。アミールは国の東部のドゥシャンベに退き、半年間そこからソヴィエトとの戦いを指揮した。赤軍は1921年2月21日にドゥシャンベを奪取し、アミールはさらに東へ、そこからアフガニスタンに逃れた。ハン国は1920年10月6日に正式に廃止された(ブハラ人民ソヴィエト共和国を参照)。", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["ブハラ人民ソヴィエト共和国が宣言される", "ef579627"], "d": ["赤軍が1920年8月28日から31日にかけてブハラ首長国を倒し、アミールのアーリム・ハンを東ブハラに逃走させた後、Feyzullah Hocayevを首班とするブハラ人民ソヴィエト共和国が宣言された。", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["タンヌ・トゥヴァ人民共和国が独立を宣言", "8710ea3d"], "d": ["トゥヴァ人民革命党の主導で独立が宣言された。最初の憲法の第1条は、国家が「国際関係においてソヴィエト・ロシアの庇護のもとで」行動すると定めていた。この出来事により、クジル(ベロツァルスク、タンヌ・トゥヴァ)はタンヌ・トゥヴァ人民共和国に移った。", "dc0ac64a"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["ブハラ人民ソヴィエト共和国の新憲法が採択", "fb17bf39"], "d": ["ロシアの1918年憲法とは異なり、土地・生産手段の私有を認め、プロレタリアでない者にも選挙権を与える新憲法が採択された(退位したアミールの親族と大地主を除く)。", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["ホラズム・ソヴィエト社会主義共和国への転換", "14a1d26f"], "d": ["国は名称と地位を変更してホラズム・ソヴィエト社会主義共和国となり、行政・法制度はソヴィエト制度に従って再編された。", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["タンヌ・トゥヴァ政府が実際に職務を開始", "22ea1516"], "d": ["1922年2月の最初の党会議の後に組織された政府が、実際に職務を開始した。", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["タンヌ・トゥヴァ最初の大フラル(大会議)が招集", "80fe15f2"], "d": ["国の最初の大フラル(人民議会)が招集された。これは国家の制度化の過程における最初の大規模な代表者会議である。", "e8cf06ac"]}
});
